fn default_positive_outcome() -> Option<f64> {
    Some(0.012)
}

fn default_risk_veto_volatility_threshold() -> f64 {
    0.08
}

fn default_min_replay_examples_required() -> usize {
    10
}

fn default_min_examples_per_member_required() -> usize {
    2
}

fn default_replay_coverage_target_min_total() -> usize {
    10
}

fn default_min_validated_label_ratio_required() -> f64 {
    0.5
}

fn default_input_path() -> Option<String> {
    Some("examples/minimal_ai_committee_core_sample.json".to_string())
}

fn default_style_mapping_mode() -> StyleMappingMode {
    StyleMappingMode::None
}

fn local_only(path: &str) -> bool {
    let path = path.trim();
    !path.is_empty()
        && !path.contains("://")
        && !path.starts_with("http:")
        && !path.starts_with("https:")
        && !path.starts_with("s3:")
}

fn clamp_unit(value: f64) -> f64 {
    value.clamp(0.0, 1.0)
}

