fn apply_style_influence_to_opinion(
    mut opinion: MemberOpinion,
    profile: &StyleInfluencedMemberProfile,
) -> MemberOpinion {
    let blend_weight = profile
        .style_blend
        .archetype_weights
        .iter()
        .map(|weight| weight.weight)
        .sum::<f64>()
        .min(1.0);
    match profile.base_role {
        IndependentMemberRole::TrendEntry
            if matches!(opinion.stance, MemberStance::BuyProposal) =>
        {
            opinion.confidence = clamp_unit(opinion.confidence + 0.02 * blend_weight);
            opinion.evidence_notes.push(
                "style influence: trend/momentum archetype cards lightly support entry proposal"
                    .to_string(),
            );
        }
        IndependentMemberRole::RiskGuard
            if matches!(
                opinion.stance,
                MemberStance::NoTrade | MemberStance::NeedMoreEvidence
            ) =>
        {
            opinion.confidence = clamp_unit(opinion.confidence + 0.02 * blend_weight);
            opinion.risk_hint = clamp_unit(opinion.risk_hint + 0.02 * blend_weight);
            opinion.evidence_notes.push(
                "style influence: risk/volatility archetype cards strengthen defensive view"
                    .to_string(),
            );
        }
        IndependentMemberRole::EvidenceRegime => {
            if matches!(
                opinion.stance,
                MemberStance::Hold | MemberStance::NeedMoreEvidence
            ) {
                opinion.confidence = clamp_unit(opinion.confidence + 0.01 * blend_weight);
            }
            opinion.evidence_notes.push(
                "style influence: evidence-quality archetype cards affect evidence threshold only"
                    .to_string(),
            );
        }
        _ => {}
    }
    opinion
        .evidence_notes
        .push("archetype style card influence only; not a real investor clone".to_string());
    opinion
}

fn deferred_core_opinion(packet: &MemberInputPacket, reason: &str) -> MemberOpinion {
    MemberOpinion {
        member_id: packet.member_id.clone(),
        symbol: packet.market_data.symbol.clone(),
        market_scope: packet.market_data.market_scope,
        stance: MemberStance::NeedMoreEvidence,
        confidence: 0.5,
        expected_return_hint: 0.0,
        risk_hint: clamp_unit(packet.market_data.volatility_hint),
        evidence_notes: vec![
            format!("Mamba3 + Gated DeltaNet core {}", reason),
            "NeedMoreEvidence only; no fake AI inference, training, or order".to_string(),
        ],
        event_triggered: false,
        event_reason: Some(reason.to_string()),
    }
}

fn outcome_from_return(simulated_outcome_return: Option<f64>) -> SimulatedPaperOutcome {
    match simulated_outcome_return {
        Some(value) if value > 0.0 => SimulatedPaperOutcome::Positive,
        Some(value) if value < 0.0 => SimulatedPaperOutcome::Negative,
        Some(_) => SimulatedPaperOutcome::Neutral,
        None => SimulatedPaperOutcome::Unknown,
    }
}

pub fn apply_paper_outcome_feedback(
    members: &[AICommitteeMember],
    member_opinions: &[MemberOpinion],
    chairman_decision: Option<&ChairmanDecision>,
    paper_outcome_feedback: &PaperOutcomeFeedback,
) -> PaperOutcomeFeedbackResult {
    let score_updates: Vec<MemberScoreUpdate> = members
        .iter()
        .filter_map(|member| {
            let opinion = member_opinions
                .iter()
                .find(|opinion| opinion.member_id == member.member_id)?;
            Some(score_update_for(
                member,
                opinion,
                chairman_decision,
                outcome_return_for_feedback(paper_outcome_feedback.simulated_result),
            ))
        })
        .collect();

    let mut learning_journal_entries = Vec::new();
    let mut updated_memory_states = Vec::new();
    for member in members {
        let Some(opinion) = member_opinions
            .iter()
            .find(|opinion| opinion.member_id == member.member_id)
        else {
            continue;
        };
        let update_reason = score_updates
            .iter()
            .find(|update| update.member_id == member.member_id)
            .map(|update| update.update_reason)
            .unwrap_or(MemberScoreUpdateReason::Neutral);
        let learning_signal =
            learning_signal_for(update_reason, paper_outcome_feedback.simulated_result);
        let decision_id = chairman_decision
            .map(|decision| decision.decision_id.clone())
            .unwrap_or_else(|| paper_outcome_feedback.decision_id.clone());
        learning_journal_entries.push(MemberLearningJournalEntry {
            journal_id: format!(
                "journal-{}-{}-{}",
                member.member_id, paper_outcome_feedback.symbol, decision_id
            ),
            member_id: member.member_id.clone(),
            symbol: paper_outcome_feedback.symbol.clone(),
            market_scope: paper_outcome_feedback.market_scope,
            opinion_stance: opinion.stance,
            confidence: opinion.confidence,
            chairman_action: chairman_decision.map(|decision| decision.final_action),
            risk_governor_status: chairman_decision.map(|decision| decision.risk_governor_status),
            simulated_outcome: paper_outcome_feedback.simulated_result,
            learning_signal,
            note: "offline learning journal only; no model training or weight mutation".to_string(),
        });

        let mut memory_state = member
            .memory_state
            .clone()
            .unwrap_or_else(|| MemberMemoryState::new(&member.member_id));
        if !memory_state
            .recent_symbols
            .contains(&paper_outcome_feedback.symbol)
        {
            memory_state
                .recent_symbols
                .push(paper_outcome_feedback.symbol.clone());
        }
        memory_state.recent_opinion_count += 1;
        if opinion.event_triggered {
            memory_state.recent_event_count += 1;
        }
        match update_reason {
            MemberScoreUpdateReason::GoodCall | MemberScoreUpdateReason::HelpfulDissent => {
                memory_state.recent_good_call_count += 1;
            }
            MemberScoreUpdateReason::BadCall
            | MemberScoreUpdateReason::RiskyCall
            | MemberScoreUpdateReason::LowEvidence => {
                memory_state.recent_bad_call_count += 1;
            }
            MemberScoreUpdateReason::Neutral => {}
        }
        if chairman_decision
            .is_some_and(|decision| decision.risk_governor_status == RiskGovernorStatus::Vetoed)
        {
            memory_state.recent_risk_veto_count += 1;
        }
        memory_state
            .notes
            .push(format!("last_learning_signal={:?}", learning_signal));
        updated_memory_states.push(memory_state);
    }

    PaperOutcomeFeedbackResult {
        score_updates,
        learning_journal_entries,
        updated_memory_states,
    }
}

fn outcome_return_for_feedback(outcome: SimulatedPaperOutcome) -> Option<f64> {
    match outcome {
        SimulatedPaperOutcome::Positive => Some(0.01),
        SimulatedPaperOutcome::Negative => Some(-0.01),
        SimulatedPaperOutcome::Neutral => Some(0.0),
        SimulatedPaperOutcome::Unknown => None,
    }
}

fn learning_signal_for(
    update_reason: MemberScoreUpdateReason,
    outcome: SimulatedPaperOutcome,
) -> MemberLearningSignal {
    match update_reason {
        MemberScoreUpdateReason::GoodCall | MemberScoreUpdateReason::HelpfulDissent => {
            MemberLearningSignal::Reinforce
        }
        MemberScoreUpdateReason::BadCall
        | MemberScoreUpdateReason::RiskyCall
        | MemberScoreUpdateReason::LowEvidence => MemberLearningSignal::Penalize,
        MemberScoreUpdateReason::Neutral if matches!(outcome, SimulatedPaperOutcome::Unknown) => {
            MemberLearningSignal::Ignore
        }
        MemberScoreUpdateReason::Neutral => MemberLearningSignal::Watch,
    }
}

fn build_learning_journals(entries: &[MemberLearningJournalEntry]) -> Vec<MemberLearningJournal> {
    let mut member_ids: Vec<String> = entries
        .iter()
        .map(|entry| entry.member_id.clone())
        .collect();
    member_ids.sort();
    member_ids.dedup();
    member_ids
        .into_iter()
        .map(|member_id| {
            let entries: Vec<MemberLearningJournalEntry> = entries
                .iter()
                .filter(|entry| entry.member_id == member_id)
                .cloned()
                .collect();
            let summary = MemberLearningJournalSummary {
                reinforce_count: entries
                    .iter()
                    .filter(|entry| {
                        matches!(entry.learning_signal, MemberLearningSignal::Reinforce)
                    })
                    .count(),
                penalize_count: entries
                    .iter()
                    .filter(|entry| matches!(entry.learning_signal, MemberLearningSignal::Penalize))
                    .count(),
                watch_count: entries
                    .iter()
                    .filter(|entry| matches!(entry.learning_signal, MemberLearningSignal::Watch))
                    .count(),
                ignore_count: entries
                    .iter()
                    .filter(|entry| matches!(entry.learning_signal, MemberLearningSignal::Ignore))
                    .count(),
            };
            MemberLearningJournal {
                member_id,
                entries,
                summary,
            }
        })
        .collect()
}

impl MemberExperienceStore {
    pub fn new(store_id: impl Into<String>, records: Vec<MemberExperienceRecord>) -> Self {
        let mut records = records;
        records.sort_by(|left, right| {
            left.member_id
                .cmp(&right.member_id)
                .then(left.symbol.cmp(&right.symbol))
                .then(left.experience_id.cmp(&right.experience_id))
        });
        let mut member_ids: Vec<String> = records
            .iter()
            .map(|record| record.member_id.clone())
            .collect();
        member_ids.sort();
        member_ids.dedup();
        Self {
            store_id: store_id.into(),
            record_count: records.len(),
            member_count: member_ids.len(),
            records,
            paper_only: true,
        }
    }

    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_member_experience_path(path, "member experience store input path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let store: Self = serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if !store.paper_only {
            return Err("member experience store must be paper-only".to_string());
        }
        if store.records.iter().any(|record| !record.paper_only) {
            return Err("member experience records must be paper-only".to_string());
        }
        Ok(Self::new(store.store_id, store.records))
    }

    pub fn save_to_local_json(&self, path: &Path) -> Result<(), String> {
        validate_member_experience_path(path, "member experience store output path")?;
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
        }
        let text = serde_json::to_string_pretty(self).map_err(|err| err.to_string())?;
        fs::write(path, text).map_err(|err| err.to_string())
    }

    pub fn append_records(&mut self, records: Vec<MemberExperienceRecord>) {
        self.records.extend(records);
        let refreshed = Self::new(self.store_id.clone(), self.records.clone());
        self.records = refreshed.records;
        self.record_count = refreshed.record_count;
        self.member_count = refreshed.member_count;
        self.paper_only = true;
    }

    pub fn records_by_member(&self, member_id: &str) -> Vec<MemberExperienceRecord> {
        self.records
            .iter()
            .filter(|record| record.member_id == member_id)
            .cloned()
            .collect()
    }

    pub fn records_by_symbol(&self, symbol: &str) -> Vec<MemberExperienceRecord> {
        self.records
            .iter()
            .filter(|record| record.symbol == symbol)
            .cloned()
            .collect()
    }

    pub fn recent_records(&self, member_id: &str, limit: usize) -> Vec<MemberExperienceRecord> {
        let mut records = self.records_by_member(member_id);
        records.sort_by(|left, right| right.experience_id.cmp(&left.experience_id));
        records.truncate(limit);
        records
    }

    pub fn summarize_member_learning(&self, member_id: &str) -> Option<MemberCalibrationSummary> {
        let records = self.records_by_member(member_id);
        if records.is_empty() {
            None
        } else {
            Some(compute_member_calibration_summary(&records))
        }
    }

    pub fn export_replay_examples(&self, filter: &ReplayDatasetFilter) -> Vec<ReplayExample> {
        build_replay_dataset_from_experience_store(self, filter).examples
    }
}

impl ReplayDataset {
    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_member_experience_path(path, "replay dataset input path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let dataset: Self = serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if !dataset.paper_only {
            return Err("replay dataset must be paper-only".to_string());
        }
        if dataset.examples.iter().any(|example| !example.paper_only) {
            return Err("replay examples must be paper-only".to_string());
        }
        Ok(Self::new(
            dataset.dataset_id,
            dataset.generated_from_store_id,
            dataset.examples,
        ))
    }

    pub fn save_to_local_json(&self, path: &Path) -> Result<(), String> {
        validate_member_experience_path(path, "replay dataset output path")?;
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
        }
        let text = serde_json::to_string_pretty(self).map_err(|err| err.to_string())?;
        fs::write(path, text).map_err(|err| err.to_string())
    }

    fn new(
        dataset_id: impl Into<String>,
        generated_from_store_id: impl Into<String>,
        examples: Vec<ReplayExample>,
    ) -> Self {
        let mut examples = examples;
        examples.sort_by(|left, right| {
            left.member_id
                .cmp(&right.member_id)
                .then(left.symbol.cmp(&right.symbol))
                .then(left.replay_id.cmp(&right.replay_id))
        });
        let mut member_ids: Vec<String> = examples
            .iter()
            .map(|example| example.member_id.clone())
            .collect();
        member_ids.sort();
        member_ids.dedup();
        Self {
            dataset_id: dataset_id.into(),
            example_count: examples.len(),
            member_count: member_ids.len(),
            examples,
            generated_from_store_id: generated_from_store_id.into(),
            paper_only: true,
        }
    }
}

pub fn extract_member_experiences_from_batch_cycle(
    batch_result: &BatchCommitteeCycleResult,
    state_update: Option<&BatchCycleStateUpdate>,
    owner_summary: Option<&OwnerCommitteeSummary>,
    paper_outcome_feedback: Option<&PaperOutcomeFeedback>,
) -> Vec<MemberExperienceRecord> {
    batch_result
        .member_opinions
        .iter()
        .enumerate()
        .map(|(index, opinion)| {
            let session = batch_result.committee_sessions.iter().find(|session| {
                session.event.symbol == opinion.symbol
                    && session.event.market_scope == opinion.market_scope
                    && session
                        .member_opinions
                        .iter()
                        .any(|session_opinion| session_opinion.member_id == opinion.member_id)
            });
            let decision = session.and_then(|session| {
                batch_result
                    .chairman_decisions
                    .iter()
                    .find(|decision| decision.session_id == session.session_id)
            });
            let update_reason = batch_result
                .score_updates
                .iter()
                .find(|update| update.member_id == opinion.member_id)
                .map(|update| update.update_reason)
                .unwrap_or(MemberScoreUpdateReason::Neutral);
            let outcome =
                member_experience_outcome(update_reason, decision, paper_outcome_feedback);
            let learning_label = member_learning_label_for(update_reason, outcome);
            let memory_state_summary = state_update.and_then(|state_update| {
                state_update
                    .memory_updates
                    .iter()
                    .find(|memory| memory.member_id == opinion.member_id)
                    .map(memory_state_summary)
            });
            let owner_context_summary =
                owner_summary.map(|summary| summary.owner_readable_summary.clone());
            MemberExperienceRecord {
                experience_id: format!(
                    "experience-{}-{}-{}-{}",
                    batch_result.batch_id, opinion.symbol, opinion.member_id, index
                ),
                member_id: opinion.member_id.clone(),
                symbol: opinion.symbol.clone(),
                market_scope: opinion.market_scope,
                cycle_id: Some(batch_result.batch_id.clone()),
                event_id: session.map(|session| session.event.event_id.clone()),
                session_id: session.map(|session| session.session_id.clone()),
                decision_id: decision.map(|decision| decision.decision_id.clone()),
                input_context: MemberExperienceInputContext {
                    market_data_summary: format!(
                        "symbol={} scope={:?}",
                        opinion.symbol, opinion.market_scope
                    ),
                    news_summary:
                        "headline/summary-only news context; full article body not stored"
                            .to_string(),
                    owner_context_summary,
                    style_blend_summary: None,
                    memory_state_summary,
                },
                member_opinion: MemberExperienceOpinionSnapshot {
                    stance: opinion.stance,
                    confidence: opinion.confidence,
                    expected_return_hint: opinion.expected_return_hint,
                    risk_hint: opinion.risk_hint,
                    evidence_notes: opinion.evidence_notes.clone(),
                    event_triggered: opinion.event_triggered,
                },
                committee_context: MemberExperienceCommitteeContext {
                    disagreement_level: session
                        .map(|session| session.disagreement_level)
                        .unwrap_or(0.0),
                    other_member_stances: session
                        .map(|session| {
                            session
                                .member_opinions
                                .iter()
                                .filter(|session_opinion| {
                                    session_opinion.member_id != opinion.member_id
                                })
                                .map(|session_opinion| {
                                    format!(
                                        "{}:{:?}",
                                        session_opinion.member_id, session_opinion.stance
                                    )
                                })
                                .collect()
                        })
                        .unwrap_or_default(),
                    chairman_action: decision.map(|decision| decision.final_action),
                    risk_governor_status: decision.map(|decision| decision.risk_governor_status),
                    risk_flags: session
                        .map(|session| session.risk_flags.clone())
                        .unwrap_or_default(),
                },
                outcome,
                attribution: update_reason,
                learning_label,
                created_at: None,
                paper_only: true,
            }
        })
        .collect()
}

pub fn build_replay_dataset_from_experience_store(
    store: &MemberExperienceStore,
    filter: &ReplayDatasetFilter,
) -> ReplayDataset {
    let examples: Vec<ReplayExample> = store
        .records
        .iter()
        .filter(|record| replay_filter_matches(record, filter))
        .map(|record| ReplayExample {
            replay_id: format!("replay-{}", record.experience_id),
            member_id: record.member_id.clone(),
            symbol: record.symbol.clone(),
            market_scope: record.market_scope,
            input_features: ReplayInputFeatures {
                market_data_summary: record.input_context.market_data_summary.clone(),
                news_summary: record.input_context.news_summary.clone(),
                owner_context_summary: record.input_context.owner_context_summary.clone(),
                memory_state_summary: record.input_context.memory_state_summary.clone(),
            },
            target: ReplayTarget {
                stance: record.member_opinion.stance,
                confidence_calibration: record.learning_label,
                risk_label: format!("{:?}", record.attribution),
                evidence_label: evidence_label_for(record),
                outcome_label: record.outcome,
            },
            sanitized_input_features: None,
            target_labels: None,
            post_decision_context: None,
            sample_weight: replay_sample_weight(record),
            paper_only: true,
        })
        .collect();
    ReplayDataset::new(
        format!("replay-dataset-{}", store.store_id),
        store.store_id.clone(),
        examples,
    )
}

pub fn compute_member_calibration_summaries(
    store: &MemberExperienceStore,
) -> Vec<MemberCalibrationSummary> {
    let mut member_ids: Vec<String> = store
        .records
        .iter()
        .map(|record| record.member_id.clone())
        .collect();
    member_ids.sort();
    member_ids.dedup();
    member_ids
        .into_iter()
        .map(|member_id| {
            let records: Vec<&MemberExperienceRecord> = store
                .records
                .iter()
                .filter(|record| record.member_id == member_id)
                .collect();
            let high_confidence_count = records
                .iter()
                .filter(|record| record.member_opinion.confidence >= 0.75)
                .count();
            let high_confidence_bad_call_count = records
                .iter()
                .filter(|record| {
                    record.member_opinion.confidence >= 0.75
                        && matches!(
                            record.attribution,
                            MemberScoreUpdateReason::BadCall
                                | MemberScoreUpdateReason::RiskyCall
                                | MemberScoreUpdateReason::LowEvidence
                        )
                })
                .count();
            let risk_veto_count = records
                .iter()
                .filter(|record| {
                    matches!(record.outcome, MemberExperienceOutcome::RiskVetoSavedLoss)
                })
                .count();
            let helpful_dissent_count = records
                .iter()
                .filter(|record| matches!(record.outcome, MemberExperienceOutcome::HelpfulDissent))
                .count();
            let need_more_evidence_count = records
                .iter()
                .filter(|record| {
                    matches!(record.learning_label, MemberLearningLabel::NeedMoreEvidence)
                })
                .count();
            let (calibration_warning, suggested_adjustment) = if high_confidence_bad_call_count > 0
            {
                (
                    CalibrationWarning::Overconfident,
                    CalibrationSuggestedAdjustment::LowerConfidence,
                )
            } else if need_more_evidence_count > 0 {
                (
                    CalibrationWarning::NeedsMoreEvidence,
                    CalibrationSuggestedAdjustment::RaiseEvidenceThreshold,
                )
            } else if risk_veto_count > 0 {
                (
                    CalibrationWarning::Risky,
                    CalibrationSuggestedAdjustment::RaiseRiskSensitivity,
                )
            } else {
                (
                    CalibrationWarning::None,
                    CalibrationSuggestedAdjustment::Keep,
                )
            };
            MemberCalibrationSummary {
                member_id,
                total_records: records.len(),
                high_confidence_count,
                high_confidence_bad_call_count,
                risk_veto_count,
                helpful_dissent_count,
                need_more_evidence_count,
                calibration_warning,
                suggested_adjustment,
            }
        })
        .collect()
}

pub fn compute_member_calibration_summary(
    records: &[MemberExperienceRecord],
) -> MemberCalibrationSummary {
    let store = MemberExperienceStore::new("single-member-calibration", records.to_vec());
    compute_member_calibration_summaries(&store)
        .into_iter()
        .next()
        .unwrap_or_else(|| MemberCalibrationSummary {
            member_id: "unknown".to_string(),
            total_records: 0,
            high_confidence_count: 0,
            high_confidence_bad_call_count: 0,
            risk_veto_count: 0,
            helpful_dissent_count: 0,
            need_more_evidence_count: 0,
            calibration_warning: CalibrationWarning::None,
            suggested_adjustment: CalibrationSuggestedAdjustment::Keep,
        })
}

pub fn generate_member_self_review_notes(
    store: &MemberExperienceStore,
) -> Vec<MemberSelfReviewNote> {
    store
        .records
        .iter()
        .filter_map(|record| {
            let (review_type, summary, next_behavior_hint) = match record.learning_label {
                MemberLearningLabel::Penalize | MemberLearningLabel::CalibrateDown => (
                    MemberSelfReviewType::MistakeReview,
                    format!(
                        "{} should review {:?} on {}",
                        record.member_id, record.attribution, record.symbol
                    ),
                    "lower confidence unless evidence and risk checks agree".to_string(),
                ),
                MemberLearningLabel::NeedMoreEvidence => (
                    MemberSelfReviewType::EvidenceReview,
                    format!(
                        "{} lacked enough evidence on {}",
                        record.member_id, record.symbol
                    ),
                    "ask for more evidence before proposing paper action".to_string(),
                ),
                MemberLearningLabel::Reinforce => (
                    MemberSelfReviewType::GoodCallReview,
                    format!(
                        "{} can reinforce the {} pattern",
                        record.member_id, record.symbol
                    ),
                    "reuse the evidence pattern without increasing live risk".to_string(),
                ),
                MemberLearningLabel::CalibrateUp | MemberLearningLabel::Keep => return None,
            };
            Some(MemberSelfReviewNote {
                note_id: format!("self-review-{}", record.experience_id),
                member_id: record.member_id.clone(),
                experience_id: record.experience_id.clone(),
                review_type,
                summary,
                next_behavior_hint,
                paper_only: true,
            })
        })
        .collect()
}

pub fn generate_deterministic_self_review_notes(
    records: &[MemberExperienceRecord],
) -> Vec<MemberSelfReviewNote> {
    let store = MemberExperienceStore::new("self-review-records", records.to_vec());
    generate_member_self_review_notes(&store)
}

impl Default for SanitizedReplayDatasetBuildConfig {
    fn default() -> Self {
        Self {
            source_experience_store_id: "experience-store".to_string(),
            strict_temporal_boundary: true,
            include_post_decision_context_for_audit: true,
            include_prior_memory_buckets: true,
            reject_on_blocking_leakage: true,
            paper_only: true,
        }
    }
}

impl ReplayFeatureSanitizer {
    pub fn sanitize_input_text(&self, field_name: &str, text: &str) -> SanitizedField {
        let removed_terms = self.detect_blocked_terms(text);
        let field_blocked = self
            .blocked_field_names
            .iter()
            .any(|blocked| field_name.to_ascii_lowercase().contains(blocked));
        let original_present = !text.trim().is_empty();
        let contains_blocking_safety_term = removed_terms.iter().any(|term| {
            matches!(
                term.as_str(),
                "broker"
                    | "order"
                    | "account"
                    | "position"
                    | "holdings"
                    | "buying_power"
                    | "real_pnl"
                    | "pnl"
            )
        }) || field_blocked
            && matches!(
                field_name,
                "broker"
                    | "order"
                    | "account"
                    | "position"
                    | "holdings"
                    | "buying_power"
                    | "real_pnl"
                    | "pnl"
            );
        let safety_status = if contains_blocking_safety_term {
            SanitizedFieldSafetyStatus::BlockingLeakage
        } else if removed_terms.is_empty() && !field_blocked {
            SanitizedFieldSafetyStatus::Clean
        } else {
            SanitizedFieldSafetyStatus::Sanitized
        };
        let sanitized_text = if removed_terms.is_empty() && !field_blocked {
            text.to_string()
        } else if contains_blocking_safety_term {
            self.replacement_note.clone()
        } else {
            remove_blocked_terms(text, &removed_terms, &self.replacement_note)
        };
        SanitizedField {
            original_present,
            sanitized_text,
            removed_terms,
            safety_status,
        }
    }

    pub fn sanitize_memory_summary(&self, summary: &str) -> SanitizedField {
        self.sanitize_input_text("prior_member_memory_summary", summary)
    }

    pub fn sanitize_owner_context(&self, summary: &str) -> SanitizedField {
        self.sanitize_input_text("owner_pre_decision_context", summary)
    }

    pub fn sanitize_replay_input_features(
        &self,
        features: &ReplayInputFeatures,
    ) -> SanitizedReplayInputFeatures {
        let market = self.sanitize_input_text("market_data_summary", &features.market_data_summary);
        let news = self.sanitize_input_text("news_summary", &features.news_summary);
        let owner = features
            .owner_context_summary
            .as_ref()
            .map(|text| self.sanitize_owner_context(text));
        let memory = features
            .memory_state_summary
            .as_ref()
            .map(|text| self.sanitize_memory_summary(text));
        let mut feature_safety_notes = Vec::new();
        for (field, sanitized) in [("market_data_summary", &market), ("news_summary", &news)] {
            if !sanitized.removed_terms.is_empty() {
                feature_safety_notes.push(format!("{field}: removed blocked signal"));
            }
        }
        if let Some(owner) = &owner {
            if !owner.removed_terms.is_empty() {
                feature_safety_notes.push(format!(
                    "owner_pre_decision_context: removed blocked signal"
                ));
            }
        }
        if let Some(memory) = &memory {
            if !memory.removed_terms.is_empty() {
                feature_safety_notes.push(format!(
                    "prior_member_memory_summary: removed blocked signal"
                ));
            }
        }
        if feature_safety_notes.is_empty() {
            feature_safety_notes
                .push("strict temporal boundary: input features are pre-decision only".to_string());
        }
        SanitizedReplayInputFeatures {
            market_data_summary: market.sanitized_text,
            news_summary: news.sanitized_text,
            owner_pre_decision_context: owner.map(|field| field.sanitized_text),
            prior_member_memory_summary: memory.map(|field| field.sanitized_text),
            prior_style_blend_summary: None,
            prior_calibration_summary: None,
            feature_safety_notes,
            paper_only: true,
        }
    }

    pub fn detect_blocked_terms(&self, text: &str) -> Vec<String> {
        detect_blocked_terms_with_list(text, &self.blocked_terms)
    }
}

pub fn build_pre_decision_memory_snapshot(
    member_state: &MemberMemoryState,
    _before_cycle_id: Option<&str>,
) -> MemberPreDecisionMemorySnapshot {
    MemberPreDecisionMemorySnapshot {
        member_id: member_state.member_id.clone(),
        recent_opinion_count: member_state.recent_opinion_count,
        recent_event_count: member_state.recent_event_count,
        recent_good_call_count_bucket: memory_count_bucket(member_state.recent_good_call_count),
        recent_bad_call_count_bucket: memory_count_bucket(member_state.recent_bad_call_count),
        recent_risk_veto_count_bucket: memory_count_bucket(member_state.recent_risk_veto_count),
        evidence_need_tendency: evidence_need_tendency_from_notes(&member_state.notes),
        calibration_warning_prior: None,
        paper_only: true,
    }
}

pub fn build_sanitized_replay_dataset_from_experience_store(
    store: &MemberExperienceStore,
    config: SanitizedReplayDatasetBuildConfig,
) -> SanitizedReplayDatasetBuildResult {
    let sanitizer = ReplayFeatureSanitizer::default();
    let mut examples = Vec::new();
    let mut leakage_findings = Vec::new();
    let mut sanitized_count = 0;
    let mut rejected_count = 0;

    for record in &store.records {
        let raw_features = ReplayInputFeatures {
            market_data_summary: record.input_context.market_data_summary.clone(),
            news_summary: record.input_context.news_summary.clone(),
            owner_context_summary: record.input_context.owner_context_summary.clone(),
            memory_state_summary: record.input_context.memory_state_summary.clone(),
        };
        let sanitized = sanitizer.sanitize_replay_input_features(&raw_features);
        let sanitized_fields = [
            (
                "market_data_summary",
                sanitizer
                    .sanitize_input_text("market_data_summary", &raw_features.market_data_summary),
            ),
            (
                "news_summary",
                sanitizer.sanitize_input_text("news_summary", &raw_features.news_summary),
            ),
            (
                "owner_pre_decision_context",
                raw_features
                    .owner_context_summary
                    .as_ref()
                    .map(|text| sanitizer.sanitize_owner_context(text))
                    .unwrap_or_else(|| sanitizer.sanitize_owner_context("")),
            ),
            (
                "prior_member_memory_summary",
                raw_features
                    .memory_state_summary
                    .as_ref()
                    .map(|text| sanitizer.sanitize_memory_summary(text))
                    .unwrap_or_else(|| sanitizer.sanitize_memory_summary("")),
            ),
        ];
        let mut blocking = false;
        for (field_name, field) in sanitized_fields {
            if !field.removed_terms.is_empty() {
                sanitized_count += 1;
                for term in field.removed_terms {
                    let issue_type = leakage_issue_type_for_term(&term);
                    let severity = if matches!(
                        issue_type,
                        ReplayLeakageIssueType::BrokerAccountFieldDetected
                            | ReplayLeakageIssueType::RealTradeFieldDetected
                    ) {
                        ReplayLeakageSeverity::Blocking
                    } else {
                        ReplayLeakageSeverity::Warning
                    };
                    if severity == ReplayLeakageSeverity::Blocking {
                        blocking = true;
                    }
                    leakage_findings.push(ReplayLeakageFinding {
                        replay_id: format!("replay-{}", record.experience_id),
                        member_id: record.member_id.clone(),
                        section: ReplaySection::InputFeatures,
                        issue_type,
                        field_name: field_name.to_string(),
                        severity,
                        note: format!("sanitizer removed {term} from pre-decision input"),
                    });
                }
            }
            if field.safety_status == SanitizedFieldSafetyStatus::BlockingLeakage {
                blocking = true;
            }
        }
        if blocking && config.reject_on_blocking_leakage {
            rejected_count += 1;
            continue;
        }

        let target_labels = ReplayTargetLabels {
            stance_target: record.member_opinion.stance,
            confidence_calibration_target: record.learning_label,
            risk_label: format!("{:?}", record.attribution),
            evidence_label: evidence_label_for(record),
            outcome_label: record.outcome,
            attribution_label: record.attribution,
            label_source: ReplayLabelSource::ReviewRequired,
            label_confidence: ReplayLabelConfidence::ReviewRequired,
            paper_only: true,
        };
        let post_decision_context =
            config
                .include_post_decision_context_for_audit
                .then(|| ReplayPostDecisionContext {
                    chairman_action: record.committee_context.chairman_action,
                    risk_governor_status: record.committee_context.risk_governor_status,
                    disagreement_level: record.committee_context.disagreement_level,
                    other_member_stances: record.committee_context.other_member_stances.clone(),
                    risk_flags: record.committee_context.risk_flags.clone(),
                    paper_only: true,
                });
        examples.push(ReplayExample {
            replay_id: format!("replay-{}", record.experience_id),
            member_id: record.member_id.clone(),
            symbol: record.symbol.clone(),
            market_scope: record.market_scope,
            input_features: ReplayInputFeatures {
                market_data_summary: sanitized.market_data_summary.clone(),
                news_summary: sanitized.news_summary.clone(),
                owner_context_summary: sanitized.owner_pre_decision_context.clone(),
                memory_state_summary: if config.include_prior_memory_buckets {
                    sanitized.prior_member_memory_summary.clone()
                } else {
                    None
                },
            },
            target: ReplayTarget {
                stance: target_labels.stance_target,
                confidence_calibration: target_labels.confidence_calibration_target,
                risk_label: target_labels.risk_label.clone(),
                evidence_label: target_labels.evidence_label.clone(),
                outcome_label: target_labels.outcome_label,
            },
            sanitized_input_features: Some(sanitized),
            target_labels: Some(target_labels),
            post_decision_context,
            sample_weight: replay_sample_weight(record),
            paper_only: true,
        });
    }

    let dataset = ReplayDataset::new(
        format!(
            "sanitized-replay-dataset-{}",
            config.source_experience_store_id
        ),
        config.source_experience_store_id,
        examples,
    );
    let leakage_check = check_replay_data_leakage(&dataset);
    leakage_findings.extend(leakage_check.leakage_findings);
    leakage_findings.sort_by(|left, right| {
        left.replay_id
            .cmp(&right.replay_id)
            .then(left.field_name.cmp(&right.field_name))
            .then(format!("{:?}", left.issue_type).cmp(&format!("{:?}", right.issue_type)))
    });
    leakage_findings.dedup_by(|left, right| {
        left.replay_id == right.replay_id
            && left.member_id == right.member_id
            && left.section == right.section
            && left.issue_type == right.issue_type
            && left.field_name == right.field_name
    });

    let has_blocking = leakage_findings
        .iter()
        .any(|finding| finding.severity == ReplayLeakageSeverity::Blocking);
    let build_status = if dataset.examples.is_empty() {
        SanitizedReplayDatasetBuildStatus::Empty
    } else if has_blocking && config.reject_on_blocking_leakage {
        SanitizedReplayDatasetBuildStatus::BlockedByLeakage
    } else if sanitized_count > 0 || rejected_count > 0 || has_blocking {
        SanitizedReplayDatasetBuildStatus::BuiltWithWarnings
    } else {
        SanitizedReplayDatasetBuildStatus::Built
    };

    SanitizedReplayDatasetBuildResult {
        dataset,
        sanitized_count,
        rejected_count,
        leakage_findings,
        build_status,
        paper_only: true,
    }
}

