impl ResearchSourceRegistry {
    pub fn validate_sources(&self) -> Result<(), String> {
        if !self.paper_only {
            return Err("research source registry must be paper-only".to_string());
        }
        let mut ids = std::collections::BTreeSet::new();
        for source in &self.sources {
            validate_research_source_descriptor(source)?;
            if !ids.insert(source.source_id.clone()) {
                return Err(format!("duplicate research source id {}", source.source_id));
            }
        }
        Ok(())
    }

    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_local_json_path(path, "research source registry path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        if let Some(reason) = research_source_unsafe_reasons(&text).first() {
            return Err(reason.clone());
        }
        let registry: ResearchSourceRegistry =
            serde_json::from_str(&text).map_err(|err| err.to_string())?;
        registry.validate_sources()?;
        Ok(normalize_research_source_registry(registry))
    }

    pub fn enabled_sources(&self) -> Vec<ResearchSourceDescriptor> {
        self.sources
            .iter()
            .filter(|source| source.enabled)
            .cloned()
            .collect()
    }

    pub fn disabled_sources(&self) -> Vec<ResearchSourceDescriptor> {
        self.sources
            .iter()
            .filter(|source| !source.enabled)
            .cloned()
            .collect()
    }

    pub fn sources_for_symbol(&self, symbol: &str) -> Vec<ResearchSourceDescriptor> {
        self.sources
            .iter()
            .filter(|source| source.enabled)
            .filter(|source| {
                source.symbols.is_empty() || source.symbols.iter().any(|item| item == symbol)
            })
            .cloned()
            .collect()
    }

    pub fn sources_for_scope(&self, scope: MarketScope) -> Vec<ResearchSourceDescriptor> {
        self.sources
            .iter()
            .filter(|source| source.enabled)
            .filter(|source| {
                source.market_scopes.is_empty() || source.market_scopes.contains(&scope)
            })
            .cloned()
            .collect()
    }
}

fn research_trust_level_base_score(level: ResearchSourceTrustLevel) -> f64 {
    match level {
        ResearchSourceTrustLevel::High => 0.95,
        ResearchSourceTrustLevel::Medium => 0.75,
        ResearchSourceTrustLevel::Low => 0.4,
        ResearchSourceTrustLevel::ReviewRequired => 0.15,
    }
}

pub fn evaluate_research_source_trust(
    registry: &ResearchSourceRegistry,
    recent_evidence: Option<&ResearchEvidenceBundle>,
) -> SourceTrustEvaluationResult {
    let evidence_counts: std::collections::BTreeMap<&str, usize> = recent_evidence
        .map(|bundle| {
            let mut counts = std::collections::BTreeMap::new();
            for record in &bundle.records {
                if let Some(source_id) = record.source_id.as_deref() {
                    *counts.entry(source_id).or_insert(0usize) += 1;
                }
            }
            counts
        })
        .unwrap_or_default();
    let mut source_scores = Vec::new();
    let mut trusted_count = 0;
    let mut review_required_count = 0;
    let mut rejected_count = 0;
    for source in &registry.sources {
        let base = research_trust_level_base_score(source.trust_level);
        let evidence_count = evidence_counts
            .get(source.source_id.as_str())
            .copied()
            .unwrap_or(0);
        let freshness_score = if source.enabled { 0.8 } else { 0.2 };
        let consistency_score = if evidence_count > 0 { 0.8 } else { 0.6 };
        let coverage_score = if !source.symbols.is_empty() || !source.market_scopes.is_empty() {
            0.8
        } else {
            0.6
        };
        let safety_score = if source.enabled || matches!(source.kind, ResearchSourceKind::Disabled)
        {
            1.0
        } else {
            0.7
        };
        let final_score = clamp_unit(
            (base + freshness_score + consistency_score + coverage_score + safety_score) / 5.0,
        );
        let mut reasons = Vec::new();
        if !source.enabled {
            reasons.push("source disabled by config".to_string());
        }
        if research_source_is_network(source.kind) {
            reasons.push("network source remains allowlisted-only".to_string());
        }
        let trust_status = if !source.enabled {
            SourceTrustStatus::Rejected
        } else if matches!(source.trust_level, ResearchSourceTrustLevel::ReviewRequired) {
            SourceTrustStatus::ReviewRequired
        } else if final_score >= 0.75 {
            SourceTrustStatus::Trusted
        } else if final_score >= 0.5 {
            SourceTrustStatus::UsableWithWarnings
        } else {
            SourceTrustStatus::ReviewRequired
        };
        match trust_status {
            SourceTrustStatus::Trusted => trusted_count += 1,
            SourceTrustStatus::ReviewRequired => review_required_count += 1,
            SourceTrustStatus::Rejected => rejected_count += 1,
            SourceTrustStatus::UsableWithWarnings => {}
        }
        source_scores.push(SourceTrustScore {
            source_id: source.source_id.clone(),
            base_trust_level: source.trust_level,
            freshness_score,
            consistency_score,
            coverage_score,
            safety_score,
            final_score,
            trust_status,
            reasons,
            paper_only: true,
        });
    }
    SourceTrustEvaluationResult {
        source_scores,
        trusted_count,
        review_required_count,
        rejected_count,
        paper_only: true,
    }
}

fn member_research_preferences_for_role(
    role: Option<IndependentMemberRole>,
) -> (Vec<MemberResearchTaskType>, Vec<ResearchSourceKind>) {
    match role {
        Some(IndependentMemberRole::TrendEntry) => (
            vec![
                MemberResearchTaskType::GatherNewsContext,
                MemberResearchTaskType::GatherPriceEvidence,
                MemberResearchTaskType::BuildReplayEvidenceCandidate,
            ],
            vec![
                ResearchSourceKind::LocalPriceSeries,
                ResearchSourceKind::LocalNewsFixture,
                ResearchSourceKind::LocalRssFixture,
                ResearchSourceKind::AllowlistedHeadlineEndpoint,
            ],
        ),
        Some(IndependentMemberRole::RiskGuard) => (
            vec![
                MemberResearchTaskType::ReviewRiskVetoCase,
                MemberResearchTaskType::FindContradictoryEvidence,
                MemberResearchTaskType::GatherPriceEvidence,
            ],
            vec![
                ResearchSourceKind::LocalPriceSeries,
                ResearchSourceKind::LocalMarketData,
                ResearchSourceKind::LocalNewsFixture,
            ],
        ),
        Some(IndependentMemberRole::EvidenceRegime) => (
            vec![
                MemberResearchTaskType::VerifyPaperOutcome,
                MemberResearchTaskType::ReviewNeedMoreEvidenceCase,
                MemberResearchTaskType::FillCoverageGap,
            ],
            vec![
                ResearchSourceKind::LocalNewsFixture,
                ResearchSourceKind::LocalRssFixture,
                ResearchSourceKind::LocalPriceSeries,
                ResearchSourceKind::LocalMarketData,
            ],
        ),
        None => (
            vec![MemberResearchTaskType::BuildReplayEvidenceCandidate],
            vec![
                ResearchSourceKind::LocalNewsFixture,
                ResearchSourceKind::LocalPriceSeries,
            ],
        ),
    }
}

fn member_task_type_for_weak_item(item: &WeakReplayLabelItem) -> MemberResearchTaskType {
    match role_for_member_id(&item.member_id) {
        Some(IndependentMemberRole::TrendEntry) => {
            if item.current_outcome_label == MemberExperienceOutcome::Unknown {
                MemberResearchTaskType::GatherPriceEvidence
            } else {
                MemberResearchTaskType::GatherNewsContext
            }
        }
        Some(IndependentMemberRole::RiskGuard) => {
            if item
                .weakness_reasons
                .contains(&WeakReplayLabelReason::ContradictoryEvidence)
            {
                MemberResearchTaskType::FindContradictoryEvidence
            } else {
                MemberResearchTaskType::ReviewRiskVetoCase
            }
        }
        Some(IndependentMemberRole::EvidenceRegime) => {
            if item.current_outcome_label == MemberExperienceOutcome::Unknown {
                MemberResearchTaskType::ReviewNeedMoreEvidenceCase
            } else {
                MemberResearchTaskType::VerifyPaperOutcome
            }
        }
        None => MemberResearchTaskType::BuildReplayEvidenceCandidate,
    }
}

fn member_task_type_for_gap(gap: &ReplayCoverageGap) -> (String, MemberResearchTaskType) {
    match gap.gap_type {
        ReplayCoverageGapType::RiskVetoMissing
        | ReplayCoverageGapType::HighConfidenceMistakeMissing => (
            "RiskGuardAI".to_string(),
            MemberResearchTaskType::ReviewRiskVetoCase,
        ),
        ReplayCoverageGapType::EvidenceGapMissing | ReplayCoverageGapType::LabelSourceWeak => (
            "EvidenceRegimeAI".to_string(),
            MemberResearchTaskType::FillCoverageGap,
        ),
        _ => (
            "TrendEntryAI".to_string(),
            MemberResearchTaskType::BuildReplayEvidenceCandidate,
        ),
    }
}

pub fn build_tasks_from_weak_labels(
    weak_inventory: &WeakReplayLabelInventory,
) -> MemberResearchTaskQueue {
    let mut tasks: Vec<MemberResearchTask> = weak_inventory
        .weak_items
        .iter()
        .map(|item| {
            let member_id = display_name_for_member_id(&item.member_id).to_string();
            let role = role_for_member_id(&item.member_id);
            let (_, source_preferences) = member_research_preferences_for_role(role);
            MemberResearchTask {
                task_id: format!("research-weak-{}", item.item_id),
                member_id,
                task_type: member_task_type_for_weak_item(item),
                symbol: Some(item.symbol.clone()),
                market_scope: Some(item.market_scope),
                related_replay_id: (!item.replay_id.trim().is_empty())
                    .then(|| item.replay_id.clone()),
                related_experience_id: item.experience_id.clone(),
                related_decision_id: item.decision_id.clone(),
                priority: item.priority,
                source_preferences,
                task_reason: format!("weak label follow-up: {:?}", item.weakness_reasons),
                paper_only: true,
            }
        })
        .collect();
    tasks.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.task_id.cmp(&right.task_id))
    });
    MemberResearchTaskQueue {
        queue_id: format!("{}-member-research-tasks", weak_inventory.inventory_id),
        high_priority_count: tasks
            .iter()
            .filter(|task| task.priority == WeakReplayLabelPriority::High)
            .count(),
        tasks,
        paper_only: true,
    }
}

pub fn build_tasks_from_coverage_gaps(gaps: &[ReplayCoverageGap]) -> MemberResearchTaskQueue {
    let mut tasks: Vec<MemberResearchTask> = gaps
        .iter()
        .enumerate()
        .map(|(index, gap)| {
            let (member_id, task_type) = member_task_type_for_gap(gap);
            let role = role_for_member_id(&member_id);
            let (_, source_preferences) = member_research_preferences_for_role(role);
            MemberResearchTask {
                task_id: format!("research-gap-{}-{index}", gap.gap_id),
                member_id,
                task_type,
                symbol: gap.symbol.clone(),
                market_scope: gap.market_scope,
                related_replay_id: None,
                related_experience_id: None,
                related_decision_id: None,
                priority: match gap.priority {
                    ReplayCoverageGapPriority::High => WeakReplayLabelPriority::High,
                    ReplayCoverageGapPriority::Normal => WeakReplayLabelPriority::Normal,
                    ReplayCoverageGapPriority::Medium => WeakReplayLabelPriority::Normal,
                    ReplayCoverageGapPriority::Low => WeakReplayLabelPriority::Low,
                },
                source_preferences,
                task_reason: gap.reason.clone(),
                paper_only: true,
            }
        })
        .collect();
    tasks.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.task_id.cmp(&right.task_id))
    });
    MemberResearchTaskQueue {
        queue_id: "coverage-gap-member-research-tasks".to_string(),
        high_priority_count: tasks
            .iter()
            .filter(|task| task.priority == WeakReplayLabelPriority::High)
            .count(),
        tasks,
        paper_only: true,
    }
}

pub fn build_tasks_from_attention_queue(
    attention_queue: &OwnerAttentionQueue,
) -> MemberResearchTaskQueue {
    let mut tasks: Vec<MemberResearchTask> = attention_queue
        .items
        .iter()
        .map(|item| {
            let (member_id, task_type, source_preferences) = match item.attention_type {
                OwnerAttentionType::RiskVeto => (
                    "RiskGuardAI".to_string(),
                    MemberResearchTaskType::ReviewRiskVetoCase,
                    vec![
                        ResearchSourceKind::LocalPriceSeries,
                        ResearchSourceKind::LocalMarketData,
                    ],
                ),
                OwnerAttentionType::NeedMoreEvidence => (
                    "EvidenceRegimeAI".to_string(),
                    MemberResearchTaskType::ReviewNeedMoreEvidenceCase,
                    vec![
                        ResearchSourceKind::LocalNewsFixture,
                        ResearchSourceKind::LocalRssFixture,
                        ResearchSourceKind::LocalPriceSeries,
                    ],
                ),
                _ => (
                    "TrendEntryAI".to_string(),
                    MemberResearchTaskType::GatherNewsContext,
                    vec![
                        ResearchSourceKind::LocalNewsFixture,
                        ResearchSourceKind::LocalRssFixture,
                    ],
                ),
            };
            MemberResearchTask {
                task_id: format!("research-attention-{}", item.item_id),
                member_id,
                task_type,
                symbol: item.symbol.clone(),
                market_scope: item.market_scope,
                related_replay_id: None,
                related_experience_id: None,
                related_decision_id: item.related_decision_id.clone(),
                priority: match item.priority {
                    OwnerAttentionPriority::High => WeakReplayLabelPriority::High,
                    OwnerAttentionPriority::Normal => WeakReplayLabelPriority::Normal,
                    OwnerAttentionPriority::Low => WeakReplayLabelPriority::Low,
                },
                source_preferences,
                task_reason: item.reason.clone(),
                paper_only: true,
            }
        })
        .collect();
    tasks.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.task_id.cmp(&right.task_id))
    });
    MemberResearchTaskQueue {
        queue_id: format!("{}-member-research-tasks", attention_queue.queue_id),
        high_priority_count: tasks
            .iter()
            .filter(|task| task.priority == WeakReplayLabelPriority::High)
            .count(),
        tasks,
        paper_only: true,
    }
}

impl MemberResearchTaskQueue {
    pub fn sort_by_priority(&self) -> Self {
        let mut queue = self.clone();
        queue.tasks.sort_by(|left, right| {
            right
                .priority
                .cmp(&left.priority)
                .then_with(|| left.member_id.cmp(&right.member_id))
                .then_with(|| left.task_id.cmp(&right.task_id))
        });
        queue
    }

    pub fn next_tasks(&self, limit: usize) -> Vec<MemberResearchTask> {
        self.tasks.iter().take(limit).cloned().collect()
    }
}

fn research_source_matches_task(
    task: &MemberResearchTask,
    source: &ResearchSourceDescriptor,
) -> bool {
    if !task.source_preferences.is_empty() && !task.source_preferences.contains(&source.kind) {
        return false;
    }
    if let Some(symbol) = task.symbol.as_deref() {
        if !source.symbols.is_empty() && !source.symbols.iter().any(|item| item == symbol) {
            return false;
        }
    }
    if let Some(scope) = task.market_scope {
        if !source.market_scopes.is_empty() && !source.market_scopes.contains(&scope) {
            return false;
        }
    }
    true
}

fn truncate_research_summary(text: &str, max_chars: usize) -> String {
    text.chars().take(max_chars).collect()
}

fn build_news_research_records(
    task: &MemberResearchTask,
    source: &ResearchSourceDescriptor,
    items: &[CollectedNewsItem],
    trust_score: Option<f64>,
) -> Vec<ResearchEvidenceRecord> {
    items
        .iter()
        .take(source.max_items)
        .enumerate()
        .map(|(index, item)| ResearchEvidenceRecord {
            evidence_id: format!("evidence-{}-{}-{index}", source.source_id, task.task_id),
            task_id: Some(task.task_id.clone()),
            member_id: task.member_id.clone(),
            symbol: Some(item.symbol.clone()),
            market_scope: item.market_scope.or(task.market_scope),
            kind: ResearchEvidenceKind::NewsHeadline,
            headline: Some(item.headline.clone()),
            summary: Some(truncate_research_summary(
                &item.summary,
                source.max_summary_chars,
            )),
            source_id: Some(source.source_id.clone()),
            source_trust_score: trust_score,
            related_replay_id: task.related_replay_id.clone(),
            related_experience_id: task.related_experience_id.clone(),
            related_decision_id: task.related_decision_id.clone(),
            related_attention_item_id: None,
            evidence_confidence: ReplayLabelConfidence::ReviewRequired,
            evidence_notes: vec![
                "headline-only research evidence; no full article body stored".to_string(),
            ],
            paper_only: true,
        })
        .collect()
}

fn build_price_research_record(
    task: &MemberResearchTask,
    source: &ResearchSourceDescriptor,
    series: &PaperPriceSeries,
    trust_score: Option<f64>,
) -> Option<ResearchEvidenceRecord> {
    let first = series.bars.first()?;
    let last = series.bars.last()?;
    if first.close.abs() <= f64::EPSILON {
        return None;
    }
    let change = (last.close - first.close) / first.close;
    Some(ResearchEvidenceRecord {
        evidence_id: format!(
            "evidence-{}-{}-{}",
            source.source_id, task.task_id, series.series_id
        ),
        task_id: Some(task.task_id.clone()),
        member_id: task.member_id.clone(),
        symbol: Some(series.symbol.clone()),
        market_scope: Some(series.market_scope),
        kind: ResearchEvidenceKind::PriceMove,
        headline: Some(format!("paper price move for {}", series.symbol)),
        summary: Some(format!("price_change_pct={change:.6}")),
        source_id: Some(source.source_id.clone()),
        source_trust_score: trust_score,
        related_replay_id: task.related_replay_id.clone(),
        related_experience_id: task.related_experience_id.clone(),
        related_decision_id: task.related_decision_id.clone(),
        related_attention_item_id: None,
        evidence_confidence: if change.abs() >= 0.01 {
            ReplayLabelConfidence::Medium
        } else {
            ReplayLabelConfidence::Low
        },
        evidence_notes: vec![format!("price_change_pct={change:.6}")],
        paper_only: true,
    })
}

fn price_series_matches_research_task(
    series: &PaperPriceSeries,
    task: &MemberResearchTask,
) -> bool {
    task.symbol
        .as_ref()
        .map(|symbol| series.symbol == *symbol)
        .unwrap_or(true)
        && task
            .market_scope
            .map(|scope| series.market_scope == scope)
            .unwrap_or(true)
}

fn collect_research_evidence_with_network_mode(
    tasks: &[MemberResearchTask],
    registry: &ResearchSourceRegistry,
    source_scores: &[SourceTrustScore],
    allow_network_sources: bool,
) -> Result<ResearchEvidenceBundle, String> {
    registry.validate_sources()?;
    let score_by_source: std::collections::BTreeMap<&str, &SourceTrustScore> = source_scores
        .iter()
        .map(|score| (score.source_id.as_str(), score))
        .collect();
    let mut records = Vec::new();
    for task in tasks {
        for source in registry.enabled_sources() {
            if !research_source_matches_task(task, &source) {
                continue;
            }
            let trust_score = score_by_source
                .get(source.source_id.as_str())
                .map(|score| score.final_score);
            match source.kind {
                ResearchSourceKind::LocalNewsFixture => {
                    let items = load_collected_news_items_from_local_json(Path::new(
                        &source.source_path_or_url,
                    ))?;
                    let filtered: Vec<CollectedNewsItem> = items
                        .into_iter()
                        .filter(|item| {
                            task.symbol
                                .as_ref()
                                .map(|symbol| &item.symbol == symbol)
                                .unwrap_or(true)
                        })
                        .filter(|item| {
                            task.market_scope
                                .map(|scope| {
                                    item.market_scope == Some(scope) || item.market_scope.is_none()
                                })
                                .unwrap_or(true)
                        })
                        .collect();
                    records.extend(build_news_research_records(
                        task,
                        &source,
                        &filtered,
                        trust_score,
                    ));
                }
                ResearchSourceKind::LocalRssFixture => {
                    let xml_text = fs::read_to_string(&source.source_path_or_url)
                        .map_err(|err| err.to_string())?;
                    let parse_result = parse_rss_xml_fixture(
                        &xml_text,
                        RssXmlParseConfig {
                            parser_id: format!("{}-{}", source.source_id, task.task_id),
                            source_label: source.label.clone(),
                            symbol_hint: task.symbol.clone(),
                            market_scope: task.market_scope,
                            max_items: source.max_items,
                            max_summary_chars: source.max_summary_chars,
                            trust_level: NewsProviderTrustLevel::ReviewRequired,
                            paper_only: true,
                        },
                    );
                    let items = convert_rss_items_to_collected_news(&parse_result.parsed_items);
                    records.extend(build_news_research_records(
                        task,
                        &source,
                        &items,
                        trust_score,
                    ));
                }
                ResearchSourceKind::LocalPriceSeries => {
                    let store = load_price_series_store_from_local_json(Path::new(
                        &source.source_path_or_url,
                    ))?;
                    for series in store
                        .series
                        .iter()
                        .filter(|series| price_series_matches_research_task(series, task))
                        .take(source.max_items)
                    {
                        if let Some(record) =
                            build_price_research_record(task, &source, series, trust_score)
                        {
                            records.push(record);
                        }
                    }
                }
                ResearchSourceKind::LocalMarketData => {
                    let market_data =
                        load_market_data_from_local_json(Path::new(&source.source_path_or_url))?;
                    for (index, snapshot) in market_data
                        .into_iter()
                        .filter(|snapshot| {
                            task.symbol
                                .as_ref()
                                .map(|symbol| snapshot.symbol == *symbol)
                                .unwrap_or(true)
                                && task
                                    .market_scope
                                    .map(|scope| snapshot.market_scope == scope)
                                    .unwrap_or(true)
                        })
                        .take(source.max_items)
                        .enumerate()
                    {
                        records.push(ResearchEvidenceRecord {
                            evidence_id: format!(
                                "evidence-{}-{}-{index}",
                                source.source_id, task.task_id
                            ),
                            task_id: Some(task.task_id.clone()),
                            member_id: task.member_id.clone(),
                            symbol: Some(snapshot.symbol),
                            market_scope: Some(snapshot.market_scope),
                            kind: ResearchEvidenceKind::SupportingEvidence,
                            headline: Some("local market context".to_string()),
                            summary: Some(format!(
                                "price={} change_pct={} volatility_hint={}",
                                snapshot.price, snapshot.change_pct, snapshot.volatility_hint
                            )),
                            source_id: Some(source.source_id.clone()),
                            source_trust_score: trust_score,
                            related_replay_id: task.related_replay_id.clone(),
                            related_experience_id: task.related_experience_id.clone(),
                            related_decision_id: task.related_decision_id.clone(),
                            related_attention_item_id: None,
                            evidence_confidence: ReplayLabelConfidence::Low,
                            evidence_notes: vec![
                                "local market snapshot only; no trade execution".to_string(),
                            ],
                            paper_only: true,
                        });
                    }
                }
                ResearchSourceKind::AllowlistedRssFeed => {
                    if allow_network_sources {
                        let allowed_host = source.allowed_host.clone().unwrap_or_else(|| {
                            extract_url_host(&source.source_path_or_url).unwrap_or_default()
                        });
                        let result = run_single_allowlisted_rss_fetch_pilot_with_http_policy(
                            &RssFetchPilotConfig {
                                pilot_id: format!("{}-{}", source.source_id, task.task_id),
                                enabled: source.enabled,
                                rss_url: source.source_path_or_url.clone(),
                                allowed_domains: vec![allowed_host.clone()],
                                timeout_ms: default_safe_http_timeout_ms(),
                                rate_limit_ms: default_safe_news_rate_limit_ms(),
                                max_items: source.max_items,
                                max_summary_chars: source.max_summary_chars,
                                source_label: source.label.clone(),
                                symbol_hint: task.symbol.clone(),
                                market_scope: task.market_scope,
                                paper_only: true,
                            },
                            &SafeHttpClientPolicy {
                                network_enabled: true,
                                allowed_hosts: vec![allowed_host],
                                ..SafeHttpClientPolicy::default()
                            },
                            &DeferredRealHttpTransport,
                        )?;
                        records.extend(build_news_research_records(
                            task,
                            &source,
                            &result.collected_news,
                            trust_score,
                        ));
                    }
                }
                ResearchSourceKind::AllowlistedHeadlineEndpoint | ResearchSourceKind::Disabled => {}
            }
        }
    }
    records.sort_by(|left, right| left.evidence_id.cmp(&right.evidence_id));
    Ok(ResearchEvidenceBundle {
        bundle_id: format!("{}-research-evidence", registry.registry_id),
        source_scores: source_scores.to_vec(),
        task_count: tasks.len(),
        evidence_count: records.len(),
        records,
        paper_only: true,
    })
}

pub fn collect_research_evidence(
    tasks: &[MemberResearchTask],
    registry: &ResearchSourceRegistry,
    source_scores: &[SourceTrustScore],
) -> Result<ResearchEvidenceBundle, String> {
    collect_research_evidence_with_network_mode(tasks, registry, source_scores, false)
}

impl ResearchEvidenceBundle {
    pub fn evidence_by_member(&self, member_id: &str) -> Vec<ResearchEvidenceRecord> {
        self.records
            .iter()
            .filter(|record| record.member_id == member_id)
            .cloned()
            .collect()
    }

    pub fn evidence_by_symbol(&self, symbol: &str) -> Vec<ResearchEvidenceRecord> {
        self.records
            .iter()
            .filter(|record| record.symbol.as_deref() == Some(symbol))
            .cloned()
            .collect()
    }

    pub fn evidence_by_replay_id(&self, replay_id: &str) -> Vec<ResearchEvidenceRecord> {
        self.records
            .iter()
            .filter(|record| record.related_replay_id.as_deref() == Some(replay_id))
            .cloned()
            .collect()
    }
}

fn research_price_change_from_record(record: &ResearchEvidenceRecord) -> Option<f64> {
    record
        .evidence_notes
        .iter()
        .find_map(|note| {
            note.strip_prefix("price_change_pct=")
                .and_then(|value| value.parse().ok())
        })
        .or_else(|| {
            record.summary.as_deref().and_then(|summary| {
                summary
                    .strip_prefix("price_change_pct=")
                    .and_then(|value| value.parse().ok())
            })
        })
}

fn research_source_can_promote_label(score: Option<&SourceTrustScore>) -> bool {
    let Some(score) = score else {
        return false;
    };
    matches!(
        score.trust_status,
        SourceTrustStatus::Trusted | SourceTrustStatus::UsableWithWarnings
    ) && !matches!(
        score.base_trust_level,
        ResearchSourceTrustLevel::Low | ResearchSourceTrustLevel::ReviewRequired
    ) && score.final_score >= 0.5
}

pub fn convert_research_evidence_to_paper_outcome_evidence(
    bundle: &ResearchEvidenceBundle,
    policy: &ResearchToPaperEvidenceConversionPolicy,
) -> ResearchToPaperEvidenceConversionResult {
    let mut converted_records = Vec::new();
    let mut skipped_records = Vec::new();
    let mut skip_reasons = Vec::new();
    let score_by_source: std::collections::BTreeMap<&str, &SourceTrustScore> = bundle
        .source_scores
        .iter()
        .map(|score| (score.source_id.as_str(), score))
        .collect();
    let thresholds = PaperPriceMoveLabelPolicy::default();
    for record in &bundle.records {
        match record.kind {
            ResearchEvidenceKind::PriceMove if policy.allow_price_move_to_paper_evidence => {
                if policy.require_replay_or_decision_id
                    && record.related_replay_id.is_none()
                    && record.related_decision_id.is_none()
                {
                    skipped_records.push(record.clone());
                    skip_reasons
                        .push("price evidence requires replay_id or decision_id".to_string());
                    continue;
                }
                if !policy.allow_low_trust_source_promotion
                    && !research_source_can_promote_label(
                        record
                            .source_id
                            .as_deref()
                            .and_then(|source_id| score_by_source.get(source_id).copied()),
                    )
                {
                    skipped_records.push(record.clone());
                    skip_reasons.push(
                        "low or review-required trust price evidence cannot promote labels"
                            .to_string(),
                    );
                    continue;
                }
                let Some(change) = research_price_change_from_record(record) else {
                    skipped_records.push(record.clone());
                    skip_reasons.push("price evidence missing change percentage".to_string());
                    continue;
                };
                let candidate_label = if change >= thresholds.positive_threshold_pct {
                    MemberExperienceOutcome::PaperPositive
                } else if change <= thresholds.negative_threshold_pct {
                    MemberExperienceOutcome::PaperNegative
                } else if change.abs() <= thresholds.neutral_band_pct {
                    MemberExperienceOutcome::PaperNeutral
                } else {
                    MemberExperienceOutcome::Unknown
                };
                let confidence = if matches!(candidate_label, MemberExperienceOutcome::Unknown) {
                    ReplayLabelConfidence::ReviewRequired
                } else {
                    ReplayLabelConfidence::Medium
                };
                converted_records.push(PaperOutcomeEvidenceRecord {
                    evidence_id: format!("paper-evidence-{}", record.evidence_id),
                    symbol: record
                        .symbol
                        .clone()
                        .unwrap_or_else(|| "UNKNOWN".to_string()),
                    market_scope: record.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    decision_id: record.related_decision_id.clone(),
                    event_id: None,
                    replay_id: record.related_replay_id.clone(),
                    experience_id: record.related_experience_id.clone(),
                    horizon: replay_evidence_horizon_for_scope(
                        record.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    ),
                    horizon_bars: price_horizon_bars(replay_evidence_horizon_for_scope(
                        record.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    )),
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: Some(change),
                    candidate_label,
                    label_source: if matches!(confidence, ReplayLabelConfidence::Medium) {
                        ReplayLabelSource::ManualPaperLabel
                    } else {
                        ReplayLabelSource::ReviewRequired
                    },
                    label_confidence: confidence,
                    evidence_notes: record.evidence_notes.clone(),
                    validation_hint: Some(if matches!(confidence, ReplayLabelConfidence::Medium) {
                        PaperOutcomeEvidenceValidationHint::PromoteIfPolicyPasses
                    } else {
                        PaperOutcomeEvidenceValidationHint::KeepReviewRequired
                    }),
                    paper_only: true,
                });
            }
            ResearchEvidenceKind::NewsHeadline
                if policy.allow_news_headline_to_context_evidence =>
            {
                skipped_records.push(record.clone());
                skip_reasons
                    .push("news headline alone cannot become validated label evidence".to_string());
            }
            _ => {
                skipped_records.push(record.clone());
                skip_reasons.push(
                    "research evidence kind not convertible to paper label evidence".to_string(),
                );
            }
        }
    }
    ResearchToPaperEvidenceConversionResult {
        converted_count: converted_records.len(),
        skipped_count: skipped_records.len(),
        converted_records,
        skipped_records,
        skip_reasons,
        paper_only: true,
    }
}

fn self_growing_evidence_kind_for_record(kind: ResearchEvidenceKind) -> SelfGrowingEvidenceKind {
    match kind {
        ResearchEvidenceKind::PriceMove => SelfGrowingEvidenceKind::PriceMove,
        ResearchEvidenceKind::NewsHeadline => SelfGrowingEvidenceKind::NewsContext,
        ResearchEvidenceKind::SourceTrust => SelfGrowingEvidenceKind::SourceTrust,
        ResearchEvidenceKind::ContradictoryEvidence => {
            SelfGrowingEvidenceKind::ContradictoryEvidence
        }
        ResearchEvidenceKind::SupportingEvidence => SelfGrowingEvidenceKind::SupportingEvidence,
        ResearchEvidenceKind::PaperOutcomeEvidenceCandidate => {
            SelfGrowingEvidenceKind::PaperOutcomeCandidate
        }
        ResearchEvidenceKind::CoverageGapEvidence => SelfGrowingEvidenceKind::CoverageGapEvidence,
    }
}

fn self_growing_label_source_for_kind(
    kind: SelfGrowingEvidenceKind,
) -> SelfGrowingEvidenceLabelSource {
    match kind {
        SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate => {
            SelfGrowingEvidenceLabelSource::SelfGrowingPriceEvidence
        }
        SelfGrowingEvidenceKind::NewsContext => {
            SelfGrowingEvidenceLabelSource::SelfGrowingNewsContext
        }
        SelfGrowingEvidenceKind::SourceTrust => {
            SelfGrowingEvidenceLabelSource::SelfGrowingSourceTrust
        }
        SelfGrowingEvidenceKind::ContradictoryEvidence
        | SelfGrowingEvidenceKind::SupportingEvidence
        | SelfGrowingEvidenceKind::CoverageGapEvidence => {
            SelfGrowingEvidenceLabelSource::ReviewRequired
        }
    }
}

fn self_growing_candidate_label_from_record(
    record: &ResearchEvidenceRecord,
) -> Option<MemberExperienceOutcome> {
    match record.kind {
        ResearchEvidenceKind::PriceMove | ResearchEvidenceKind::PaperOutcomeEvidenceCandidate => {
            let thresholds = PaperPriceMoveLabelPolicy::default();
            research_price_change_from_record(record).map(|change| {
                if change >= thresholds.positive_threshold_pct {
                    MemberExperienceOutcome::PaperPositive
                } else if change <= thresholds.negative_threshold_pct {
                    MemberExperienceOutcome::PaperNegative
                } else if change.abs() <= thresholds.neutral_band_pct {
                    MemberExperienceOutcome::PaperNeutral
                } else {
                    MemberExperienceOutcome::Unknown
                }
            })
        }
        _ => None,
    }
}

fn self_growing_candidate_contains_unsafe_content(
    candidate: &SelfGrowingEvidenceCandidate,
) -> bool {
    let text =
        serde_json::to_string(candidate).unwrap_or_else(|_| candidate.evidence_notes.join("\n"));
    !research_source_unsafe_reasons(&text).is_empty()
}

fn normalize_self_growing_evidence_staging_store(
    mut store: SelfGrowingEvidenceStagingStore,
) -> SelfGrowingEvidenceStagingStore {
    store
        .candidates
        .sort_by(|left, right| left.candidate_id.cmp(&right.candidate_id));
    store.candidate_count = store.candidates.len();
    store.pending_count = store
        .candidates
        .iter()
        .filter(|candidate| {
            matches!(
                candidate.status,
                SelfGrowingEvidenceCandidateStatus::Pending
            )
        })
        .count();
    store.approved_count = store
        .candidates
        .iter()
        .filter(|candidate| {
            matches!(
                candidate.status,
                SelfGrowingEvidenceCandidateStatus::Approved
            )
        })
        .count();
    store.rejected_count = store
        .candidates
        .iter()
        .filter(|candidate| {
            matches!(
                candidate.status,
                SelfGrowingEvidenceCandidateStatus::Rejected
            )
        })
        .count();
    store.review_required_count = store
        .candidates
        .iter()
        .filter(|candidate| {
            matches!(
                candidate.status,
                SelfGrowingEvidenceCandidateStatus::ReviewRequired
            )
        })
        .count();
    store.paper_only = true;
    store
}

impl SelfGrowingEvidenceStagingStore {
    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_local_json_path(path, "self-growing evidence staging store path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        if let Some(reason) = research_source_unsafe_reasons(&text).first() {
            return Err(reason.clone());
        }
        let store: SelfGrowingEvidenceStagingStore =
            serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if !store.paper_only {
            return Err("self-growing evidence staging store must be paper-only".to_string());
        }
        Ok(normalize_self_growing_evidence_staging_store(store))
    }

    pub fn save_to_local_json(&self, path: &Path) -> Result<(), String> {
        validate_local_json_path(path, "self-growing evidence staging store output path")?;
        if !self.paper_only {
            return Err("self-growing evidence staging store must be paper-only".to_string());
        }
        if self.candidates.iter().any(|candidate| {
            !candidate.paper_only || self_growing_candidate_contains_unsafe_content(candidate)
        }) {
            return Err(
                "self-growing evidence staging store contains unsafe candidate".to_string(),
            );
        }
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
        }
        let text = serde_json::to_string_pretty(self).map_err(|err| err.to_string())?;
        fs::write(path, text).map_err(|err| err.to_string())
    }

    pub fn add_candidates(&mut self, candidates: Vec<SelfGrowingEvidenceCandidate>) {
        self.candidates.extend(candidates);
        *self = normalize_self_growing_evidence_staging_store(self.clone());
    }

    pub fn dedupe_by_candidate_id(&mut self) {
        let mut seen = std::collections::BTreeSet::new();
        self.candidates
            .retain(|candidate| seen.insert(candidate.candidate_id.clone()));
        *self = normalize_self_growing_evidence_staging_store(self.clone());
    }

    pub fn candidates_by_symbol(&self, symbol: &str) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| candidate.symbol.as_deref() == Some(symbol))
            .cloned()
            .collect()
    }

    pub fn candidates_by_member(&self, member_id: &str) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| candidate.member_id == member_id)
            .cloned()
            .collect()
    }

    pub fn pending_candidates(&self) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| {
                matches!(
                    candidate.status,
                    SelfGrowingEvidenceCandidateStatus::Pending
                )
            })
            .cloned()
            .collect()
    }

    pub fn approved_candidates(&self) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| {
                matches!(
                    candidate.status,
                    SelfGrowingEvidenceCandidateStatus::Approved
                )
            })
            .cloned()
            .collect()
    }

    pub fn rejected_candidates(&self) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| {
                matches!(
                    candidate.status,
                    SelfGrowingEvidenceCandidateStatus::Rejected
                )
            })
            .cloned()
            .collect()
    }
}

fn build_self_growing_evidence_staging_store_from_bundle(
    bundle: &ResearchEvidenceBundle,
) -> SelfGrowingEvidenceStagingStore {
    let trust_by_source: std::collections::BTreeMap<&str, SourceTrustStatus> = bundle
        .source_scores
        .iter()
        .map(|score| (score.source_id.as_str(), score.trust_status))
        .collect();
    let candidates = bundle
        .records
        .iter()
        .map(|record| SelfGrowingEvidenceCandidate {
            candidate_id: format!("candidate-{}", record.evidence_id),
            source_research_evidence_id: record.evidence_id.clone(),
            member_id: record.member_id.clone(),
            symbol: record.symbol.clone(),
            market_scope: record.market_scope,
            related_replay_id: record.related_replay_id.clone(),
            related_experience_id: record.related_experience_id.clone(),
            related_decision_id: record.related_decision_id.clone(),
            evidence_kind: self_growing_evidence_kind_for_record(record.kind),
            source_id: record.source_id.clone(),
            source_trust_status: record
                .source_id
                .as_deref()
                .and_then(|source_id| trust_by_source.get(source_id).copied())
                .unwrap_or(SourceTrustStatus::ReviewRequired),
            evidence_confidence: record.evidence_confidence,
            candidate_label: self_growing_candidate_label_from_record(record),
            label_source: self_growing_label_source_for_kind(
                self_growing_evidence_kind_for_record(record.kind),
            ),
            reference_price: None,
            horizon_price: None,
            price_change_pct: research_price_change_from_record(record),
            evidence_notes: record.evidence_notes.clone(),
            status: SelfGrowingEvidenceCandidateStatus::Pending,
            paper_only: true,
        })
        .collect();
    normalize_self_growing_evidence_staging_store(SelfGrowingEvidenceStagingStore {
        store_id: format!("{}-staging-store", bundle.bundle_id),
        candidates,
        candidate_count: 0,
        pending_count: 0,
        approved_count: 0,
        rejected_count: 0,
        review_required_count: 0,
        paper_only: true,
    })
}

fn self_growing_source_trust_score(status: SourceTrustStatus) -> f64 {
    match status {
        SourceTrustStatus::Trusted => 1.0,
        SourceTrustStatus::UsableWithWarnings => 0.75,
        SourceTrustStatus::ReviewRequired => 0.35,
        SourceTrustStatus::Rejected => 0.0,
    }
}

fn self_growing_replay_link_score(candidate: &SelfGrowingEvidenceCandidate) -> f64 {
    if candidate.related_replay_id.is_some() {
        1.0
    } else if candidate.related_decision_id.is_some() && candidate.related_experience_id.is_some() {
        0.8
    } else if candidate.related_decision_id.is_some() || candidate.related_experience_id.is_some() {
        0.55
    } else {
        0.1
    }
}

fn self_growing_evidence_type_score(kind: SelfGrowingEvidenceKind) -> f64 {
    match kind {
        SelfGrowingEvidenceKind::PriceMove => 1.0,
        SelfGrowingEvidenceKind::PaperOutcomeCandidate => 0.9,
        SelfGrowingEvidenceKind::ContradictoryEvidence => 0.7,
        SelfGrowingEvidenceKind::SupportingEvidence => 0.6,
        SelfGrowingEvidenceKind::CoverageGapEvidence => 0.5,
        SelfGrowingEvidenceKind::SourceTrust => 0.35,
        SelfGrowingEvidenceKind::NewsContext => 0.2,
    }
}

fn self_growing_label_strength_score(candidate: &SelfGrowingEvidenceCandidate) -> f64 {
    match candidate.candidate_label {
        Some(MemberExperienceOutcome::PaperPositive)
        | Some(MemberExperienceOutcome::PaperNegative)
        | Some(MemberExperienceOutcome::PaperNeutral) => 1.0,
        Some(MemberExperienceOutcome::Unknown) | None => 0.2,
        Some(_) => 0.4,
    }
}

pub fn score_self_growing_evidence_candidate(
    candidate: &SelfGrowingEvidenceCandidate,
    source_scores: &[SourceTrustScore],
) -> EvidenceCandidateScore {
    let source_score_lookup: std::collections::BTreeMap<&str, &SourceTrustScore> = source_scores
        .iter()
        .map(|score| (score.source_id.as_str(), score))
        .collect();
    let source_score = candidate
        .source_id
        .as_deref()
        .and_then(|source_id| source_score_lookup.get(source_id).copied());
    let effective_trust_status = source_score
        .map(|score| score.trust_status)
        .unwrap_or(candidate.source_trust_status);
    let source_trust_score = source_score
        .map(|score| score.final_score)
        .unwrap_or_else(|| self_growing_source_trust_score(effective_trust_status));
    let replay_link_score = self_growing_replay_link_score(candidate);
    let evidence_type_score = self_growing_evidence_type_score(candidate.evidence_kind);
    let label_strength_score = self_growing_label_strength_score(candidate);
    let unsafe_candidate =
        self_growing_candidate_contains_unsafe_content(candidate) || !candidate.paper_only;
    let safety_score = if unsafe_candidate { 0.0 } else { 1.0 };
    let mut total_score = clamp_unit(
        (source_trust_score
            + replay_link_score
            + evidence_type_score
            + label_strength_score
            + safety_score)
            / 5.0,
    );
    let mut reasons = Vec::new();
    if candidate.related_replay_id.is_some() {
        reasons.push("exact replay_id linked".to_string());
    } else if candidate.related_decision_id.is_some() || candidate.related_experience_id.is_some() {
        reasons.push("partial replay linkage only".to_string());
    } else {
        reasons.push("missing replay linkage".to_string());
    }
    if matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::NewsContext
    ) {
        reasons.push("news-only evidence cannot auto-promote label".to_string());
    }
    let score_status =
        if unsafe_candidate || matches!(effective_trust_status, SourceTrustStatus::Rejected) {
            total_score = 0.0;
            reasons.push("unsafe or rejected source".to_string());
            EvidenceCandidateScoreStatus::Rejected
        } else if matches!(effective_trust_status, SourceTrustStatus::ReviewRequired) {
            reasons.push("source review required caps candidate strength".to_string());
            EvidenceCandidateScoreStatus::Weak
        } else if source_trust_score < 0.5 {
            total_score = total_score.min(0.49);
            reasons.push("low-trust source caps score".to_string());
            EvidenceCandidateScoreStatus::Weak
        } else if total_score >= 0.8 {
            EvidenceCandidateScoreStatus::Strong
        } else if total_score >= 0.65 {
            EvidenceCandidateScoreStatus::Acceptable
        } else {
            EvidenceCandidateScoreStatus::Weak
        };
    EvidenceCandidateScore {
        candidate_id: candidate.candidate_id.clone(),
        source_trust_score,
        replay_link_score,
        evidence_type_score,
        label_strength_score,
        safety_score,
        total_score,
        score_status,
        reasons,
        paper_only: true,
    }
}

fn self_growing_candidate_has_exact_match(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    candidate.related_replay_id.is_some()
}

fn self_growing_candidate_missing_all_links(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    candidate.related_replay_id.is_none()
        && candidate.related_decision_id.is_none()
        && candidate.related_experience_id.is_none()
}

fn self_growing_generated_paper_evidence(
    candidate: &SelfGrowingEvidenceCandidate,
) -> Option<PaperOutcomeEvidenceRecord> {
    let candidate_label = candidate.candidate_label?;
    if matches!(candidate_label, MemberExperienceOutcome::Unknown) {
        return None;
    }
    let market_scope = candidate.market_scope.unwrap_or(MarketScope::UsShortTerm);
    Some(PaperOutcomeEvidenceRecord {
        evidence_id: format!("approved-{}", candidate.candidate_id),
        symbol: candidate
            .symbol
            .clone()
            .unwrap_or_else(|| "UNKNOWN".to_string()),
        market_scope,
        decision_id: candidate.related_decision_id.clone(),
        event_id: None,
        replay_id: candidate.related_replay_id.clone(),
        experience_id: candidate.related_experience_id.clone(),
        horizon: replay_evidence_horizon_for_scope(market_scope),
        horizon_bars: price_horizon_bars(replay_evidence_horizon_for_scope(market_scope)),
        reference_price: candidate.reference_price,
        horizon_price: candidate.horizon_price,
        price_change_pct: candidate.price_change_pct.or_else(|| {
            candidate.evidence_notes.iter().find_map(|note| {
                note.strip_prefix("price_change_pct=")
                    .and_then(|value| value.parse().ok())
            })
        }),
        candidate_label,
        label_source: ReplayLabelSource::ManualPaperLabel,
        label_confidence: match candidate.evidence_confidence {
            ReplayLabelConfidence::High => ReplayLabelConfidence::High,
            ReplayLabelConfidence::Medium => ReplayLabelConfidence::Medium,
            ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired => {
                ReplayLabelConfidence::Medium
            }
        },
        evidence_notes: candidate.evidence_notes.clone(),
        validation_hint: Some(PaperOutcomeEvidenceValidationHint::PromoteIfPolicyPasses),
        paper_only: true,
    })
}

pub fn evaluate_self_growing_evidence_promotion(
    candidate: &SelfGrowingEvidenceCandidate,
    score: &EvidenceCandidateScore,
    policy: &SelfGrowingEvidencePromotionPolicy,
) -> SelfGrowingEvidencePromotionDecision {
    let unsafe_candidate =
        self_growing_candidate_contains_unsafe_content(candidate) || !candidate.paper_only;
    let missing_price_label = policy.require_price_move_label
        && matches!(
            candidate.evidence_kind,
            SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate
        )
        && !matches!(
            candidate.candidate_label,
            Some(MemberExperienceOutcome::PaperPositive)
                | Some(MemberExperienceOutcome::PaperNegative)
                | Some(MemberExperienceOutcome::PaperNeutral)
        );
    let missing_link = policy.require_replay_or_decision_id
        && candidate.related_replay_id.is_none()
        && candidate.related_decision_id.is_none();
    let ambiguous_match = !self_growing_candidate_has_exact_match(candidate)
        && !self_growing_candidate_missing_all_links(candidate);
    let news_only = matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::NewsContext
    );
    let low_trust = matches!(
        candidate.source_trust_status,
        SourceTrustStatus::ReviewRequired | SourceTrustStatus::Rejected
    ) || score.source_trust_score < 0.5;
    let strong_enough = matches!(
        score.score_status,
        EvidenceCandidateScoreStatus::Strong | EvidenceCandidateScoreStatus::Acceptable
    ) && score.total_score >= policy.min_score_for_auto_approval;
    let trusted_enough = if policy.require_validated_source_trust {
        matches!(
            candidate.source_trust_status,
            SourceTrustStatus::Trusted | SourceTrustStatus::UsableWithWarnings
        )
    } else {
        !matches!(candidate.source_trust_status, SourceTrustStatus::Rejected)
    };
    let decision = if unsafe_candidate
        || matches!(score.score_status, EvidenceCandidateScoreStatus::Rejected)
    {
        SelfGrowingEvidencePromotionDecisionStatus::Rejected
    } else if news_only && !policy.allow_auto_approve_news_only {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if low_trust && !policy.allow_low_trust_promotion {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if missing_link {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if ambiguous_match && !policy.allow_ambiguous_match_promotion {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if missing_price_label {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if policy.allow_auto_approve_exact_price_evidence
        && matches!(
            candidate.evidence_kind,
            SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate
        )
        && self_growing_candidate_has_exact_match(candidate)
        && trusted_enough
        && strong_enough
    {
        SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
    } else {
        SelfGrowingEvidencePromotionDecisionStatus::KeptStaged
    };
    let reason = match decision {
        SelfGrowingEvidencePromotionDecisionStatus::AutoApproved => {
            "exact price evidence passed promotion gate".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if news_only => {
            "news-only evidence must stay in review".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if low_trust => {
            "low-trust or review-required source must stay in review".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if missing_link => {
            "missing replay or decision linkage".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if ambiguous_match => {
            "ambiguous replay linkage".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if missing_price_label => {
            "price evidence missing promotable label".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::Rejected => {
            "unsafe or rejected candidate blocked".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::KeptStaged => {
            "candidate kept staged pending stronger evidence".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview => {
            "candidate requires review".to_string()
        }
    };
    SelfGrowingEvidencePromotionDecision {
        candidate_id: candidate.candidate_id.clone(),
        score: score.clone(),
        decision,
        reason,
        generated_paper_evidence: matches!(
            decision,
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
        )
        .then(|| self_growing_generated_paper_evidence(candidate))
        .flatten(),
        paper_only: true,
    }
}

pub fn build_staged_evidence_review_queue(
    candidates: &[SelfGrowingEvidenceCandidate],
    promotion_decisions: &[SelfGrowingEvidencePromotionDecision],
) -> StagedEvidenceReviewQueue {
    let candidate_by_id: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    let mut items = Vec::new();
    for decision in promotion_decisions {
        let Some(candidate) = candidate_by_id.get(decision.candidate_id.as_str()).copied() else {
            continue;
        };
        let Some((review_reason, suggested_action, priority)) = (match decision.decision {
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved => None,
            SelfGrowingEvidencePromotionDecisionStatus::Rejected => Some((
                StagedEvidenceReviewReason::UnsafeRejected,
                StagedEvidenceReviewSuggestedAction::Reject,
                WeakReplayLabelPriority::High,
            )),
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if matches!(
                    candidate.evidence_kind,
                    SelfGrowingEvidenceKind::NewsContext
                ) =>
            {
                Some((
                    StagedEvidenceReviewReason::NewsOnlyEvidence,
                    StagedEvidenceReviewSuggestedAction::AddPriceEvidence,
                    WeakReplayLabelPriority::Normal,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if self_growing_candidate_missing_all_links(candidate) =>
            {
                Some((
                    StagedEvidenceReviewReason::MissingReplayId,
                    StagedEvidenceReviewSuggestedAction::AddReplayId,
                    WeakReplayLabelPriority::High,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if !self_growing_candidate_has_exact_match(candidate) =>
            {
                Some((
                    StagedEvidenceReviewReason::AmbiguousReplayMatch,
                    StagedEvidenceReviewSuggestedAction::AddDecisionId,
                    WeakReplayLabelPriority::High,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if matches!(
                    candidate.source_trust_status,
                    SourceTrustStatus::ReviewRequired
                ) =>
            {
                Some((
                    StagedEvidenceReviewReason::SourceReviewRequired,
                    StagedEvidenceReviewSuggestedAction::AddSourceValidation,
                    WeakReplayLabelPriority::Normal,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if decision.score.source_trust_score < 0.5 =>
            {
                Some((
                    StagedEvidenceReviewReason::LowTrustSource,
                    StagedEvidenceReviewSuggestedAction::AddSourceValidation,
                    WeakReplayLabelPriority::High,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview => Some((
                StagedEvidenceReviewReason::MissingPriceEvidence,
                StagedEvidenceReviewSuggestedAction::KeepStaged,
                WeakReplayLabelPriority::Normal,
            )),
            SelfGrowingEvidencePromotionDecisionStatus::KeptStaged => Some((
                StagedEvidenceReviewReason::MissingPriceEvidence,
                StagedEvidenceReviewSuggestedAction::KeepStaged,
                WeakReplayLabelPriority::Low,
            )),
        }) else {
            continue;
        };
        items.push(StagedEvidenceReviewItem {
            review_item_id: format!("review-{}", candidate.candidate_id),
            candidate_id: candidate.candidate_id.clone(),
            member_id: candidate.member_id.clone(),
            symbol: candidate.symbol.clone(),
            market_scope: candidate.market_scope,
            review_reason,
            suggested_action,
            priority,
            paper_only: true,
        });
    }
    items.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.review_item_id.cmp(&right.review_item_id))
    });
    StagedEvidenceReviewQueue {
        queue_id: "self-growing-evidence-review-queue".to_string(),
        high_priority_count: items
            .iter()
            .filter(|item| item.priority == WeakReplayLabelPriority::High)
            .count(),
        items,
        paper_only: true,
    }
}

fn self_growing_candidate_has_price_evidence(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    candidate.price_change_pct.is_some()
        || candidate
            .evidence_notes
            .iter()
            .any(|note| note.starts_with("price_change_pct="))
}

fn self_growing_candidate_is_news_only(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::NewsContext
    )
}

fn self_growing_candidate_is_low_trust(
    candidate: &SelfGrowingEvidenceCandidate,
    score: &EvidenceCandidateScore,
) -> bool {
    matches!(
        candidate.source_trust_status,
        SourceTrustStatus::ReviewRequired | SourceTrustStatus::Rejected
    ) || score.source_trust_score < 0.5
}

fn self_growing_candidate_is_ambiguous(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    !self_growing_candidate_has_exact_match(candidate)
        && !self_growing_candidate_missing_all_links(candidate)
}

fn self_growing_candidate_is_safe_exact_price_evidence(
    candidate: &SelfGrowingEvidenceCandidate,
    score: &EvidenceCandidateScore,
) -> bool {
    matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate
    ) && self_growing_candidate_has_exact_match(candidate)
        && self_growing_candidate_has_price_evidence(candidate)
        && matches!(
            candidate.candidate_label,
            Some(MemberExperienceOutcome::PaperPositive)
                | Some(MemberExperienceOutcome::PaperNegative)
                | Some(MemberExperienceOutcome::PaperNeutral)
        )
        && !self_growing_candidate_is_low_trust(candidate, score)
        && !self_growing_candidate_is_ambiguous(candidate)
        && !self_growing_candidate_contains_unsafe_content(candidate)
        && candidate.paper_only
}

fn push_unique_note(notes: &mut Vec<String>, note: String) {
    if !notes.iter().any(|existing| existing == &note) {
        notes.push(note);
    }
}

fn staged_evidence_failure_reasons(
    candidate: &SelfGrowingEvidenceCandidate,
    decision: &SelfGrowingEvidencePromotionDecision,
) -> Vec<StagedEvidenceFailureReason> {
    let mut reasons = Vec::new();
    if !candidate.paper_only {
        reasons.push(StagedEvidenceFailureReason::NotPaperOnly);
    }
    if self_growing_candidate_contains_unsafe_content(candidate) {
        reasons.push(StagedEvidenceFailureReason::UnsafeEvidence);
    }
    if candidate.related_replay_id.is_none() {
        reasons.push(StagedEvidenceFailureReason::MissingReplayId);
    }
    if candidate.related_decision_id.is_none() {
        reasons.push(StagedEvidenceFailureReason::MissingDecisionId);
    }
    if candidate.related_experience_id.is_none() {
        reasons.push(StagedEvidenceFailureReason::MissingExperienceId);
    }
    if self_growing_candidate_is_news_only(candidate) {
        reasons.push(StagedEvidenceFailureReason::NewsOnlyEvidence);
    }
    if matches!(
        candidate.source_trust_status,
        SourceTrustStatus::ReviewRequired
    ) {
        reasons.push(StagedEvidenceFailureReason::SourceReviewRequired);
    }
    if self_growing_candidate_is_low_trust(candidate, &decision.score) {
        reasons.push(StagedEvidenceFailureReason::LowTrustSource);
    }
    if self_growing_candidate_is_ambiguous(candidate) {
        reasons.push(StagedEvidenceFailureReason::AmbiguousReplayMatch);
    }
    if !self_growing_candidate_has_price_evidence(candidate)
        && matches!(
            candidate.evidence_kind,
            SelfGrowingEvidenceKind::PriceMove
                | SelfGrowingEvidenceKind::PaperOutcomeCandidate
                | SelfGrowingEvidenceKind::NewsContext
        )
    {
        reasons.push(StagedEvidenceFailureReason::MissingPriceEvidence);
    }
    if matches!(
        decision.decision,
        SelfGrowingEvidencePromotionDecisionStatus::Rejected
    ) && !reasons.contains(&StagedEvidenceFailureReason::UnsafeEvidence)
    {
        reasons.push(StagedEvidenceFailureReason::UnsafeEvidence);
    }
    reasons
}

fn staged_evidence_suggested_fix(
    reasons: &[StagedEvidenceFailureReason],
) -> StagedEvidenceSuggestedFix {
    if reasons.contains(&StagedEvidenceFailureReason::UnsafeEvidence)
        || reasons.contains(&StagedEvidenceFailureReason::NotPaperOnly)
    {
        return StagedEvidenceSuggestedFix::RejectCandidate;
    }
    if reasons.contains(&StagedEvidenceFailureReason::MissingReplayId) {
        return StagedEvidenceSuggestedFix::LinkReplayId;
    }
    if reasons.contains(&StagedEvidenceFailureReason::MissingDecisionId) {
        return StagedEvidenceSuggestedFix::LinkDecisionId;
    }
    if reasons.contains(&StagedEvidenceFailureReason::MissingExperienceId) {
        return StagedEvidenceSuggestedFix::LinkExperienceId;
    }
    if reasons.contains(&StagedEvidenceFailureReason::MissingPriceEvidence)
        || reasons.contains(&StagedEvidenceFailureReason::NewsOnlyEvidence)
    {
        return StagedEvidenceSuggestedFix::AttachLocalPriceEvidence;
    }
    if reasons.contains(&StagedEvidenceFailureReason::LowTrustSource)
        || reasons.contains(&StagedEvidenceFailureReason::SourceReviewRequired)
    {
        return StagedEvidenceSuggestedFix::ImproveSourceTrust;
    }
    StagedEvidenceSuggestedFix::KeepInReview
}

pub fn analyze_staged_evidence_review_queue(
    candidates: &[SelfGrowingEvidenceCandidate],
    promotion_decisions: &[SelfGrowingEvidencePromotionDecision],
) -> StagedEvidenceReviewAnalysis {
    let candidate_by_id: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    let mut review_items = Vec::new();
    let mut missing_replay_link_count = 0;
    let mut news_only_count = 0;
    let mut low_trust_count = 0;
    let mut ambiguous_count = 0;
    let mut missing_price_evidence_count = 0;
    let mut unsafe_count = 0;
    for decision in promotion_decisions {
        let Some(candidate) = candidate_by_id.get(decision.candidate_id.as_str()).copied() else {
            continue;
        };
        let reasons = staged_evidence_failure_reasons(candidate, decision);
        if reasons.contains(&StagedEvidenceFailureReason::MissingReplayId) {
            missing_replay_link_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::NewsOnlyEvidence) {
            news_only_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::LowTrustSource)
            || reasons.contains(&StagedEvidenceFailureReason::SourceReviewRequired)
        {
            low_trust_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::AmbiguousReplayMatch) {
            ambiguous_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::MissingPriceEvidence) {
            missing_price_evidence_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::UnsafeEvidence)
            || reasons.contains(&StagedEvidenceFailureReason::NotPaperOnly)
        {
            unsafe_count += 1;
        }
        if matches!(
            decision.decision,
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
        ) {
            continue;
        }
        review_items.push(StagedEvidenceReviewAnalysisItem {
            candidate_id: candidate.candidate_id.clone(),
            member_id: candidate.member_id.clone(),
            symbol: candidate.symbol.clone(),
            market_scope: candidate.market_scope,
            evidence_kind: candidate.evidence_kind,
            current_score_status: decision.score.score_status,
            current_promotion_decision: decision.decision,
            suggested_fix: staged_evidence_suggested_fix(&reasons),
            failure_reasons: reasons,
            paper_only: candidate.paper_only,
        });
    }
    StagedEvidenceReviewAnalysis {
        analysis_id: "staged-evidence-review-analysis".to_string(),
        candidate_count: promotion_decisions.len(),
        auto_approved_count: promotion_decisions
            .iter()
            .filter(|decision| {
                matches!(
                    decision.decision,
                    SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
                )
            })
            .count(),
        needs_review_count: promotion_decisions
            .iter()
            .filter(|decision| {
                matches!(
                    decision.decision,
                    SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                        | SelfGrowingEvidencePromotionDecisionStatus::KeptStaged
                )
            })
            .count(),
        rejected_count: promotion_decisions
            .iter()
            .filter(|decision| {
                matches!(
                    decision.decision,
                    SelfGrowingEvidencePromotionDecisionStatus::Rejected
                )
            })
            .count(),
        missing_replay_link_count,
        news_only_count,
        low_trust_count,
        ambiguous_count,
        missing_price_evidence_count,
        unsafe_count,
        review_items,
        paper_only: true,
    }
}

fn replay_examples_for_experience_id<'a>(
    dataset: &'a ReplayDataset,
    experience_id: &str,
) -> Vec<&'a ReplayExample> {
    dataset
        .examples
        .iter()
        .filter(|example| replay_example_experience_id(example).as_deref() == Some(experience_id))
        .collect()
}

fn replay_examples_for_decision_id<'a>(
    dataset: &'a ReplayDataset,
    experience_store: &MemberExperienceStore,
    decision_id: &str,
) -> Vec<&'a ReplayExample> {
    dataset
        .examples
        .iter()
        .filter(|example| {
            replay_example_decision_id(example, experience_store).as_deref() == Some(decision_id)
        })
        .collect()
}

fn replay_examples_for_symbol_scope<'a>(
    dataset: &'a ReplayDataset,
    symbol: &str,
    market_scope: MarketScope,
) -> Vec<&'a ReplayExample> {
    dataset
        .examples
        .iter()
        .filter(|example| example.symbol == symbol && example.market_scope == market_scope)
        .collect()
}

fn filter_link_matches_for_candidate<'a>(
    candidate: &SelfGrowingEvidenceCandidate,
    matches: Vec<&'a ReplayExample>,
) -> Vec<&'a ReplayExample> {
    matches
        .into_iter()
        .filter(|example| {
            candidate
                .symbol
                .as_deref()
                .map(|symbol| example.symbol == symbol)
                .unwrap_or(true)
                && candidate
                    .market_scope
                    .map(|market_scope| example.market_scope == market_scope)
                    .unwrap_or(true)
                && example.member_id == candidate.member_id
        })
        .collect()
}

fn staged_link_candidate_from_example(
    candidate: &SelfGrowingEvidenceCandidate,
    example: &ReplayExample,
    experience_store: &MemberExperienceStore,
    match_type: StagedEvidenceLinkMatchType,
    match_confidence: StagedEvidenceLinkMatchConfidence,
    link_safe: bool,
    unsafe_reason: Option<String>,
) -> StagedEvidenceLinkCandidate {
    StagedEvidenceLinkCandidate {
        candidate_id: candidate.candidate_id.clone(),
        suggested_replay_id: Some(example.replay_id.clone()),
        suggested_experience_id: replay_example_experience_id(example)
            .or_else(|| candidate.related_experience_id.clone()),
        suggested_decision_id: replay_example_decision_id(example, experience_store)
            .or_else(|| candidate.related_decision_id.clone()),
        match_type,
        match_confidence,
        link_safe,
        unsafe_reason,
        paper_only: true,
    }
}

pub fn resolve_staged_evidence_links(
    candidates: &[SelfGrowingEvidenceCandidate],
    dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    policy: &StagedEvidenceLinkResolutionPolicy,
) -> StagedEvidenceLinkResolutionResult {
    if !policy.paper_only {
        return StagedEvidenceLinkResolutionResult {
            resolved_count: 0,
            unresolved_count: candidates.len(),
            unsafe_count: candidates.len(),
            link_candidates: candidates
                .iter()
                .map(|candidate| StagedEvidenceLinkCandidate {
                    candidate_id: candidate.candidate_id.clone(),
                    suggested_replay_id: None,
                    suggested_experience_id: candidate.related_experience_id.clone(),
                    suggested_decision_id: candidate.related_decision_id.clone(),
                    match_type: StagedEvidenceLinkMatchType::NoMatch,
                    match_confidence: StagedEvidenceLinkMatchConfidence::None,
                    link_safe: false,
                    unsafe_reason: Some(
                        "staged evidence link resolution policy must remain paper-only".to_string(),
                    ),
                    paper_only: true,
                })
                .collect(),
            paper_only: true,
        };
    }
    let link_candidates: Vec<StagedEvidenceLinkCandidate> = candidates
        .iter()
        .map(|candidate| {
            if !candidate.paper_only || self_growing_candidate_contains_unsafe_content(candidate) {
                return StagedEvidenceLinkCandidate {
                    candidate_id: candidate.candidate_id.clone(),
                    suggested_replay_id: None,
                    suggested_experience_id: candidate.related_experience_id.clone(),
                    suggested_decision_id: candidate.related_decision_id.clone(),
                    match_type: StagedEvidenceLinkMatchType::NoMatch,
                    match_confidence: StagedEvidenceLinkMatchConfidence::None,
                    link_safe: false,
                    unsafe_reason: Some("candidate is not safe for link resolution".to_string()),
                    paper_only: true,
                };
            }
            if policy.reject_unknown_horizon && candidate.market_scope.is_none() {
                return StagedEvidenceLinkCandidate {
                    candidate_id: candidate.candidate_id.clone(),
                    suggested_replay_id: None,
                    suggested_experience_id: candidate.related_experience_id.clone(),
                    suggested_decision_id: candidate.related_decision_id.clone(),
                    match_type: StagedEvidenceLinkMatchType::NoMatch,
                    match_confidence: StagedEvidenceLinkMatchConfidence::None,
                    link_safe: false,
                    unsafe_reason: Some("candidate market_scope is required for exact replay linking".to_string()),
                    paper_only: true,
                };
            }
            if policy.allow_replay_id_link {
                if let Some(replay_id) = candidate.related_replay_id.as_deref() {
                    let exact_matches = filter_link_matches_for_candidate(
                        candidate,
                        dataset
                            .examples
                            .iter()
                            .filter(|example| example.replay_id == replay_id)
                            .collect(),
                    );
                    match unique_match(exact_matches) {
                        Ok(Some(example)) => {
                            return staged_link_candidate_from_example(
                                candidate,
                                example,
                                experience_store,
                                StagedEvidenceLinkMatchType::ReplayId,
                                StagedEvidenceLinkMatchConfidence::High,
                                true,
                                None,
                            );
                        }
                        Err(_) | Ok(None) => {
                            return StagedEvidenceLinkCandidate {
                                candidate_id: candidate.candidate_id.clone(),
                                suggested_replay_id: candidate.related_replay_id.clone(),
                                suggested_experience_id: candidate.related_experience_id.clone(),
                                suggested_decision_id: candidate.related_decision_id.clone(),
                                match_type: StagedEvidenceLinkMatchType::ReplayId,
                                match_confidence: StagedEvidenceLinkMatchConfidence::Low,
                                link_safe: false,
                                unsafe_reason: Some(
                                    "candidate replay_id did not resolve to a unique replay example".to_string(),
                                ),
                                paper_only: true,
                            };
                        }
                    }
                }
            }
            if policy.allow_experience_id_link {
                if let Some(experience_id) = candidate.related_experience_id.as_deref() {
                    let matches = filter_link_matches_for_candidate(
                        candidate,
                        replay_examples_for_experience_id(dataset, experience_id),
                    );
                    match unique_match(matches) {
                        Ok(Some(example)) => {
                            return staged_link_candidate_from_example(
                                candidate,
                                example,
                                experience_store,
                                StagedEvidenceLinkMatchType::ExperienceId,
                                StagedEvidenceLinkMatchConfidence::High,
                                true,
                                None,
                            );
                        }
                        Err(_) => {
                            return StagedEvidenceLinkCandidate {
                                candidate_id: candidate.candidate_id.clone(),
                                suggested_replay_id: None,
                                suggested_experience_id: candidate.related_experience_id.clone(),
                                suggested_decision_id: candidate.related_decision_id.clone(),
                                match_type: StagedEvidenceLinkMatchType::ExperienceId,
                                match_confidence: StagedEvidenceLinkMatchConfidence::Low,
                                link_safe: false,
                                unsafe_reason: Some(
                                    "experience_id resolves to multiple replay examples".to_string(),
                                ),
                                paper_only: true,
                            };
                        }
                        Ok(None) => {}
                    }
                }
            }
            if policy.allow_decision_id_link {
                if let Some(decision_id) = candidate.related_decision_id.as_deref() {
                    let matches = filter_link_matches_for_candidate(
                        candidate,
                        replay_examples_for_decision_id(dataset, experience_store, decision_id),
                    );
                    match unique_match(matches) {
                        Ok(Some(example)) => {
                            return staged_link_candidate_from_example(
                                candidate,
                                example,
                                experience_store,
                                StagedEvidenceLinkMatchType::DecisionId,
                                StagedEvidenceLinkMatchConfidence::High,
                                true,
                                None,
                            );
                        }
                        Err(_) => {
                            return StagedEvidenceLinkCandidate {
                                candidate_id: candidate.candidate_id.clone(),
                                suggested_replay_id: None,
                                suggested_experience_id: candidate.related_experience_id.clone(),
                                suggested_decision_id: candidate.related_decision_id.clone(),
                                match_type: StagedEvidenceLinkMatchType::DecisionId,
                                match_confidence: StagedEvidenceLinkMatchConfidence::Low,
                                link_safe: false,
                                unsafe_reason: Some(
                                    "decision_id resolves to multiple replay examples".to_string(),
                                ),
                                paper_only: true,
                            };
                        }
                        Ok(None) => {}
                    }
                }
            }
            if policy.allow_symbol_scope_unique_match {
                if let (Some(symbol), Some(market_scope)) =
                    (candidate.symbol.as_deref(), candidate.market_scope)
                {
                    let matches =
                        replay_examples_for_symbol_scope(dataset, symbol, market_scope)
                            .into_iter()
                            .filter(|example| example.member_id == candidate.member_id)
                            .collect::<Vec<_>>();
                    match unique_match(matches) {
                        Ok(Some(example)) => {
                            let symbol_scope_only = candidate.related_replay_id.is_none()
                                && candidate.related_experience_id.is_none()
                                && candidate.related_decision_id.is_none();
                            let link_safe = !(symbol_scope_only && policy.reject_symbol_scope_only);
                            let match_type = if symbol_scope_only {
                                StagedEvidenceLinkMatchType::SymbolScopeOnly
                            } else {
                                StagedEvidenceLinkMatchType::UniqueSymbolScopeHorizon
                            };
                            return staged_link_candidate_from_example(
                                candidate,
                                example,
                                experience_store,
                                match_type,
                                if link_safe {
                                    StagedEvidenceLinkMatchConfidence::Medium
                                } else {
                                    StagedEvidenceLinkMatchConfidence::Low
                                },
                                link_safe,
                                (!link_safe).then(|| {
                                    "symbol/scope-only replay linking stays review-only".to_string()
                                }),
                            );
                        }
                        Err(_) => {
                            return StagedEvidenceLinkCandidate {
                                candidate_id: candidate.candidate_id.clone(),
                                suggested_replay_id: None,
                                suggested_experience_id: candidate.related_experience_id.clone(),
                                suggested_decision_id: candidate.related_decision_id.clone(),
                                match_type: StagedEvidenceLinkMatchType::UniqueSymbolScopeHorizon,
                                match_confidence: StagedEvidenceLinkMatchConfidence::Low,
                                link_safe: false,
                                unsafe_reason: Some(
                                    "symbol/scope resolves to multiple replay examples".to_string(),
                                ),
                                paper_only: true,
                            };
                        }
                        Ok(None) => {}
                    }
                }
            }
            StagedEvidenceLinkCandidate {
                candidate_id: candidate.candidate_id.clone(),
                suggested_replay_id: None,
                suggested_experience_id: candidate.related_experience_id.clone(),
                suggested_decision_id: candidate.related_decision_id.clone(),
                match_type: StagedEvidenceLinkMatchType::NoMatch,
                match_confidence: StagedEvidenceLinkMatchConfidence::None,
                link_safe: false,
                unsafe_reason: Some("no safe exact replay link candidate found".to_string()),
                paper_only: true,
            }
        })
        .collect();
    StagedEvidenceLinkResolutionResult {
        resolved_count: link_candidates
            .iter()
            .filter(|candidate| candidate.link_safe && candidate.suggested_replay_id.is_some())
            .count(),
        unresolved_count: link_candidates
            .iter()
            .filter(|candidate| candidate.suggested_replay_id.is_none())
            .count(),
        unsafe_count: link_candidates
            .iter()
            .filter(|candidate| !candidate.link_safe)
            .count(),
        link_candidates,
        paper_only: true,
    }
}

fn self_growing_candidate_label_from_price_change(
    change: f64,
    policy: &StagedEvidencePriceEnrichmentPolicy,
) -> MemberExperienceOutcome {
    if change >= policy.positive_threshold_pct {
        MemberExperienceOutcome::PaperPositive
    } else if change <= policy.negative_threshold_pct {
        MemberExperienceOutcome::PaperNegative
    } else if change.abs() <= policy.neutral_band_pct {
        MemberExperienceOutcome::PaperNeutral
    } else {
        MemberExperienceOutcome::Unknown
    }
}

fn apply_link_resolutions_to_candidates(
    candidates: &[SelfGrowingEvidenceCandidate],
    link_resolution_result: &StagedEvidenceLinkResolutionResult,
) -> Vec<SelfGrowingEvidenceCandidate> {
    let link_by_candidate: std::collections::BTreeMap<&str, &StagedEvidenceLinkCandidate> =
        link_resolution_result
            .link_candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    candidates
        .iter()
        .map(|candidate| {
            let mut updated = candidate.clone();
            if let Some(link) = link_by_candidate.get(candidate.candidate_id.as_str()) {
                if link.link_safe {
                    if updated.related_replay_id.is_none() {
                        updated.related_replay_id = link.suggested_replay_id.clone();
                    }
                    if updated.related_experience_id.is_none() {
                        updated.related_experience_id = link.suggested_experience_id.clone();
                    }
                    if updated.related_decision_id.is_none() {
                        updated.related_decision_id = link.suggested_decision_id.clone();
                    }
                    if let Some(replay_id) = link.suggested_replay_id.as_deref() {
                        push_unique_note(
                            &mut updated.evidence_notes,
                            format!("resolved_replay_id={replay_id}"),
                        );
                    }
                }
            }
            updated
        })
        .collect()
}

pub fn enrich_staged_evidence_with_local_price_series(
    candidates: &[SelfGrowingEvidenceCandidate],
    price_series_store: &PaperPriceSeriesStore,
    policy: &StagedEvidencePriceEnrichmentPolicy,
) -> StagedEvidencePriceEnrichmentResult {
    if !policy.paper_only || !policy.allow_local_price_series {
        return StagedEvidencePriceEnrichmentResult {
            enriched_count: 0,
            needs_more_price_data_count: candidates.len(),
            rejected_count: 0,
            enrichments: candidates
                .iter()
                .map(|candidate| StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: candidate
                        .symbol
                        .clone()
                        .unwrap_or_else(|| "UNKNOWN".to_string()),
                    market_scope: candidate.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: candidate
                        .candidate_label
                        .unwrap_or(MemberExperienceOutcome::Unknown),
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NotApplicable,
                    evidence_notes: vec![
                        "local price enrichment policy is disabled or not paper-only".to_string(),
                    ],
                    paper_only: true,
                })
                .collect(),
            paper_only: true,
        };
    }
    let enrichments: Vec<StagedEvidencePriceEnrichment> = candidates
        .iter()
        .map(|candidate| {
            let Some(symbol) = candidate.symbol.as_deref() else {
                return StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: "UNKNOWN".to_string(),
                    market_scope: candidate.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NotApplicable,
                    evidence_notes: vec![
                        "candidate symbol missing for local price enrichment".to_string(),
                    ],
                    paper_only: true,
                };
            };
            let Some(market_scope) = candidate.market_scope else {
                return StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope: MarketScope::UsShortTerm,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NotApplicable,
                    evidence_notes: vec![
                        "candidate market_scope missing for local price enrichment".to_string(),
                    ],
                    paper_only: true,
                };
            };
            let horizon = replay_evidence_horizon_for_scope(market_scope);
            let Some(series) = price_series_store.series_for_symbol_scope(symbol, market_scope)
            else {
                return StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::SymbolScopeMismatch,
                    evidence_notes: vec![
                        "no exact local price series for symbol/scope".to_string(),
                    ],
                    paper_only: true,
                };
            };
            let horizon_bars = price_horizon_bars(horizon).unwrap_or(0);
            if policy.require_min_bars && series.bars.len() <= horizon_bars as usize {
                return StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NeedsMorePriceData,
                    evidence_notes: vec!["local price series has insufficient bars".to_string()],
                    paper_only: true,
                };
            }
            match find_reference_and_horizon_price(
                price_series_store,
                symbol,
                market_scope,
                horizon,
                None,
            ) {
                Some((reference_price, horizon_price, resolved_bars))
                    if (!policy.require_finite_prices
                        || (reference_price.is_finite() && horizon_price.is_finite()))
                        && reference_price.abs() > f64::EPSILON =>
                {
                    let change = (horizon_price - reference_price) / reference_price;
                    let candidate_label =
                        self_growing_candidate_label_from_price_change(change, policy);
                    let status = if matches!(candidate_label, MemberExperienceOutcome::Unknown) {
                        StagedEvidencePriceEnrichmentStatus::NeedsMorePriceData
                    } else {
                        StagedEvidencePriceEnrichmentStatus::Enriched
                    };
                    StagedEvidencePriceEnrichment {
                        candidate_id: candidate.candidate_id.clone(),
                        replay_id: candidate.related_replay_id.clone(),
                        symbol: symbol.to_string(),
                        market_scope,
                        reference_price: Some(reference_price),
                        horizon_price: Some(horizon_price),
                        price_change_pct: Some(change),
                        candidate_label,
                        enrichment_status: status,
                        evidence_notes: vec![
                            format!("local price series enrichment over {resolved_bars} bars"),
                            format!("price_change_pct={change:.6}"),
                        ],
                        paper_only: true,
                    }
                }
                Some(_) => StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::InvalidPriceSeries,
                    evidence_notes: vec![
                        "local price series contains invalid price values".to_string(),
                    ],
                    paper_only: true,
                },
                None => StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NeedsMorePriceData,
                    evidence_notes: vec![
                        "unable to compute deterministic local price move".to_string(),
                    ],
                    paper_only: true,
                },
            }
        })
        .collect();
    StagedEvidencePriceEnrichmentResult {
        enriched_count: enrichments
            .iter()
            .filter(|item| {
                matches!(
                    item.enrichment_status,
                    StagedEvidencePriceEnrichmentStatus::Enriched
                )
            })
            .count(),
        needs_more_price_data_count: enrichments
            .iter()
            .filter(|item| {
                matches!(
                    item.enrichment_status,
                    StagedEvidencePriceEnrichmentStatus::NeedsMorePriceData
                        | StagedEvidencePriceEnrichmentStatus::NotApplicable
                )
            })
            .count(),
        rejected_count: enrichments
            .iter()
            .filter(|item| {
                matches!(
                    item.enrichment_status,
                    StagedEvidencePriceEnrichmentStatus::SymbolScopeMismatch
                        | StagedEvidencePriceEnrichmentStatus::InvalidPriceSeries
                )
            })
            .count(),
        enrichments,
        paper_only: true,
    }
}

pub fn build_self_growing_candidate_enrichment_patch(
    store: &SelfGrowingEvidenceStagingStore,
    link_resolution_result: StagedEvidenceLinkResolutionResult,
    price_enrichment_result: StagedEvidencePriceEnrichmentResult,
) -> SelfGrowingCandidateEnrichmentPatch {
    let original_by_candidate: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        store
            .candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    let link_applied_candidates =
        apply_link_resolutions_to_candidates(&store.candidates, &link_resolution_result);
    let enrichment_by_candidate: std::collections::BTreeMap<&str, &StagedEvidencePriceEnrichment> =
        price_enrichment_result
            .enrichments
            .iter()
            .map(|enrichment| (enrichment.candidate_id.as_str(), enrichment))
            .collect();
    let mut patched_candidates = Vec::new();
    let mut skipped_candidates = Vec::new();
    for candidate in link_applied_candidates {
        let mut updated = candidate.clone();
        let mut patched = original_by_candidate
            .get(candidate.candidate_id.as_str())
            .map(|original| {
                updated.related_replay_id != original.related_replay_id
                    || updated.related_decision_id != original.related_decision_id
                    || updated.related_experience_id != original.related_experience_id
            })
            .unwrap_or(false);
        if let Some(enrichment) = enrichment_by_candidate.get(candidate.candidate_id.as_str()) {
            if matches!(
                enrichment.enrichment_status,
                StagedEvidencePriceEnrichmentStatus::Enriched
            ) {
                updated.reference_price = enrichment.reference_price;
                updated.horizon_price = enrichment.horizon_price;
                updated.price_change_pct = enrichment.price_change_pct;
                updated.candidate_label = Some(enrichment.candidate_label);
                updated.label_source = SelfGrowingEvidenceLabelSource::SelfGrowingPriceEvidence;
                for note in &enrichment.evidence_notes {
                    push_unique_note(&mut updated.evidence_notes, note.clone());
                }
                patched = true;
            }
        }
        if patched {
            patched_candidates.push(updated);
        } else {
            skipped_candidates.push(candidate.candidate_id.clone());
            patched_candidates.push(candidate);
        }
    }
    SelfGrowingCandidateEnrichmentPatch {
        patch_id: format!("{}-enrichment-patch", store.store_id),
        link_resolutions: link_resolution_result,
        price_enrichments: price_enrichment_result,
        patched_candidates,
        skipped_candidates,
        paper_only: true,
    }
}

pub fn apply_self_growing_candidate_enrichment_patch(
    store: &SelfGrowingEvidenceStagingStore,
    patch: &SelfGrowingCandidateEnrichmentPatch,
) -> SelfGrowingEvidenceStagingStore {
    let patched_by_candidate: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        patch
            .patched_candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    normalize_self_growing_evidence_staging_store(SelfGrowingEvidenceStagingStore {
        store_id: store.store_id.clone(),
        candidates: store
            .candidates
            .iter()
            .map(|candidate| {
                patched_by_candidate
                    .get(candidate.candidate_id.as_str())
                    .copied()
                    .cloned()
                    .unwrap_or_else(|| candidate.clone())
            })
            .collect(),
        candidate_count: 0,
        pending_count: 0,
        approved_count: 0,
        rejected_count: 0,
        review_required_count: 0,
        paper_only: true,
    })
}

pub fn compute_promotion_safety_delta(
    candidates_after_patch: &[SelfGrowingEvidenceCandidate],
    before: &[SelfGrowingEvidencePromotionDecision],
    after: &[SelfGrowingEvidencePromotionDecision],
) -> PromotionSafetyDelta {
    let before_by_candidate: std::collections::BTreeMap<
        &str,
        &SelfGrowingEvidencePromotionDecision,
    > = before
        .iter()
        .map(|decision| (decision.candidate_id.as_str(), decision))
        .collect();
    let candidate_by_id: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        candidates_after_patch
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    let mut policy_violations = Vec::new();
    let mut unsafe_approval_count = 0;
    for decision in after {
        if !matches!(
            decision.decision,
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
        ) {
            continue;
        }
        let Some(candidate) = candidate_by_id.get(decision.candidate_id.as_str()).copied() else {
            continue;
        };
        let Some(previous) = before_by_candidate
            .get(decision.candidate_id.as_str())
            .copied()
        else {
            continue;
        };
        if matches!(
            previous.decision,
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
        ) {
            continue;
        }
        if !self_growing_candidate_is_safe_exact_price_evidence(candidate, &decision.score) {
            unsafe_approval_count += 1;
            policy_violations.push(format!(
                "candidate {} became auto-approved without safe exact price evidence",
                candidate.candidate_id
            ));
        }
    }
    let auto_approved_before = before
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
            )
        })
        .count();
    let auto_approved_after = after
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
            )
        })
        .count();
    let needs_review_before = before
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                    | SelfGrowingEvidencePromotionDecisionStatus::KeptStaged
            )
        })
        .count();
    let needs_review_after = after
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                    | SelfGrowingEvidencePromotionDecisionStatus::KeptStaged
            )
        })
        .count();
    let rejected_before = before
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::Rejected
            )
        })
        .count();
    let rejected_after = after
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::Rejected
            )
        })
        .count();
    let delta_status = if unsafe_approval_count > 0 {
        PromotionSafetyDeltaStatus::UnsafeRegression
    } else if auto_approved_after > auto_approved_before
        && needs_review_after <= needs_review_before
    {
        PromotionSafetyDeltaStatus::ImprovedSafely
    } else if auto_approved_after == auto_approved_before
        && needs_review_after == needs_review_before
        && rejected_after == rejected_before
    {
        PromotionSafetyDeltaStatus::NoChange
    } else {
        PromotionSafetyDeltaStatus::NeedsReview
    };
    PromotionSafetyDelta {
        auto_approved_before,
        auto_approved_after,
        needs_review_before,
        needs_review_after,
        rejected_before,
        rejected_after,
        unsafe_approval_count,
        policy_violations,
        delta_status,
        paper_only: true,
    }
}

fn run_enriched_evidence_promotion_with_inputs(
    config: &EnrichedEvidencePromotionRunConfig,
    staging_store: SelfGrowingEvidenceStagingStore,
    source_scores: &[SourceTrustScore],
    price_series_store: &PaperPriceSeriesStore,
    validated_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
) -> Result<EnrichedEvidencePromotionRunResult, String> {
    if !config.paper_only {
        return Err("enriched evidence promotion config must be paper-only".to_string());
    }
    let baseline_promotion = run_self_growing_evidence_promotion_with_inputs(
        &SelfGrowingEvidencePromotionRunConfig {
            run_id: format!("{}-baseline", config.run_id),
            staging_store_input_path: None,
            staging_store_output_path: None,
            research_evidence_bundle_path: None,
            source_trust_input_path: None,
            validated_dataset_input_path: None,
            sanitized_dataset_input_path: None,
            experience_store_input_path: None,
            approved_paper_evidence_output_path: None,
            validated_replay_output_path: None,
            training_candidate_dataset_output_path: None,
            dry_run: true,
            apply_promotions: false,
            refresh_training_candidates: false,
            paper_only: true,
        },
        staging_store.clone(),
        source_scores,
        Some(validated_dataset),
        Some(experience_store),
    )?;
    let review_analysis = analyze_staged_evidence_review_queue(
        &staging_store.candidates,
        &baseline_promotion.promotion_decisions,
    );
    let link_resolution_result = resolve_staged_evidence_links(
        &staging_store.candidates,
        validated_dataset,
        experience_store,
        &StagedEvidenceLinkResolutionPolicy::default(),
    );
    let candidates_with_links =
        apply_link_resolutions_to_candidates(&staging_store.candidates, &link_resolution_result);
    let price_enrichment_result = enrich_staged_evidence_with_local_price_series(
        &candidates_with_links,
        price_series_store,
        &StagedEvidencePriceEnrichmentPolicy::default(),
    );
    let patch = build_self_growing_candidate_enrichment_patch(
        &staging_store,
        link_resolution_result.clone(),
        price_enrichment_result.clone(),
    );
    let mut enrichment_patch_result = SelfGrowingCandidateEnrichmentPatchResult {
        patch: patch.clone(),
        patched_count: patch
            .patched_candidates
            .iter()
            .filter(|candidate| !patch.skipped_candidates.contains(&candidate.candidate_id))
            .count(),
        skipped_count: patch.skipped_candidates.len(),
        unsafe_skip_count: patch
            .link_resolutions
            .link_candidates
            .iter()
            .filter(|candidate| !candidate.link_safe)
            .count(),
        output_path: None,
        paper_only: true,
    };
    let enriched_store = apply_self_growing_candidate_enrichment_patch(&staging_store, &patch);
    let preview_enriched_promotion = run_self_growing_evidence_promotion_with_inputs(
        &SelfGrowingEvidencePromotionRunConfig {
            run_id: format!("{}-preview", config.run_id),
            staging_store_input_path: None,
            staging_store_output_path: None,
            research_evidence_bundle_path: None,
            source_trust_input_path: None,
            validated_dataset_input_path: None,
            sanitized_dataset_input_path: None,
            experience_store_input_path: None,
            approved_paper_evidence_output_path: None,
            validated_replay_output_path: None,
            training_candidate_dataset_output_path: None,
            dry_run: true,
            apply_promotions: false,
            refresh_training_candidates: false,
            paper_only: true,
        },
        enriched_store.clone(),
        source_scores,
        Some(validated_dataset),
        Some(experience_store),
    )?;
    let safety_delta = compute_promotion_safety_delta(
        &enriched_store.candidates,
        &baseline_promotion.promotion_decisions,
        &preview_enriched_promotion.promotion_decisions,
    );
    let safe_to_apply = !matches!(
        safety_delta.delta_status,
        PromotionSafetyDeltaStatus::UnsafeRegression
    );
    let final_enriched_promotion = if !config.dry_run && safe_to_apply {
        let promotion = run_self_growing_evidence_promotion_with_inputs(
            &SelfGrowingEvidencePromotionRunConfig {
                run_id: config.run_id.clone(),
                staging_store_input_path: None,
                staging_store_output_path: config
                    .apply_enrichment_patch
                    .then(|| config.enriched_staging_output_path.clone())
                    .flatten(),
                research_evidence_bundle_path: None,
                source_trust_input_path: None,
                validated_dataset_input_path: None,
                sanitized_dataset_input_path: None,
                experience_store_input_path: None,
                approved_paper_evidence_output_path: config
                    .apply_promotions
                    .then(|| config.approved_evidence_output_path.clone())
                    .flatten(),
                validated_replay_output_path: config.validated_replay_output_path.clone(),
                training_candidate_dataset_output_path: config
                    .training_candidate_output_path
                    .clone(),
                dry_run: false,
                apply_promotions: config.apply_promotions,
                refresh_training_candidates: config.refresh_training_candidates,
                paper_only: true,
            },
            enriched_store.clone(),
            source_scores,
            Some(validated_dataset),
            Some(experience_store),
        )?;
        if config.apply_enrichment_patch {
            if let Some(path) = &config.enriched_staging_output_path {
                enriched_store.save_to_local_json(Path::new(path))?;
                enrichment_patch_result.output_path = Some(path.clone());
            }
        }
        promotion
    } else {
        preview_enriched_promotion
    };
    Ok(EnrichedEvidencePromotionRunResult {
        review_analysis,
        link_resolution_result,
        price_enrichment_result,
        enrichment_patch_result,
        rescored_count: final_enriched_promotion.scored_count,
        auto_approved_count_before: baseline_promotion.auto_approved_count,
        auto_approved_count_after: final_enriched_promotion.auto_approved_count,
        needs_review_count_after: final_enriched_promotion.needs_review_count
            + final_enriched_promotion.kept_staged_count,
        rejected_count_after: final_enriched_promotion.rejected_count,
        generated_paper_evidence_records: final_enriched_promotion.generated_paper_evidence_records,
        validated_replay_build_result: final_enriched_promotion.validated_replay_build_result,
        training_candidate_refresh_result: final_enriched_promotion
            .training_candidate_dataset
            .as_ref()
            .map(|candidate_dataset| TrainingCandidateRefreshResult {
                previous_candidate_count: baseline_promotion
                    .training_candidate_dataset
                    .as_ref()
                    .map(|dataset| dataset.example_count)
                    .unwrap_or(0),
                new_candidate_count: candidate_dataset.example_count,
                added_candidate_count: candidate_dataset.example_count.saturating_sub(
                    baseline_promotion
                        .training_candidate_dataset
                        .as_ref()
                        .map(|dataset| dataset.example_count)
                        .unwrap_or(0),
                ),
                excluded_candidate_count: baseline_promotion
                    .training_candidate_dataset
                    .as_ref()
                    .map(|dataset| dataset.example_count)
                    .unwrap_or(0)
                    .saturating_sub(candidate_dataset.example_count),
                refresh_status: if config.refresh_training_candidates {
                    TrainingCandidateRefreshStatus::Refreshed
                } else {
                    TrainingCandidateRefreshStatus::NoChange
                },
                blockers: if safe_to_apply {
                    Vec::new()
                } else {
                    safety_delta.policy_violations.clone()
                },
                paper_only: true,
            }),
        design_gate: final_enriched_promotion.design_gate,
        safety_delta,
        safety_summary: safety_summary(),
        paper_only: true,
    })
}

pub fn run_enriched_evidence_promotion(
    config: EnrichedEvidencePromotionRunConfig,
) -> Result<EnrichedEvidencePromotionRunResult, String> {
    for (path, label) in [
        (
            config.staging_store_input_path.as_ref(),
            "enriched evidence staging store input path",
        ),
        (
            config.price_series_path.as_ref(),
            "enriched evidence local price series path",
        ),
        (
            config.sanitized_dataset_path.as_ref(),
            "enriched evidence sanitized dataset path",
        ),
        (
            config.experience_store_path.as_ref(),
            "enriched evidence experience store path",
        ),
        (
            config.enriched_staging_output_path.as_ref(),
            "enriched evidence staging output path",
        ),
        (
            config.approved_evidence_output_path.as_ref(),
            "enriched evidence approved evidence output path",
        ),
        (
            config.validated_replay_output_path.as_ref(),
            "enriched evidence validated replay output path",
        ),
        (
            config.training_candidate_output_path.as_ref(),
            "enriched evidence training candidate output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    let staging_store_path = config.staging_store_input_path.as_ref().ok_or_else(|| {
        "enriched evidence promotion requires staging_store_input_path".to_string()
    })?;
    let price_series_path = config
        .price_series_path
        .as_ref()
        .ok_or_else(|| "enriched evidence promotion requires price_series_path".to_string())?;
    let sanitized_dataset_path = config
        .sanitized_dataset_path
        .as_ref()
        .ok_or_else(|| "enriched evidence promotion requires sanitized_dataset_path".to_string())?;
    let experience_store_path = config
        .experience_store_path
        .as_ref()
        .ok_or_else(|| "enriched evidence promotion requires experience_store_path".to_string())?;
    let staging_store =
        SelfGrowingEvidenceStagingStore::load_from_local_json(Path::new(staging_store_path))?;
    let price_series_store = load_price_series_store_from_local_json(Path::new(price_series_path))?;
    let validated_dataset = ReplayDataset::load_from_local_json(Path::new(sanitized_dataset_path))?;
    let experience_store =
        MemberExperienceStore::load_from_local_json(Path::new(experience_store_path))?;
    run_enriched_evidence_promotion_with_inputs(
        &config,
        staging_store,
        &[],
        &price_series_store,
        &validated_dataset,
        &experience_store,
    )
}

fn auto_approval_exact_link_type(
    candidate: &SelfGrowingEvidenceCandidate,
) -> AutoApprovalSuccessExactLinkType {
    if candidate.related_replay_id.is_some() {
        AutoApprovalSuccessExactLinkType::ReplayId
    } else if candidate.related_experience_id.is_some() {
        AutoApprovalSuccessExactLinkType::ExperienceId
    } else if candidate.related_decision_id.is_some() {
        AutoApprovalSuccessExactLinkType::DecisionId
    } else {
        AutoApprovalSuccessExactLinkType::None
    }
}

pub fn check_auto_approval_success_path(
    candidate: &SelfGrowingEvidenceCandidate,
    score: &EvidenceCandidateScore,
    price_enrichment: Option<&StagedEvidencePriceEnrichment>,
    policy: &SelfGrowingEvidencePromotionPolicy,
) -> AutoApprovalSuccessPathCheck {
    let price_evidence_present = price_enrichment
        .map(|enrichment| {
            matches!(
                enrichment.enrichment_status,
                StagedEvidencePriceEnrichmentStatus::Enriched
            ) && enrichment.price_change_pct.is_some()
        })
        .unwrap_or_else(|| self_growing_candidate_has_price_evidence(candidate));
    let source_trust_ok = if policy.require_validated_source_trust {
        matches!(
            candidate.source_trust_status,
            SourceTrustStatus::Trusted | SourceTrustStatus::UsableWithWarnings
        ) && score.source_trust_score >= 0.5
    } else {
        !matches!(candidate.source_trust_status, SourceTrustStatus::Rejected)
    };
    let evidence_kind_ok = matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate
    );
    let label_ok = matches!(
        candidate.candidate_label,
        Some(MemberExperienceOutcome::PaperPositive)
            | Some(MemberExperienceOutcome::PaperNegative)
            | Some(MemberExperienceOutcome::PaperNeutral)
    );
    let replay_link_present = candidate.related_replay_id.is_some();
    let exact_link_type = auto_approval_exact_link_type(candidate);
    let safety_ok = candidate.paper_only
        && !self_growing_candidate_contains_unsafe_content(candidate)
        && !self_growing_candidate_is_news_only(candidate)
        && !self_growing_candidate_is_low_trust(candidate, score)
        && !self_growing_candidate_is_ambiguous(candidate);
    let promotion_allowed = matches!(
        evaluate_self_growing_evidence_promotion(candidate, score, policy).decision,
        SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
    );
    let mut failure_reasons = Vec::new();
    if !replay_link_present {
        failure_reasons.push("missing exact replay link".to_string());
    }
    if !price_evidence_present {
        failure_reasons.push("missing deterministic price evidence".to_string());
    }
    if !source_trust_ok {
        failure_reasons.push("source trust below promotion threshold".to_string());
    }
    if !evidence_kind_ok {
        failure_reasons.push("evidence_kind is not price evidence".to_string());
    }
    if !label_ok {
        failure_reasons.push("candidate label is not promotable".to_string());
    }
    if !safety_ok {
        failure_reasons.push("candidate violates promotion safety".to_string());
    }
    if !promotion_allowed {
        failure_reasons.push("promotion gate still blocks candidate".to_string());
    }
    AutoApprovalSuccessPathCheck {
        check_id: format!("success-path-{}", candidate.candidate_id),
        candidate_id: candidate.candidate_id.clone(),
        replay_link_present,
        exact_link_type,
        price_evidence_present,
        source_trust_ok,
        evidence_kind_ok,
        label_ok,
        safety_ok,
        promotion_allowed,
        failure_reasons,
        paper_only: true,
    }
}

fn build_auto_approval_success_path_checks(
    candidates: &[SelfGrowingEvidenceCandidate],
    source_scores: &[SourceTrustScore],
    price_enrichment_result: &StagedEvidencePriceEnrichmentResult,
) -> Vec<AutoApprovalSuccessPathCheck> {
    let enrichment_by_candidate: std::collections::BTreeMap<&str, &StagedEvidencePriceEnrichment> =
        price_enrichment_result
            .enrichments
            .iter()
            .map(|enrichment| (enrichment.candidate_id.as_str(), enrichment))
            .collect();
    let policy = SelfGrowingEvidencePromotionPolicy::default();
    candidates
        .iter()
        .map(|candidate| {
            let score = score_self_growing_evidence_candidate(candidate, source_scores);
            check_auto_approval_success_path(
                candidate,
                &score,
                enrichment_by_candidate
                    .get(candidate.candidate_id.as_str())
                    .copied(),
                &policy,
            )
        })
        .collect()
}

fn approved_evidence_record_is_safe(record: &PaperOutcomeEvidenceRecord) -> bool {
    if !record.paper_only || record.replay_id.is_none() {
        return false;
    }
    if record.decision_id.is_none() && record.experience_id.is_none() {
        return false;
    }
    if !matches!(
        record.candidate_label,
        MemberExperienceOutcome::PaperPositive
            | MemberExperienceOutcome::PaperNegative
            | MemberExperienceOutcome::PaperNeutral
    ) {
        return false;
    }
    serde_json::to_string(record)
        .map(|text| research_source_unsafe_reasons(&text).is_empty())
        .unwrap_or(false)
}

fn replay_input_features_unchanged(before: &ReplayDataset, after: &ReplayDataset) -> bool {
    let before_by_replay: std::collections::BTreeMap<&str, &ReplayInputFeatures> = before
        .examples
        .iter()
        .map(|example| (example.replay_id.as_str(), &example.input_features))
        .collect();
    after.examples.iter().all(|example| {
        before_by_replay
            .get(example.replay_id.as_str())
            .map(|features| **features == example.input_features)
            .unwrap_or(true)
    })
}

fn apply_approved_evidence_to_training_candidates_with_inputs(
    config: &ApprovedEvidenceApplyConfig,
    approved_evidence: &[PaperOutcomeEvidenceRecord],
    validated_dataset: &ReplayDataset,
) -> Result<
    (
        ApprovedEvidenceApplyResult,
        Option<ValidatedReplayDatasetBuildResult>,
        Option<ReplayTrainingInclusionMask>,
        Option<TrainingCandidateDataset>,
    ),
    String,
> {
    if !config.paper_only {
        return Err("approved evidence apply config must be paper-only".to_string());
    }
    let approved_evidence_count = approved_evidence.len();
    let safe_records: Vec<PaperOutcomeEvidenceRecord> = approved_evidence
        .iter()
        .filter(|record| approved_evidence_record_is_safe(record))
        .cloned()
        .collect();
    let rejected_evidence_count = approved_evidence_count.saturating_sub(safe_records.len());
    let previous_mask = build_replay_training_inclusion_mask(
        validated_dataset,
        &ReplayTrainingInclusionPolicy::default(),
    );
    let previous_candidate_dataset = build_training_candidate_dataset(
        validated_dataset,
        &previous_mask,
        &TrainingCandidateBuildConfig::default(),
    );
    let mut build_result = None;
    let mut inclusion_mask = None;
    let mut training_candidate_dataset = None;
    if (config.refresh_validated_replay || config.refresh_training_candidates)
        && !safe_records.is_empty()
    {
        let (new_build, new_mask, new_candidate_dataset, _) =
            rebuild_training_candidate_dataset_from_approved_evidence(
                validated_dataset,
                &safe_records,
                &TrainingCandidateRefreshPolicy::default(),
            );
        build_result = Some(new_build);
        inclusion_mask = Some(new_mask);
        training_candidate_dataset = Some(new_candidate_dataset);
    }
    let input_features_unchanged = build_result
        .as_ref()
        .map(|build| replay_input_features_unchanged(validated_dataset, &build.dataset))
        .unwrap_or(true);
    if matches!(config.apply_mode, ApprovedEvidenceApplyMode::Apply) && !input_features_unchanged {
        return Ok((
            ApprovedEvidenceApplyResult {
                approved_evidence_count,
                applied_evidence_count: 0,
                skipped_evidence_count: safe_records.len(),
                rejected_evidence_count,
                validated_replay_refreshed: false,
                training_candidates_refreshed: false,
                previous_training_candidate_count: Some(previous_candidate_dataset.example_count),
                new_training_candidate_count: training_candidate_dataset
                    .as_ref()
                    .map(|dataset| dataset.example_count),
                input_features_unchanged: false,
                apply_status: ApprovedEvidenceApplyStatus::Blocked,
                paper_only: true,
            },
            None,
            None,
            None,
        ));
    }
    if matches!(config.apply_mode, ApprovedEvidenceApplyMode::Apply) && safe_records.is_empty() {
        return Ok((
            ApprovedEvidenceApplyResult {
                approved_evidence_count,
                applied_evidence_count: 0,
                skipped_evidence_count: 0,
                rejected_evidence_count,
                validated_replay_refreshed: false,
                training_candidates_refreshed: false,
                previous_training_candidate_count: Some(previous_candidate_dataset.example_count),
                new_training_candidate_count: Some(previous_candidate_dataset.example_count),
                input_features_unchanged,
                apply_status: ApprovedEvidenceApplyStatus::Blocked,
                paper_only: true,
            },
            None,
            None,
            None,
        ));
    }
    if matches!(config.apply_mode, ApprovedEvidenceApplyMode::Apply) {
        if let Some(path) = &config.approved_evidence_output_path {
            write_safe_json(Path::new(path), &safe_records)?;
        }
        if let Some(build) = &build_result {
            if config.refresh_validated_replay {
                if let Some(path) = &config.validated_replay_output_path {
                    build.dataset.save_to_local_json(Path::new(path))?;
                }
            }
        }
        if let Some(candidate_dataset) = &training_candidate_dataset {
            if config.refresh_training_candidates {
                if let Some(path) = &config.training_candidate_output_path {
                    write_safe_json(Path::new(path), candidate_dataset)?;
                }
            }
        }
    }
    let apply_status = match config.apply_mode {
        ApprovedEvidenceApplyMode::DryRun => ApprovedEvidenceApplyStatus::DryRunPreview,
        ApprovedEvidenceApplyMode::Apply if rejected_evidence_count > 0 => {
            ApprovedEvidenceApplyStatus::AppliedWithWarnings
        }
        ApprovedEvidenceApplyMode::Apply => ApprovedEvidenceApplyStatus::Applied,
    };
    let applied_evidence_count = if matches!(config.apply_mode, ApprovedEvidenceApplyMode::Apply) {
        safe_records.len()
    } else {
        0
    };
    let skipped_evidence_count = if matches!(config.apply_mode, ApprovedEvidenceApplyMode::DryRun) {
        safe_records.len()
    } else {
        0
    };
    Ok((
        ApprovedEvidenceApplyResult {
            approved_evidence_count,
            applied_evidence_count,
            skipped_evidence_count,
            rejected_evidence_count,
            validated_replay_refreshed: matches!(
                config.apply_mode,
                ApprovedEvidenceApplyMode::Apply
            ) && config.refresh_validated_replay
                && build_result.is_some(),
            training_candidates_refreshed: matches!(
                config.apply_mode,
                ApprovedEvidenceApplyMode::Apply
            ) && config.refresh_training_candidates
                && training_candidate_dataset.is_some(),
            previous_training_candidate_count: Some(previous_candidate_dataset.example_count),
            new_training_candidate_count: training_candidate_dataset
                .as_ref()
                .map(|dataset| dataset.example_count)
                .or(Some(previous_candidate_dataset.example_count)),
            input_features_unchanged,
            apply_status,
            paper_only: true,
        },
        build_result,
        inclusion_mask,
        training_candidate_dataset,
    ))
}

pub fn apply_approved_evidence_to_training_candidates(
    config: ApprovedEvidenceApplyConfig,
    approved_evidence: &[PaperOutcomeEvidenceRecord],
    validated_dataset: &ReplayDataset,
) -> Result<ApprovedEvidenceApplyResult, String> {
    for (path, label) in [
        (
            config.approved_evidence_input_path.as_ref(),
            "approved evidence input path",
        ),
        (
            config.approved_evidence_output_path.as_ref(),
            "approved evidence output path",
        ),
        (
            config.validated_replay_input_path.as_ref(),
            "approved evidence validated replay input path",
        ),
        (
            config.validated_replay_output_path.as_ref(),
            "approved evidence validated replay output path",
        ),
        (
            config.training_candidate_output_path.as_ref(),
            "approved evidence training candidate output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    apply_approved_evidence_to_training_candidates_with_inputs(
        &config,
        approved_evidence,
        validated_dataset,
    )
    .map(|(result, _, _, _)| result)
}

pub fn compute_promotion_success_metrics(
    auto_approved_before: usize,
    auto_approved_after: usize,
    generated_paper_evidence_count: usize,
    apply_result: Option<&ApprovedEvidenceApplyResult>,
    review_analysis: &StagedEvidenceReviewAnalysis,
    safety_delta_status: PromotionSafetyDeltaStatus,
) -> PromotionSuccessMetrics {
    let previous_training_candidate_count = apply_result
        .and_then(|result| result.previous_training_candidate_count)
        .unwrap_or(0);
    let new_training_candidate_count = apply_result
        .and_then(|result| result.new_training_candidate_count)
        .unwrap_or(previous_training_candidate_count);
    PromotionSuccessMetrics {
        auto_approved_before,
        auto_approved_after,
        auto_approval_delta: auto_approved_after as isize - auto_approved_before as isize,
        generated_paper_evidence_count,
        validated_replay_promoted_count: apply_result
            .map(|result| result.applied_evidence_count)
            .unwrap_or(generated_paper_evidence_count),
        training_candidate_delta: new_training_candidate_count as isize
            - previous_training_candidate_count as isize,
        news_only_blocked_count: review_analysis.news_only_count,
        low_trust_blocked_count: review_analysis.low_trust_count,
        ambiguous_blocked_count: review_analysis.ambiguous_count,
        missing_link_blocked_count: review_analysis.missing_replay_link_count,
        safety_delta_status,
        paper_only: true,
    }
}

fn run_auto_approval_end_to_end_with_inputs(
    config: &AutoApprovalEndToEndRunConfig,
    success_staging_store: SelfGrowingEvidenceStagingStore,
    success_price_series_store: PaperPriceSeriesStore,
    validated_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
) -> Result<AutoApprovalEndToEndRunResult, String> {
    if !config.paper_only {
        return Err("auto-approval end-to-end config must be paper-only".to_string());
    }
    let enriched_promotion_result = run_enriched_evidence_promotion_with_inputs(
        &EnrichedEvidencePromotionRunConfig {
            run_id: format!("{}-enriched-preview", config.run_id),
            staging_store_input_path: None,
            price_series_path: None,
            sanitized_dataset_path: None,
            experience_store_path: None,
            enriched_staging_output_path: None,
            approved_evidence_output_path: None,
            validated_replay_output_path: None,
            training_candidate_output_path: None,
            dry_run: true,
            apply_enrichment_patch: false,
            apply_promotions: false,
            refresh_training_candidates: false,
            paper_only: true,
        },
        success_staging_store.clone(),
        &[],
        &success_price_series_store,
        validated_dataset,
        experience_store,
    )?;
    let success_path_checks = build_auto_approval_success_path_checks(
        &enriched_promotion_result
            .enrichment_patch_result
            .patch
            .patched_candidates,
        &[],
        &enriched_promotion_result.price_enrichment_result,
    );
    let (approved_evidence_apply_result, design_gate) = if config.apply_promotions
        || config.refresh_training_candidates
    {
        let apply_config = ApprovedEvidenceApplyConfig {
            run_id: format!("{}-approved-evidence-apply", config.run_id),
            approved_evidence_input_path: None,
            approved_evidence_output_path: config.approved_evidence_output_path.clone(),
            validated_replay_input_path: None,
            validated_replay_output_path: None,
            training_candidate_output_path: config.training_candidate_output_path.clone(),
            apply_mode: if config.dry_run {
                ApprovedEvidenceApplyMode::DryRun
            } else {
                ApprovedEvidenceApplyMode::Apply
            },
            refresh_validated_replay: true,
            refresh_training_candidates: config.refresh_training_candidates,
            paper_only: true,
        };
        let (apply_result, build_result, _, candidate_dataset) =
            apply_approved_evidence_to_training_candidates_with_inputs(
                &apply_config,
                &enriched_promotion_result.generated_paper_evidence_records,
                validated_dataset,
            )?;
        let design_gate = if config.refresh_training_candidates {
            if let (Some(build_result), Some(candidate_dataset)) =
                (build_result.as_ref(), candidate_dataset.as_ref())
            {
                let split_result = build_training_split(
                    candidate_dataset,
                    &TrainingSplitConfig {
                        train_ratio: 0.7,
                        validation_ratio: 0.15,
                        test_ratio: 0.15,
                        split_seed: format!("{}-success-training-split", config.run_id),
                        stratify_by: TrainingSplitStratifyBy::Member,
                        paper_only: true,
                    },
                );
                let replay_quality_eval = run_replay_quality_evaluation_with_label_ratio_threshold(
                    experience_store,
                    &build_result.dataset,
                    default_min_replay_examples_required(),
                    default_min_examples_per_member_required(),
                    default_min_validated_label_ratio_required(),
                );
                let dry_run_result = run_offline_trainer_data_loader_dry_run(
                    candidate_dataset,
                    &split_result,
                    &build_offline_trainer_dry_run_spec(candidate_dataset, &split_result),
                );
                Some(evaluate_offline_training_design_gate(
                    candidate_dataset,
                    &split_result,
                    &dry_run_result,
                    &replay_quality_eval,
                ))
            } else {
                None
            }
        } else {
            None
        };
        (Some(apply_result), design_gate)
    } else {
        (None, None)
    };
    let promotion_success_metrics = compute_promotion_success_metrics(
        enriched_promotion_result.auto_approved_count_before,
        enriched_promotion_result.auto_approved_count_after,
        enriched_promotion_result
            .generated_paper_evidence_records
            .len(),
        approved_evidence_apply_result.as_ref(),
        &enriched_promotion_result.review_analysis,
        enriched_promotion_result.safety_delta.delta_status,
    );
    Ok(AutoApprovalEndToEndRunResult {
        enriched_promotion_result,
        success_path_checks,
        approved_evidence_apply_result,
        promotion_success_metrics,
        design_gate,
        safety_summary: safety_summary(),
        paper_only: true,
    })
}

pub fn run_auto_approval_end_to_end(
    config: AutoApprovalEndToEndRunConfig,
) -> Result<AutoApprovalEndToEndRunResult, String> {
    if !config.paper_only {
        return Err("auto-approval end-to-end config must be paper-only".to_string());
    }
    for (path, label) in [
        (
            Some(&config.success_staging_path),
            "auto-approval success staging path",
        ),
        (
            Some(&config.success_price_series_path),
            "auto-approval success price series path",
        ),
        (
            config
                .sanitized_dataset_path
                .as_ref()
                .or(config.validated_dataset_path.as_ref()),
            "auto-approval dataset path",
        ),
        (
            config.experience_store_path.as_ref(),
            "auto-approval experience store path",
        ),
        (
            config.approved_evidence_output_path.as_ref(),
            "auto-approval approved evidence output path",
        ),
        (
            config.training_candidate_output_path.as_ref(),
            "auto-approval training candidate output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    let success_staging_store = SelfGrowingEvidenceStagingStore::load_from_local_json(Path::new(
        &config.success_staging_path,
    ))?;
    let success_price_series_store =
        load_price_series_store_from_local_json(Path::new(&config.success_price_series_path))?;
    let validated_dataset_path = config
        .validated_dataset_path
        .as_ref()
        .or(config.sanitized_dataset_path.as_ref())
        .ok_or_else(|| "auto-approval end-to-end requires dataset path".to_string())?;
    let validated_dataset = ReplayDataset::load_from_local_json(Path::new(validated_dataset_path))?;
    let experience_store = if let Some(path) = &config.experience_store_path {
        MemberExperienceStore::load_from_local_json(Path::new(path))?
    } else {
        MemberExperienceStore::new("auto-approval-empty-experience-store", Vec::new())
    };
    run_auto_approval_end_to_end_with_inputs(
        &config,
        success_staging_store,
        success_price_series_store,
        &validated_dataset,
        &experience_store,
    )
}

fn training_feature_text_is_safe(text: &str) -> bool {
    let normalized = text.to_ascii_lowercase();
    ![
        "paperpositive",
        "papernegative",
        "paperneutral",
        "papernotrade",
        "reviewrequired",
        "simulatedfixture",
        "chairman",
        "의장 결정",
        "risk governor",
        "riskveto",
        "broker",
        "account",
        "order",
    ]
    .iter()
    .any(|term| normalized.contains(term))
}

pub fn build_training_feature_row(
    candidate_example: &TrainingCandidateExample,
    schema: &TrainingFeatureSchema,
) -> Result<TrainingFeatureRow, String> {
    if !schema.paper_only || !candidate_example.paper_only {
        return Err("training feature row must remain paper-only".to_string());
    }
    let features = &candidate_example.sanitized_input_features;
    let fields = [
        features.market_data_summary.as_str(),
        features.news_summary.as_str(),
        features.owner_pre_decision_context.as_deref().unwrap_or(""),
        features
            .prior_member_memory_summary
            .as_deref()
            .unwrap_or(""),
        features.prior_style_blend_summary.as_deref().unwrap_or(""),
        features.prior_calibration_summary.as_deref().unwrap_or(""),
    ];
    if fields
        .iter()
        .any(|text| !training_feature_text_is_safe(text))
        || features
            .feature_safety_notes
            .iter()
            .any(|text| !training_feature_text_is_safe(text))
    {
        return Err("training feature row contains leaked target or forbidden term".to_string());
    }
    Ok(TrainingFeatureRow {
        replay_id: candidate_example.replay_id.clone(),
        member_id: candidate_example.member_id.clone(),
        symbol: candidate_example.symbol.clone(),
        market_scope: candidate_example.market_scope,
        market_features: vec![features.market_data_summary.clone()],
        news_features: vec![features.news_summary.clone()],
        owner_context_features: features
            .owner_pre_decision_context
            .clone()
            .map(|value| vec![value]),
        prior_memory_features: features
            .prior_member_memory_summary
            .clone()
            .map(|value| vec![value]),
        style_features: features
            .prior_style_blend_summary
            .clone()
            .map(|value| vec![value]),
        calibration_features: features
            .prior_calibration_summary
            .clone()
            .map(|value| vec![value]),
        feature_safety_notes: features.feature_safety_notes.clone(),
        paper_only: true,
    })
}

pub fn build_training_target_row(
    candidate_example: &TrainingCandidateExample,
    schema: &TrainingTargetSchema,
) -> Option<TrainingTargetRow> {
    if !schema.paper_only
        || !candidate_example.paper_only
        || matches!(
            candidate_example.label_source,
            ReplayLabelSource::ReviewRequired
                | ReplayLabelSource::SimulatedFixture
                | ReplayLabelSource::RejectedLabel
        )
        || !schema
            .min_label_confidence
            .contains(&candidate_example.label_confidence)
    {
        return None;
    }
    Some(TrainingTargetRow {
        replay_id: candidate_example.replay_id.clone(),
        member_id: candidate_example.member_id.clone(),
        stance_target: candidate_example.target_labels.stance_target,
        confidence_target: candidate_example
            .target_labels
            .confidence_calibration_target,
        risk_target: candidate_example.target_labels.risk_label.clone(),
        evidence_target: candidate_example.target_labels.evidence_label.clone(),
        uncertainty_target: Some(match candidate_example.label_confidence {
            ReplayLabelConfidence::High => 0.1,
            ReplayLabelConfidence::Medium => 0.3,
            ReplayLabelConfidence::Low => 0.6,
            ReplayLabelConfidence::ReviewRequired => 1.0,
        }),
        expected_return_target: None,
        outcome_label: candidate_example.target_labels.outcome_label,
        attribution_label: candidate_example.target_labels.attribution_label,
        label_source: candidate_example.label_source,
        label_confidence: candidate_example.label_confidence,
        sample_weight: candidate_example.sample_weight,
        paper_only: true,
    })
}

fn smartcore_v2_feature_dim(schema: &TrainingFeatureSchema) -> usize {
    schema.numeric_feature_count + schema.categorical_feature_count + schema.text_feature_count
}

fn default_smartcore_v2_batch_spec(
    batch_size: usize,
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
) -> SmartCoreV2BatchSpec {
    SmartCoreV2BatchSpec {
        spec_id: format!(
            "smartcore-v2-batch-spec-{}-{}",
            feature_schema.schema_version, target_schema.schema_version
        ),
        core_family: SmartCoreV2Family::Mamba3GatedDeltaNetSparseEvent,
        temporal_core: SmartCoreV2ComponentStatus::Mamba3Deferred,
        memory_core: SmartCoreV2ComponentStatus::GatedDeltaNetDeferred,
        event_attention_core: SmartCoreV2ComponentStatus::SparseEventAttentionDeferred,
        sequence_len: feature_schema.sequence_len_hint,
        feature_dim: smartcore_v2_feature_dim(feature_schema),
        target_heads: target_schema.target_heads.clone(),
        batch_size,
        paper_only: true,
    }
}

pub fn build_smartcore_v2_batch_spec(
    batch_size: usize,
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
) -> SmartCoreV2BatchSpec {
    default_smartcore_v2_batch_spec(batch_size, feature_schema, target_schema)
}

pub fn build_smartcore_v2_training_batch(
    examples: &[TrainingCandidateExample],
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
    spec: &SmartCoreV2BatchSpec,
) -> Result<SmartCoreV2TrainingBatch, String> {
    if examples.is_empty() {
        return Err("smartcore v2 training batch requires at least one example".to_string());
    }
    let member_id = &examples[0].member_id;
    if examples
        .iter()
        .any(|example| example.member_id != *member_id)
    {
        return Err("smartcore v2 training batch must stay per-member".to_string());
    }
    let mut ordered = examples.to_vec();
    ordered.sort_by(|left, right| left.training_example_id.cmp(&right.training_example_id));
    let mut feature_rows = Vec::new();
    let mut target_rows = Vec::new();
    for example in &ordered {
        feature_rows.push(build_training_feature_row(example, feature_schema)?);
        let Some(target_row) = build_training_target_row(example, target_schema) else {
            return Err(format!(
                "training target row unavailable for {}",
                example.training_example_id
            ));
        };
        target_rows.push(target_row);
    }
    Ok(SmartCoreV2TrainingBatch {
        batch_id: format!("{}-{}", spec.spec_id, member_id),
        member_id: member_id.clone(),
        split: TrainingBatchSplit::All,
        example_ids: ordered
            .iter()
            .map(|example| example.training_example_id.clone())
            .collect(),
        batch_size: ordered.len(),
        feature_rows,
        target_rows,
        feature_schema_id: feature_schema.schema_id.clone(),
        target_schema_id: target_schema.schema_id.clone(),
        spec_id: spec.spec_id.clone(),
        paper_only: true,
    })
}

fn training_example_ids_for_split(
    split: &TrainingSplitResult,
    split_kind: TrainingBatchSplit,
) -> std::collections::BTreeSet<&str> {
    match split_kind {
        TrainingBatchSplit::Train => split.train_ids.iter().map(String::as_str).collect(),
        TrainingBatchSplit::Validation => split.validation_ids.iter().map(String::as_str).collect(),
        TrainingBatchSplit::Test => split.test_ids.iter().map(String::as_str).collect(),
        TrainingBatchSplit::All => split
            .train_ids
            .iter()
            .chain(split.validation_ids.iter())
            .chain(split.test_ids.iter())
            .map(String::as_str)
            .collect(),
    }
}

pub fn build_training_batches(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
    batch_config: &TrainingBatchIteratorConfig,
) -> Result<TrainingBatchIteratorResult, String> {
    if !batch_config.paper_only || !dataset.paper_only {
        return Err("training batch iterator must remain paper-only".to_string());
    }
    if batch_config.shuffle {
        return Err("training batch iterator does not allow shuffle".to_string());
    }
    if batch_config.batch_size == 0 {
        return Err("training batch iterator batch_size must be positive".to_string());
    }
    let selected_ids = training_example_ids_for_split(split, batch_config.split);
    let mut selected_examples: Vec<&TrainingCandidateExample> = dataset
        .examples
        .iter()
        .filter(|example| selected_ids.contains(example.training_example_id.as_str()))
        .filter(|example| {
            batch_config
                .member_id
                .as_deref()
                .map(|member_id| example.member_id == member_id)
                .unwrap_or(true)
        })
        .collect();
    selected_examples.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then_with(|| left.training_example_id.cmp(&right.training_example_id))
    });
    let mut grouped: std::collections::BTreeMap<String, Vec<&TrainingCandidateExample>> =
        std::collections::BTreeMap::new();
    let mut skipped_reasons = Vec::new();
    for example in selected_examples {
        if build_training_target_row(example, target_schema).is_none() {
            skipped_reasons.push(format!(
                "{} excluded by target schema",
                example.training_example_id
            ));
            continue;
        }
        grouped
            .entry(example.member_id.clone())
            .or_default()
            .push(example);
    }
    let spec =
        default_smartcore_v2_batch_spec(batch_config.batch_size, feature_schema, target_schema);
    let mut batches = Vec::new();
    let mut example_count = 0;
    for (member_id, member_examples) in grouped {
        for chunk in member_examples.chunks(batch_config.batch_size) {
            if batch_config.drop_last && chunk.len() < batch_config.batch_size {
                skipped_reasons.push(format!(
                    "{member_id} trailing batch dropped by drop_last policy"
                ));
                continue;
            }
            let owned_examples: Vec<TrainingCandidateExample> =
                chunk.iter().map(|example| (*example).clone()).collect();
            example_count += owned_examples.len();
            let mut batch = build_smartcore_v2_training_batch(
                &owned_examples,
                feature_schema,
                target_schema,
                &spec,
            )?;
            batch.split = batch_config.split;
            batches.push(batch);
        }
    }
    Ok(TrainingBatchIteratorResult {
        batch_count: batches.len(),
        skipped_count: skipped_reasons.len(),
        batches,
        example_count,
        skipped_reasons,
        paper_only: true,
    })
}

fn loss_head_name(head: SmartCoreV2LossHead) -> &'static str {
    match head {
        SmartCoreV2LossHead::StanceLoss => "StanceLoss",
        SmartCoreV2LossHead::ConfidenceCalibrationLoss => "ConfidenceCalibrationLoss",
        SmartCoreV2LossHead::RiskLoss => "RiskLoss",
        SmartCoreV2LossHead::EvidenceNeedLoss => "EvidenceNeedLoss",
        SmartCoreV2LossHead::UncertaintyLoss => "UncertaintyLoss",
        SmartCoreV2LossHead::ExpectedReturnHintLoss => "ExpectedReturnHintLoss",
    }
}

pub fn validate_loss_contract_against_batch(
    batch: &SmartCoreV2TrainingBatch,
    loss_contract: &SmartCoreV2LossContract,
) -> LossContractValidationResult {
    let mut missing_targets = Vec::new();
    if loss_contract
        .enabled_heads
        .contains(&SmartCoreV2LossHead::UncertaintyLoss)
        && batch
            .target_rows
            .iter()
            .any(|row| row.uncertainty_target.is_none())
    {
        missing_targets.push("uncertainty_target".to_string());
    }
    if loss_contract
        .enabled_heads
        .contains(&SmartCoreV2LossHead::ExpectedReturnHintLoss)
        && batch
            .target_rows
            .iter()
            .any(|row| row.expected_return_target.is_none())
    {
        missing_targets.push("expected_return_target".to_string());
    }
    let disabled_heads: Vec<String> = [
        SmartCoreV2LossHead::StanceLoss,
        SmartCoreV2LossHead::ConfidenceCalibrationLoss,
        SmartCoreV2LossHead::RiskLoss,
        SmartCoreV2LossHead::EvidenceNeedLoss,
        SmartCoreV2LossHead::UncertaintyLoss,
        SmartCoreV2LossHead::ExpectedReturnHintLoss,
    ]
    .into_iter()
    .filter(|head| !loss_contract.enabled_heads.contains(head))
    .map(loss_head_name)
    .map(str::to_string)
    .collect();
    LossContractValidationResult {
        valid: missing_targets.is_empty() && loss_contract.paper_only && batch.paper_only,
        missing_targets,
        disabled_heads,
        warnings: vec!["loss contract remains contract-only; runtime deferred".to_string()],
        paper_only: true,
    }
}

pub fn validate_metric_contract_against_dataset(
    dataset: &TrainingCandidateDataset,
    metric_contract: &OfflineTrainingMetricContract,
) -> MetricContractValidationResult {
    let target_schema = TrainingTargetSchema::default();
    let required_targets_present = dataset.examples.iter().all(|example| {
        example.paper_only
            && example.target_labels.paper_only
            && build_training_target_row(example, &target_schema).is_some()
    });
    let mut warnings = Vec::new();
    if metric_contract
        .metrics
        .contains(&OfflineTrainingMetric::ExpectedReturnRankCorrelationDeferred)
    {
        warnings.push("expected return metric remains deferred without model outputs".to_string());
    }
    MetricContractValidationResult {
        valid: required_targets_present && metric_contract.paper_only,
        required_targets_present,
        warnings,
        paper_only: true,
    }
}

pub fn run_offline_trainer_dry_run_v2(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    config: &OfflineTrainerDryRunConfigV2,
) -> OfflineTrainerDryRunResultV2 {
    let feature_schema = TrainingFeatureSchema {
        schema_version: config.feature_schema_version.clone(),
        ..TrainingFeatureSchema::default()
    };
    let target_schema = TrainingTargetSchema {
        schema_version: config.target_schema_version.clone(),
        ..TrainingTargetSchema::default()
    };
    let train_batches = build_training_batches(
        dataset,
        split,
        &feature_schema,
        &target_schema,
        &TrainingBatchIteratorConfig {
            batch_size: config.batch_size,
            shuffle: false,
            split: TrainingBatchSplit::Train,
            member_id: None,
            drop_last: false,
            paper_only: true,
        },
    );
    let validation_batches = build_training_batches(
        dataset,
        split,
        &feature_schema,
        &target_schema,
        &TrainingBatchIteratorConfig {
            batch_size: config.batch_size,
            shuffle: false,
            split: TrainingBatchSplit::Validation,
            member_id: None,
            drop_last: false,
            paper_only: true,
        },
    );
    let test_batches = build_training_batches(
        dataset,
        split,
        &feature_schema,
        &target_schema,
        &TrainingBatchIteratorConfig {
            batch_size: config.batch_size,
            shuffle: false,
            split: TrainingBatchSplit::Test,
            member_id: None,
            drop_last: false,
            paper_only: true,
        },
    );
    let mut warnings = Vec::new();
    let mut member_batch_counts = std::collections::BTreeMap::new();
    let mut feature_schema_valid = true;
    let mut target_schema_valid = true;
    let mut batch_shapes_valid = true;
    let mut loss_contract_valid = true;
    let mut metric_contract_valid = true;
    let loss_contract = SmartCoreV2LossContract::default();
    let metric_contract = OfflineTrainingMetricContract::default();
    let train_batches = match train_batches {
        Ok(result) => result,
        Err(err) => {
            warnings.push(err);
            feature_schema_valid = false;
            target_schema_valid = false;
            batch_shapes_valid = false;
            TrainingBatchIteratorResult {
                batches: Vec::new(),
                batch_count: 0,
                example_count: 0,
                skipped_count: 0,
                skipped_reasons: Vec::new(),
                paper_only: true,
            }
        }
    };
    let validation_batches = validation_batches.unwrap_or_else(|err| {
        warnings.push(err);
        batch_shapes_valid = false;
        TrainingBatchIteratorResult {
            batches: Vec::new(),
            batch_count: 0,
            example_count: 0,
            skipped_count: 0,
            skipped_reasons: Vec::new(),
            paper_only: true,
        }
    });
    let test_batches = test_batches.unwrap_or_else(|err| {
        warnings.push(err);
        batch_shapes_valid = false;
        TrainingBatchIteratorResult {
            batches: Vec::new(),
            batch_count: 0,
            example_count: 0,
            skipped_count: 0,
            skipped_reasons: Vec::new(),
            paper_only: true,
        }
    });
    for batch in train_batches
        .batches
        .iter()
        .chain(validation_batches.batches.iter())
        .chain(test_batches.batches.iter())
    {
        *member_batch_counts
            .entry(batch.member_id.clone())
            .or_insert(0) += 1;
        batch_shapes_valid &= batch.feature_rows.len() == batch.target_rows.len()
            && batch.batch_size == batch.feature_rows.len()
            && batch.paper_only
            && batch.feature_rows.iter().all(|row| row.paper_only)
            && batch.target_rows.iter().all(|row| row.paper_only);
        if config.validate_loss_contract {
            let loss_validation = validate_loss_contract_against_batch(batch, &loss_contract);
            loss_contract_valid &= loss_validation.valid;
            warnings.extend(loss_validation.warnings);
        }
    }
    if config.validate_metric_contract {
        let metric_validation = validate_metric_contract_against_dataset(dataset, &metric_contract);
        metric_contract_valid = metric_validation.valid;
        warnings.extend(metric_validation.warnings);
    }
    feature_schema_valid &= dataset.examples.iter().all(|example| {
        build_training_feature_row(example, &feature_schema)
            .map(|row| row.paper_only)
            .unwrap_or(false)
    });
    target_schema_valid &= dataset
        .examples
        .iter()
        .filter(|example| split.train_ids.contains(&example.training_example_id))
        .all(|example| build_training_target_row(example, &target_schema).is_some());
    let dry_run_status = if !feature_schema_valid
        || !target_schema_valid
        || !batch_shapes_valid
        || !loss_contract_valid
        || !metric_contract_valid
        || train_batches.batch_count == 0
    {
        OfflineTrainerDryRunStatus::Failed
    } else if warnings.is_empty() {
        OfflineTrainerDryRunStatus::Passed
    } else {
        OfflineTrainerDryRunStatus::PassedWithWarnings
    };
    OfflineTrainerDryRunResultV2 {
        run_id: config.run_id.clone(),
        dataset_id: dataset.dataset_id.clone(),
        example_count: dataset.example_count,
        batch_size: config.batch_size,
        train_batch_count: train_batches.batch_count,
        validation_batch_count: validation_batches.batch_count,
        test_batch_count: test_batches.batch_count,
        member_batch_counts,
        feature_schema_valid,
        target_schema_valid,
        batch_shapes_valid,
        loss_contract_valid,
        metric_contract_valid,
        no_training_executed: true,
        no_weight_mutation: true,
        no_checkpoint_written: true,
        dry_run_status,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_offline_trainer_design_status(
    dry_run_result: &OfflineTrainerDryRunResultV2,
    design_gate: &OfflineTrainingDesignGate,
    label_quality_summary: &LabelQualitySummary,
) -> OfflineTrainerDesignStatus {
    let batch_contract_status = if dry_run_result.batch_shapes_valid {
        OfflineTrainerContractStatus::Ready
    } else {
        OfflineTrainerContractStatus::Blocked
    };
    let loss_contract_status = if dry_run_result.loss_contract_valid {
        OfflineTrainerContractStatus::ContractOnly
    } else {
        OfflineTrainerContractStatus::Blocked
    };
    let metric_contract_status = if dry_run_result.metric_contract_valid {
        OfflineTrainerContractStatus::ContractOnly
    } else {
        OfflineTrainerContractStatus::Blocked
    };
    let mut blockers = Vec::new();
    let mut warnings = dry_run_result.warnings.clone();
    if !dry_run_result.no_training_executed
        || !dry_run_result.no_weight_mutation
        || !dry_run_result.no_checkpoint_written
    {
        blockers.push(
            "offline trainer v2 must not train, mutate weights, or write checkpoints".to_string(),
        );
    }
    if matches!(
        design_gate.design_status,
        OfflineTrainingDesignGateStatus::BlockedBySafety
    ) {
        blockers.push("existing offline training design gate blocked by safety".to_string());
    }
    let design_status = if !blockers.is_empty() {
        OfflineTrainerDesignStatusLevel::BlockedBySafety
    } else if !dry_run_result.batch_shapes_valid {
        OfflineTrainerDesignStatusLevel::BlockedByShapeError
    } else if matches!(
        label_quality_summary.label_quality_status,
        LabelQualityStatus::Blocked
    ) {
        OfflineTrainerDesignStatusLevel::BlockedByLabelQuality
    } else if dry_run_result.train_batch_count == 0
        || matches!(
            design_gate.design_status,
            OfflineTrainingDesignGateStatus::NeedsMoreValidatedLabels
                | OfflineTrainingDesignGateStatus::NeedsMoreCoverage
        )
    {
        OfflineTrainerDesignStatusLevel::NeedsMoreData
    } else if matches!(
        dry_run_result.dry_run_status,
        OfflineTrainerDryRunStatus::Passed
    ) && matches!(
        design_gate.design_status,
        OfflineTrainingDesignGateStatus::ReadyForOfflineTrainerDryRun
            | OfflineTrainingDesignGateStatus::ReadyWithWarnings
    ) {
        if warnings.is_empty() {
            OfflineTrainerDesignStatusLevel::ReadyForTinyTrainingDryRun
        } else {
            OfflineTrainerDesignStatusLevel::ReadyWithWarnings
        }
    } else {
        OfflineTrainerDesignStatusLevel::ReadyWithWarnings
    };
    if matches!(
        design_status,
        OfflineTrainerDesignStatusLevel::NeedsMoreData
    ) {
        warnings
            .push("trainer skeleton is ready but more validated data is still needed".to_string());
    }
    OfflineTrainerDesignStatus {
        dataset_id: dry_run_result.dataset_id.clone(),
        dry_run_status: dry_run_result.dry_run_status,
        batch_contract_status,
        loss_contract_status,
        metric_contract_status,
        member_coverage_status: design_gate.member_coverage_status,
        label_quality_status: label_quality_summary.label_quality_status,
        design_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

impl Default for TinyTrainingEligibilityPolicy {
    fn default() -> Self {
        Self {
            min_training_examples_required: default_min_tiny_training_examples_required(),
            min_members_required: default_min_tiny_training_members_required(),
            allow_expected_deferred_warnings: true,
            allow_ready_with_warnings: true,
            require_no_blocking_warnings: true,
            require_no_leakage: true,
            require_no_broker_order_account: true,
            require_no_live_inference: true,
            paper_only: true,
        }
    }
}

fn canonical_pilot_member_ids() -> Vec<String> {
    vec![
        "TrendEntryAI".to_string(),
        "RiskGuardAI".to_string(),
        "EvidenceRegimeAI".to_string(),
    ]
}

fn training_target_head_name(head: TrainingTargetHead) -> &'static str {
    match head {
        TrainingTargetHead::Stance => "Stance",
        TrainingTargetHead::ConfidenceCalibration => "ConfidenceCalibration",
        TrainingTargetHead::Risk => "Risk",
        TrainingTargetHead::EvidenceNeed => "EvidenceNeed",
        TrainingTargetHead::Uncertainty => "Uncertainty",
        TrainingTargetHead::ExpectedReturnHint => "ExpectedReturnHint",
    }
}

fn offline_training_metric_name(metric: OfflineTrainingMetric) -> &'static str {
    match metric {
        OfflineTrainingMetric::StanceAccuracyDeferred => "StanceAccuracyDeferred",
        OfflineTrainingMetric::CalibrationErrorDeferred => "CalibrationErrorDeferred",
        OfflineTrainingMetric::RiskPrecisionDeferred => "RiskPrecisionDeferred",
        OfflineTrainingMetric::EvidenceRecallDeferred => "EvidenceRecallDeferred",
        OfflineTrainingMetric::ExpectedReturnRankCorrelationDeferred => {
            "ExpectedReturnRankCorrelationDeferred"
        }
    }
}

fn trainer_warning_message_slug(message: &str) -> String {
    let mut slug = String::new();
    let mut last_was_dash = false;
    for ch in message.chars().flat_map(|ch| ch.to_lowercase()) {
        if ch.is_ascii_alphanumeric() {
            slug.push(ch);
            last_was_dash = false;
        } else if !last_was_dash {
            slug.push('-');
            last_was_dash = true;
        }
        if slug.len() >= 48 {
            break;
        }
    }
    slug.trim_matches('-').to_string()
}

fn trainer_warning_split_from_message(message: &str) -> Option<TrainingBatchSplit> {
    let normalized = message.to_ascii_lowercase();
    if normalized.contains("validation") {
        Some(TrainingBatchSplit::Validation)
    } else if normalized.contains("test") {
        Some(TrainingBatchSplit::Test)
    } else if normalized.contains("train") {
        Some(TrainingBatchSplit::Train)
    } else if normalized.contains(" all ") || normalized.ends_with(" all") {
        Some(TrainingBatchSplit::All)
    } else {
        None
    }
}

fn trainer_warning_member_from_message(message: &str) -> Option<String> {
    canonical_pilot_member_ids()
        .into_iter()
        .find(|member_id| message.contains(member_id))
}

fn classify_trainer_warning(message: &str) -> TrainerWarning {
    let normalized = message.to_ascii_lowercase();
    let (kind, severity, expected, blocker) = if normalized.contains("broker")
        || normalized.contains("account")
        || normalized.contains("order")
        || normalized.contains("leak")
        || normalized.contains("blocked by safety")
        || normalized.contains("live inference")
    {
        (
            TrainerWarningKind::SafetyBlockingWarning,
            TrainerWarningSeverity::Blocking,
            false,
            true,
        )
    } else if normalized.contains("missing target")
        || normalized.contains("uncertainty_target")
        || normalized.contains("expected_return_target")
    {
        (
            TrainerWarningKind::MissingTargetWarning,
            TrainerWarningSeverity::Blocking,
            false,
            true,
        )
    } else if normalized.contains("shape")
        || normalized.contains("target row unavailable")
        || normalized.contains("unknown training example ids")
        || normalized.contains("batch_size must be positive")
        || normalized.contains("does not allow shuffle")
    {
        (
            TrainerWarningKind::ShapeWarning,
            TrainerWarningSeverity::Blocking,
            false,
            true,
        )
    } else if normalized.contains("loss contract remains contract-only") {
        (
            TrainerWarningKind::LossContractOnlyExpected,
            TrainerWarningSeverity::Info,
            true,
            false,
        )
    } else if normalized.contains("expected return metric remains deferred") {
        (
            TrainerWarningKind::MetricContractOnlyExpected,
            TrainerWarningSeverity::Info,
            true,
            false,
        )
    } else if normalized.contains("sparse") && normalized.contains("deferred") {
        (
            TrainerWarningKind::SparseEventAttentionDeferredExpected,
            TrainerWarningSeverity::Info,
            true,
            false,
        )
    } else if normalized.contains("mamba3") && normalized.contains("deferred") {
        (
            TrainerWarningKind::Mamba3RuntimeDeferredExpected,
            TrainerWarningSeverity::Info,
            true,
            false,
        )
    } else if normalized.contains("gated deltanet") && normalized.contains("deferred") {
        (
            TrainerWarningKind::GatedDeltaNetRuntimeDeferredExpected,
            TrainerWarningSeverity::Info,
            true,
            false,
        )
    } else if normalized.contains("runtime deferred") || normalized.contains("contract-only") {
        (
            TrainerWarningKind::RuntimeDeferredExpected,
            TrainerWarningSeverity::Info,
            true,
            false,
        )
    } else if normalized.contains("dataset too small")
        || normalized.contains("validation split is empty")
        || normalized.contains("test split is empty")
    {
        (
            TrainerWarningKind::SmallDatasetWarning,
            TrainerWarningSeverity::Warning,
            false,
            false,
        )
    } else if normalized.contains("does not cover every member")
        || normalized.contains("thin member coverage")
        || normalized.contains("trailing batch dropped")
        || normalized.contains("no training candidate examples available")
        || normalized.contains("no train split examples")
        || normalized.contains("excluded by target schema")
    {
        (
            TrainerWarningKind::ThinMemberCoverageWarning,
            TrainerWarningSeverity::Warning,
            false,
            false,
        )
    } else if normalized.contains("weak label")
        || normalized.contains("review-required")
        || normalized.contains("label quality")
        || normalized.contains("validated data")
    {
        (
            TrainerWarningKind::LabelQualityWarning,
            TrainerWarningSeverity::Warning,
            false,
            false,
        )
    } else {
        (
            TrainerWarningKind::UnknownWarning,
            TrainerWarningSeverity::Warning,
            false,
            false,
        )
    };
    let member_id = trainer_warning_member_from_message(message);
    let split = trainer_warning_split_from_message(message);
    let kind_slug = format!("{kind:?}").to_ascii_lowercase();
    let member_slug = member_id
        .as_deref()
        .map(str::to_ascii_lowercase)
        .unwrap_or_else(|| "all".to_string());
    let split_slug = split
        .map(|value| format!("{value:?}").to_ascii_lowercase())
        .unwrap_or_else(|| "all".to_string());
    TrainerWarning {
        warning_id: format!(
            "trainer-warning-{kind_slug}-{member_slug}-{split_slug}-{}",
            trainer_warning_message_slug(message)
        ),
        kind,
        severity,
        member_id,
        split,
        message: message.to_string(),
        expected,
        blocker,
        paper_only: true,
    }
}

pub fn dedupe_trainer_warnings(warnings: &[TrainerWarning]) -> TrainerWarningNormalizationResult {
    let mut deduped = std::collections::BTreeMap::new();
    for warning in warnings {
        let key = format!(
            "{:?}|{:?}|{}|{}|{}|{}|{}",
            warning.kind,
            warning.severity,
            warning.member_id.as_deref().unwrap_or("all"),
            warning
                .split
                .map(|value| format!("{value:?}"))
                .unwrap_or_else(|| "All".to_string()),
            warning.message,
            warning.expected,
            warning.blocker
        );
        deduped.entry(key).or_insert_with(|| warning.clone());
    }
    let normalized_warnings: Vec<TrainerWarning> =
        deduped.into_iter().map(|(_, warning)| warning).collect();
    let info_count = normalized_warnings
        .iter()
        .filter(|warning| matches!(warning.severity, TrainerWarningSeverity::Info))
        .count();
    let blocking_count = normalized_warnings
        .iter()
        .filter(|warning| matches!(warning.severity, TrainerWarningSeverity::Blocking))
        .count();
    let warning_count = normalized_warnings
        .iter()
        .filter(|warning| matches!(warning.severity, TrainerWarningSeverity::Warning))
        .count();
    let expected_deferred_warning_count = normalized_warnings
        .iter()
        .filter(|warning| warning.expected)
        .count();
    let real_blocker_count = normalized_warnings
        .iter()
        .filter(|warning| warning.blocker && !warning.expected)
        .count();
    TrainerWarningNormalizationResult {
        original_warning_count: warnings.len(),
        normalized_warning_count: normalized_warnings.len(),
        duplicate_warning_count: warnings.len().saturating_sub(normalized_warnings.len()),
        info_count,
        warning_count,
        blocking_count,
        normalized_warnings,
        expected_deferred_warning_count,
        real_blocker_count,
        paper_only: true,
    }
}

pub fn normalize_trainer_warnings(raw_warnings: &[String]) -> TrainerWarningNormalizationResult {
    let warnings: Vec<TrainerWarning> = raw_warnings
        .iter()
        .map(|warning| classify_trainer_warning(warning))
        .collect();
    dedupe_trainer_warnings(&warnings)
}

fn split_membership_sets(
    split: &TrainingSplitResult,
) -> (
    std::collections::BTreeSet<&str>,
    std::collections::BTreeSet<&str>,
    std::collections::BTreeSet<&str>,
) {
    (
        split.train_ids.iter().map(String::as_str).collect(),
        split.validation_ids.iter().map(String::as_str).collect(),
        split.test_ids.iter().map(String::as_str).collect(),
    )
}

fn split_for_training_example_id(
    split: &TrainingSplitResult,
    training_example_id: &str,
) -> TrainingBatchSplit {
    let (train_ids, validation_ids, test_ids) = split_membership_sets(split);
    if train_ids.contains(training_example_id) {
        TrainingBatchSplit::Train
    } else if validation_ids.contains(training_example_id) {
        TrainingBatchSplit::Validation
    } else if test_ids.contains(training_example_id) {
        TrainingBatchSplit::Test
    } else {
        TrainingBatchSplit::All
    }
}

pub fn summarize_member_batch_readiness(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    batches: &[SmartCoreV2TrainingBatch],
) -> Vec<MemberBatchReadinessSummary> {
    let (train_ids, validation_ids, test_ids) = split_membership_sets(split);
    let mut member_ids = canonical_pilot_member_ids();
    let mut extra_member_ids: std::collections::BTreeSet<String> = dataset
        .examples
        .iter()
        .map(|example| display_name_for_member_id(&example.member_id).to_string())
        .collect();
    for member_id in &member_ids {
        extra_member_ids.remove(member_id);
    }
    member_ids.extend(extra_member_ids);
    let target_schema = TrainingTargetSchema::default();
    member_ids
        .into_iter()
        .map(|member_id| {
            let member_examples: Vec<&TrainingCandidateExample> = dataset
                .examples
                .iter()
                .filter(|example| display_name_for_member_id(&example.member_id) == member_id)
                .collect();
            let mut label_source_distribution = std::collections::BTreeMap::new();
            let mut confidence_distribution = std::collections::BTreeMap::new();
            let mut train_example_count = 0;
            let mut validation_example_count = 0;
            let mut test_example_count = 0;
            for example in &member_examples {
                *label_source_distribution
                    .entry(format!("{:?}", example.label_source))
                    .or_insert(0) += 1;
                *confidence_distribution
                    .entry(format!("{:?}", example.label_confidence))
                    .or_insert(0) += 1;
                if train_ids.contains(example.training_example_id.as_str()) {
                    train_example_count += 1;
                } else if validation_ids.contains(example.training_example_id.as_str()) {
                    validation_example_count += 1;
                } else if test_ids.contains(example.training_example_id.as_str()) {
                    test_example_count += 1;
                }
            }
            let mut train_batch_count = 0;
            let mut validation_batch_count = 0;
            let mut test_batch_count = 0;
            for batch in batches
                .iter()
                .filter(|batch| display_name_for_member_id(&batch.member_id) == member_id)
            {
                if let Some(example_id) = batch.example_ids.first() {
                    match split_for_training_example_id(split, example_id) {
                        TrainingBatchSplit::Train => train_batch_count += 1,
                        TrainingBatchSplit::Validation => validation_batch_count += 1,
                        TrainingBatchSplit::Test => test_batch_count += 1,
                        TrainingBatchSplit::All => {}
                    }
                }
            }
            let target_rows: Vec<TrainingTargetRow> = member_examples
                .iter()
                .filter_map(|example| build_training_target_row(example, &target_schema))
                .collect();
            let mut target_head_coverage = std::collections::BTreeMap::new();
            target_head_coverage.insert(
                training_target_head_name(TrainingTargetHead::Stance).to_string(),
                target_rows.len(),
            );
            target_head_coverage.insert(
                training_target_head_name(TrainingTargetHead::ConfidenceCalibration).to_string(),
                target_rows.len(),
            );
            target_head_coverage.insert(
                training_target_head_name(TrainingTargetHead::Risk).to_string(),
                target_rows.len(),
            );
            target_head_coverage.insert(
                training_target_head_name(TrainingTargetHead::EvidenceNeed).to_string(),
                target_rows.len(),
            );
            target_head_coverage.insert(
                training_target_head_name(TrainingTargetHead::Uncertainty).to_string(),
                target_rows
                    .iter()
                    .filter(|row| row.uncertainty_target.is_some())
                    .count(),
            );
            target_head_coverage.insert(
                training_target_head_name(TrainingTargetHead::ExpectedReturnHint).to_string(),
                target_rows
                    .iter()
                    .filter(|row| row.expected_return_target.is_some())
                    .count(),
            );
            let mut warnings = Vec::new();
            let contains_forbidden_labels = label_source_distribution
                .contains_key("ReviewRequired")
                || label_source_distribution.contains_key("SimulatedFixture")
                || label_source_distribution.contains_key("RejectedLabel");
            let batch_status = if contains_forbidden_labels {
                warnings.push(
                    "weak/review-required/simulated labels must stay excluded from trainer inputs"
                        .to_string(),
                );
                MemberBatchReadinessStatus::Blocked
            } else if member_examples.is_empty() {
                warnings.push("no training candidate examples available for member".to_string());
                MemberBatchReadinessStatus::InsufficientData
            } else if train_example_count == 0 {
                warnings.push("no train split examples available for member".to_string());
                MemberBatchReadinessStatus::InsufficientData
            } else {
                if member_examples.len() < 3 {
                    warnings.push("thin member coverage across dataset".to_string());
                }
                if validation_example_count == 0 {
                    warnings.push("validation split coverage is thin for member".to_string());
                }
                if test_example_count == 0 {
                    warnings.push("test split coverage is thin for member".to_string());
                }
                if train_batch_count == 0 {
                    warnings.push("no train batches available for member".to_string());
                }
                if warnings.is_empty() {
                    MemberBatchReadinessStatus::Ready
                } else {
                    MemberBatchReadinessStatus::ReadyWithWarnings
                }
            };
            MemberBatchReadinessSummary {
                member_id,
                train_example_count,
                validation_example_count,
                test_example_count,
                train_batch_count,
                validation_batch_count,
                test_batch_count,
                label_source_distribution,
                confidence_distribution,
                target_head_coverage,
                batch_status,
                warnings,
                paper_only: true,
            }
        })
        .collect()
}

fn aggregate_loss_contract_validation(
    batches: &[SmartCoreV2TrainingBatch],
) -> LossContractValidationResult {
    let loss_contract = SmartCoreV2LossContract::default();
    let mut missing_targets = std::collections::BTreeSet::new();
    let mut warnings = std::collections::BTreeSet::new();
    let mut valid = true;
    let mut disabled_heads = std::collections::BTreeSet::new();
    for batch in batches {
        let validation = validate_loss_contract_against_batch(batch, &loss_contract);
        valid &= validation.valid;
        missing_targets.extend(validation.missing_targets);
        warnings.extend(validation.warnings);
        disabled_heads.extend(validation.disabled_heads);
    }
    if batches.is_empty() {
        valid = false;
        warnings
            .insert("loss contract validation skipped because no batches were built".to_string());
    }
    LossContractValidationResult {
        valid,
        missing_targets: missing_targets.into_iter().collect(),
        disabled_heads: disabled_heads.into_iter().collect(),
        warnings: warnings.into_iter().collect(),
        paper_only: true,
    }
}

pub fn summarize_loss_metric_readiness(
    loss_validation: &LossContractValidationResult,
    metric_validation: &MetricContractValidationResult,
) -> LossMetricReadinessSummary {
    let loss_contract = SmartCoreV2LossContract::default();
    let metric_contract = OfflineTrainingMetricContract::default();
    let enabled_loss_heads = loss_contract
        .enabled_heads
        .iter()
        .map(|head| loss_head_name(*head).to_string())
        .collect::<Vec<_>>();
    let enabled_metric_heads = metric_contract
        .metrics
        .iter()
        .map(|metric| offline_training_metric_name(*metric).to_string())
        .collect::<Vec<_>>();
    let mut deferred_heads = std::collections::BTreeSet::new();
    if loss_validation
        .warnings
        .iter()
        .any(|warning| warning.contains("contract-only"))
    {
        deferred_heads.extend(enabled_loss_heads.iter().cloned());
    }
    if matches!(
        loss_contract.loss_status,
        SmartCoreV2LossStatus::ContractOnly
    ) {
        deferred_heads.extend(enabled_loss_heads.iter().cloned());
    }
    if matches!(
        metric_contract.metric_status,
        OfflineTrainingMetricStatus::ContractOnly
    ) {
        deferred_heads.extend(enabled_metric_heads.iter().cloned());
    }
    for warning in &metric_validation.warnings {
        if warning.contains("deferred") {
            deferred_heads.insert("ExpectedReturnRankCorrelationDeferred".to_string());
        }
    }
    let missing_metric_targets = if metric_validation.required_targets_present {
        Vec::new()
    } else {
        vec!["required metric targets unavailable".to_string()]
    };
    let mut blocking_issues = Vec::new();
    if !loss_validation.missing_targets.is_empty() {
        blocking_issues.push(format!(
            "loss targets missing: {}",
            loss_validation.missing_targets.join(", ")
        ));
    }
    if !missing_metric_targets.is_empty() {
        blocking_issues.push(format!(
            "metric targets missing: {}",
            missing_metric_targets.join(", ")
        ));
    }
    let loss_contract_status = if !loss_validation.missing_targets.is_empty() {
        LossMetricReadinessStatus::MissingTargets
    } else if matches!(
        loss_contract.loss_status,
        SmartCoreV2LossStatus::ContractOnly
    ) && loss_validation.valid
    {
        LossMetricReadinessStatus::ContractOnly
    } else if loss_validation.valid {
        LossMetricReadinessStatus::Ready
    } else {
        LossMetricReadinessStatus::Blocked
    };
    let metric_contract_status = if !missing_metric_targets.is_empty() {
        LossMetricReadinessStatus::MissingTargets
    } else if matches!(
        metric_contract.metric_status,
        OfflineTrainingMetricStatus::ContractOnly
    ) && metric_validation.valid
    {
        LossMetricReadinessStatus::ContractOnly
    } else if metric_validation.valid {
        LossMetricReadinessStatus::Ready
    } else {
        LossMetricReadinessStatus::Blocked
    };
    let mut warnings = loss_validation.warnings.clone();
    if matches!(
        metric_contract.metric_status,
        OfflineTrainingMetricStatus::ContractOnly
    ) && metric_validation.valid
    {
        warnings.push("metric contract remains contract-only; runtime deferred".to_string());
    }
    warnings.extend(metric_validation.warnings.clone());
    warnings.sort();
    warnings.dedup();
    LossMetricReadinessSummary {
        loss_contract_status,
        metric_contract_status,
        enabled_loss_heads,
        enabled_metric_heads,
        missing_loss_targets: loss_validation.missing_targets.clone(),
        missing_metric_targets,
        deferred_heads: deferred_heads.into_iter().collect(),
        blocking_issues,
        warnings,
        paper_only: true,
    }
}

pub fn build_offline_trainer_readiness_brief(
    dry_run_result: &OfflineTrainerDryRunResultV2,
    design_status: &OfflineTrainerDesignStatus,
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
) -> OfflineTrainerReadinessBrief {
    let feature_schema = TrainingFeatureSchema::default();
    let target_schema = TrainingTargetSchema::default();
    let build_batches_for_split = |split_kind| {
        build_training_batches(
            dataset,
            split,
            &feature_schema,
            &target_schema,
            &TrainingBatchIteratorConfig {
                batch_size: dry_run_result.batch_size,
                shuffle: false,
                split: split_kind,
                member_id: None,
                drop_last: false,
                paper_only: true,
            },
        )
        .unwrap_or(TrainingBatchIteratorResult {
            batches: Vec::new(),
            batch_count: 0,
            example_count: 0,
            skipped_count: 0,
            skipped_reasons: Vec::new(),
            paper_only: true,
        })
    };
    let train_batches = build_batches_for_split(TrainingBatchSplit::Train);
    let validation_batches = build_batches_for_split(TrainingBatchSplit::Validation);
    let test_batches = build_batches_for_split(TrainingBatchSplit::Test);
    let all_batches = train_batches
        .batches
        .iter()
        .chain(validation_batches.batches.iter())
        .chain(test_batches.batches.iter())
        .cloned()
        .collect::<Vec<_>>();
    let member_summaries = summarize_member_batch_readiness(dataset, split, &all_batches);
    let loss_validation = aggregate_loss_contract_validation(&all_batches);
    let metric_validation = validate_metric_contract_against_dataset(
        dataset,
        &OfflineTrainingMetricContract::default(),
    );
    let loss_metric_summary = summarize_loss_metric_readiness(&loss_validation, &metric_validation);
    let mut raw_warnings = dry_run_result.warnings.clone();
    raw_warnings.extend(design_status.warnings.clone());
    raw_warnings.extend(design_status.blockers.clone());
    for member_summary in &member_summaries {
        raw_warnings.extend(
            member_summary
                .warnings
                .iter()
                .map(|warning| format!("{}: {warning}", member_summary.member_id)),
        );
    }
    raw_warnings.extend(loss_metric_summary.warnings.clone());
    raw_warnings.extend(loss_metric_summary.blocking_issues.clone());
    let warning_summary = normalize_trainer_warnings(&raw_warnings);
    let constrained_members = member_summaries
        .iter()
        .filter(|summary| !matches!(summary.batch_status, MemberBatchReadinessStatus::Ready))
        .map(|summary| summary.member_id.clone())
        .collect::<Vec<_>>();
    let next_allowed_step = if warning_summary.real_blocker_count > 0
        || matches!(
            design_status.design_status,
            OfflineTrainerDesignStatusLevel::BlockedBySafety
                | OfflineTrainerDesignStatusLevel::BlockedByShapeError
                | OfflineTrainerDesignStatusLevel::BlockedByLabelQuality
        ) {
        OfflineTrainerReadinessNextStep::FixBlockingIssues
    } else if matches!(
        design_status.design_status,
        OfflineTrainerDesignStatusLevel::NeedsMoreData
    ) || member_summaries.iter().any(|summary| {
        matches!(
            summary.batch_status,
            MemberBatchReadinessStatus::InsufficientData
        )
    }) {
        OfflineTrainerReadinessNextStep::KeepCollectingData
    } else if warning_summary.normalized_warning_count == 0 {
        OfflineTrainerReadinessNextStep::TinyTrainingDryRunAllowed
    } else if warning_summary.real_blocker_count == 0 {
        OfflineTrainerReadinessNextStep::TinyTrainingDryRunAllowedWithWarnings
    } else {
        OfflineTrainerReadinessNextStep::TrainingStillDeferred
    };
    let constrained_member_summary = if constrained_members.is_empty() {
        "all pilot members have usable batch coverage".to_string()
    } else {
        format!("constrained members: {}", constrained_members.join(", "))
    };
    let human_readable_summary = format!(
        "{} training candidates; split train/validation/test={}/{}/{}; {}; warnings={} expected deferred, {} real blockers; next={:?}; no training executed, no weight mutation, no checkpoint written.",
        dataset.example_count,
        split.train_count,
        split.validation_count,
        split.test_count,
        constrained_member_summary,
        warning_summary.expected_deferred_warning_count,
        warning_summary.real_blocker_count,
        next_allowed_step
    );
    OfflineTrainerReadinessBrief {
        brief_id: format!("trainer-readiness-brief-{}", dataset.dataset_id),
        dataset_id: dataset.dataset_id.clone(),
        design_status: design_status.design_status,
        dry_run_status: dry_run_result.dry_run_status,
        example_count: dataset.example_count,
        train_batch_count: train_batches.batch_count,
        validation_batch_count: validation_batches.batch_count,
        test_batch_count: test_batches.batch_count,
        member_summaries,
        loss_metric_summary,
        warning_summary,
        next_allowed_step,
        human_readable_summary,
        paper_only: true,
        no_training_executed: dry_run_result.no_training_executed,
        no_weight_mutation: dry_run_result.no_weight_mutation,
        no_checkpoint_written: dry_run_result.no_checkpoint_written,
    }
}

pub fn evaluate_tiny_training_eligibility(
    brief: &OfflineTrainerReadinessBrief,
    policy: &TinyTrainingEligibilityPolicy,
) -> TinyTrainingEligibilityGate {
    let pilot_member_ids = canonical_pilot_member_ids();
    let actual_members_with_examples = brief
        .member_summaries
        .iter()
        .filter(|summary| {
            pilot_member_ids.contains(&summary.member_id)
                && (summary.train_example_count
                    + summary.validation_example_count
                    + summary.test_example_count
                    > 0)
        })
        .count();
    let weak_label_excluded = brief.member_summaries.iter().all(|summary| {
        !summary
            .label_source_distribution
            .contains_key("ReviewRequired")
            && !summary
                .label_source_distribution
                .contains_key("SimulatedFixture")
            && !summary
                .label_source_distribution
                .contains_key("RejectedLabel")
    });
    let no_leakage_detected = !matches!(
        brief.design_status,
        OfflineTrainerDesignStatusLevel::BlockedBySafety
    ) && !brief.warning_summary.normalized_warnings.iter().any(
        |warning| {
            matches!(warning.kind, TrainerWarningKind::SafetyBlockingWarning)
                && warning.message.to_ascii_lowercase().contains("leak")
        },
    );
    let no_broker_order_account =
        !brief
            .warning_summary
            .normalized_warnings
            .iter()
            .any(|warning| {
                let normalized = warning.message.to_ascii_lowercase();
                normalized.contains("broker")
                    || normalized.contains("order")
                    || normalized.contains("account")
            });
    let no_live_inference = !brief
        .warning_summary
        .normalized_warnings
        .iter()
        .any(|warning| {
            warning
                .message
                .to_ascii_lowercase()
                .contains("live inference")
        });
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if policy.require_no_leakage && !no_leakage_detected {
        blockers.push("tiny training gate requires no leakage".to_string());
    }
    if policy.require_no_broker_order_account && !no_broker_order_account {
        blockers.push("tiny training gate forbids broker/order/account content".to_string());
    }
    if policy.require_no_live_inference && !no_live_inference {
        blockers.push("tiny training gate forbids live inference paths".to_string());
    }
    if !brief.no_checkpoint_written {
        blockers
            .push("tiny training gate requires checkpoint writing to remain forbidden".to_string());
    }
    if !weak_label_excluded {
        blockers.push("tiny training gate requires weak labels to remain excluded".to_string());
    }
    if policy.require_no_blocking_warnings && brief.warning_summary.real_blocker_count > 0 {
        blockers.push("tiny training gate requires zero real blocking warnings".to_string());
    }
    if brief.example_count < policy.min_training_examples_required {
        warnings.push(format!(
            "training examples below threshold: {} < {}",
            brief.example_count, policy.min_training_examples_required
        ));
    }
    if actual_members_with_examples < policy.min_members_required {
        warnings.push(format!(
            "pilot members with examples below threshold: {} < {}",
            actual_members_with_examples, policy.min_members_required
        ));
    }
    if brief.warning_summary.expected_deferred_warning_count > 0 {
        warnings.push(format!(
            "{} expected deferred warnings remain",
            brief.warning_summary.expected_deferred_warning_count
        ));
    }
    let eligibility_status = if !blockers.is_empty() {
        if blockers.iter().any(|blocker| {
            blocker.contains("leakage")
                || blocker.contains("broker/order/account")
                || blocker.contains("live inference")
                || blocker.contains("weak labels")
        }) {
            TinyTrainingEligibilityStatus::BlockedBySafety
        } else {
            TinyTrainingEligibilityStatus::BlockedByWarnings
        }
    } else if matches!(
        brief.next_allowed_step,
        OfflineTrainerReadinessNextStep::KeepCollectingData
    ) || brief.example_count < policy.min_training_examples_required
        || actual_members_with_examples < policy.min_members_required
        || matches!(
            brief.design_status,
            OfflineTrainerDesignStatusLevel::NeedsMoreData
        )
    {
        TinyTrainingEligibilityStatus::NeedsMoreData
    } else if matches!(
        brief.next_allowed_step,
        OfflineTrainerReadinessNextStep::FixBlockingIssues
    ) {
        TinyTrainingEligibilityStatus::BlockedByWarnings
    } else if matches!(
        brief.next_allowed_step,
        OfflineTrainerReadinessNextStep::TrainingStillDeferred
    ) {
        TinyTrainingEligibilityStatus::TrainingDeferred
    } else if !matches!(
        brief.design_status,
        OfflineTrainerDesignStatusLevel::ReadyForTinyTrainingDryRun
            | OfflineTrainerDesignStatusLevel::ReadyWithWarnings
    ) {
        TinyTrainingEligibilityStatus::TrainingDeferred
    } else if brief.warning_summary.expected_deferred_warning_count > 0
        || matches!(
            brief.next_allowed_step,
            OfflineTrainerReadinessNextStep::TinyTrainingDryRunAllowedWithWarnings
        )
    {
        TinyTrainingEligibilityStatus::EligibleWithWarnings
    } else {
        TinyTrainingEligibilityStatus::Eligible
    };
    let eligible_for_tiny_training_dry_run = matches!(
        eligibility_status,
        TinyTrainingEligibilityStatus::Eligible
            | TinyTrainingEligibilityStatus::EligibleWithWarnings
    );
    TinyTrainingEligibilityGate {
        gate_id: format!("tiny-training-gate-{}", brief.dataset_id),
        trainer_design_status: brief.design_status,
        dry_run_status: brief.dry_run_status,
        blocking_warning_count: brief.warning_summary.real_blocker_count,
        expected_deferred_warning_count: brief.warning_summary.expected_deferred_warning_count,
        min_training_examples_required: policy.min_training_examples_required,
        actual_training_examples: brief.example_count,
        min_members_required: policy.min_members_required,
        actual_members_with_examples,
        weak_label_excluded,
        no_leakage_detected,
        no_broker_order_account,
        no_live_inference,
        no_checkpoint_written: brief.no_checkpoint_written,
        eligible_for_tiny_training_dry_run,
        eligibility_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_tiny_training_experiment_contract(
    gate: &TinyTrainingEligibilityGate,
) -> TinyTrainingExperimentContract {
    let allowed_next_step = if gate.eligible_for_tiny_training_dry_run {
        TinyTrainingAllowedNextStep::NoWeightUpdateLossSimulation
    } else {
        TinyTrainingAllowedNextStep::KeepDryRunOnly
    };
    TinyTrainingExperimentContract {
        contract_id: format!("tiny-training-contract-{}", gate.gate_id),
        allowed_next_step,
        allowed_operations: vec![
            TinyTrainingAllowedOperation::BuildBatches,
            TinyTrainingAllowedOperation::ComputeDummyLossFromLabels,
            TinyTrainingAllowedOperation::ValidateHeadShapes,
            TinyTrainingAllowedOperation::NoOptimizer,
            TinyTrainingAllowedOperation::NoBackprop,
            TinyTrainingAllowedOperation::NoCheckpoint,
        ],
        forbidden_operations: vec![
            TinyTrainingForbiddenOperation::OptimizerStep,
            TinyTrainingForbiddenOperation::GradientBackprop,
            TinyTrainingForbiddenOperation::WeightMutation,
            TinyTrainingForbiddenOperation::CheckpointWrite,
            TinyTrainingForbiddenOperation::LiveInference,
            TinyTrainingForbiddenOperation::BrokerOrderAccount,
        ],
        max_examples: if gate.eligible_for_tiny_training_dry_run {
            gate.actual_training_examples
        } else {
            0
        },
        max_batches: if gate.eligible_for_tiny_training_dry_run {
            gate.actual_members_with_examples
        } else {
            0
        },
        paper_only: true,
    }
}

impl TinyLossSimulationConfig {
    pub fn validate(&self) -> Result<(), String> {
        if self.batch_size == 0 {
            return Err("tiny loss simulation batch_size must be positive".to_string());
        }
        if self.enabled_heads.is_empty() {
            return Err("tiny loss simulation requires at least one enabled head".to_string());
        }
        if !self.include_train_split && !self.include_validation_split && !self.include_test_split {
            return Err("tiny loss simulation requires at least one enabled split".to_string());
        }
        if !self.require_validated_labels
            || !self.forbid_review_required_labels
            || !self.forbid_simulated_fixture_labels
        {
            return Err(
                "tiny loss simulation requires validated labels and forbids review/simulated labels"
                    .to_string(),
            );
        }
        if !self.no_weight_update || !self.no_optimizer || !self.no_backprop || !self.no_checkpoint
        {
            return Err(
                "tiny loss simulation forbids optimizer/backprop/checkpoint/weight update"
                    .to_string(),
            );
        }
        if !self.paper_only {
            return Err("tiny loss simulation must remain paper-only".to_string());
        }
        Ok(())
    }
}

impl DummyPredictionPolicy {
    pub fn validate(&self) -> Result<(), String> {
        if self.allow_target_echo {
            return Err("dummy prediction policy forbids target echo".to_string());
        }
        if !self.confidence_baseline_value.is_finite() {
            return Err("dummy prediction confidence baseline must be finite".to_string());
        }
        if !self.paper_only {
            return Err("dummy prediction policy must remain paper-only".to_string());
        }
        Ok(())
    }
}

impl TinyNoWeightTrainingDryRunConfig {
    pub fn validate(&self) -> Result<(), String> {
        if self.batch_size == 0 {
            return Err("tiny no-weight dry-run batch_size must be positive".to_string());
        }
        if self.enabled_heads.is_empty() {
            return Err("tiny no-weight dry-run requires at least one enabled head".to_string());
        }
        if !self.dry_run || !self.paper_only {
            return Err("tiny no-weight dry-run must remain dry-run and paper-only".to_string());
        }
        self.prediction_policy.validate()
    }
}

impl NoPersistenceTrainingSimulationConfig {
    pub fn validate(&self) -> Result<(), String> {
        if self.batch_size == 0 {
            return Err(
                "no-persistence training simulation batch_size must be positive".to_string(),
            );
        }
        if self.max_epochs == 0 {
            return Err(
                "no-persistence training simulation max_epochs must be positive".to_string(),
            );
        }
        if self.max_steps == 0 {
            return Err(
                "no-persistence training simulation max_steps must be positive".to_string(),
            );
        }
        if self.enabled_heads.is_empty() {
            return Err(
                "no-persistence training simulation requires at least one enabled head".to_string(),
            );
        }
        if self.allow_optimizer {
            return Err("no-persistence training simulation forbids optimizer".to_string());
        }
        if self.allow_backprop {
            return Err("no-persistence training simulation forbids backprop".to_string());
        }
        if self.allow_gradient {
            return Err(
                "no-persistence training simulation forbids gradient computation".to_string(),
            );
        }
        if self.allow_weight_mutation {
            return Err("no-persistence training simulation forbids weight mutation".to_string());
        }
        if self.allow_checkpoint_write {
            return Err("no-persistence training simulation forbids checkpoint write".to_string());
        }
        if self.allow_model_runtime {
            return Err("no-persistence training simulation forbids model runtime".to_string());
        }
        if self.allow_live_inference {
            return Err("no-persistence training simulation forbids live inference".to_string());
        }
        if !self.paper_only {
            return Err("no-persistence training simulation must remain paper-only".to_string());
        }
        Ok(())
    }
}

fn head_shape_spec(head: TrainingTargetHead) -> HeadShapeSpec {
    match head {
        TrainingTargetHead::Stance => HeadShapeSpec {
            head,
            output_kind: HeadShapeOutputKind::Class,
            expected_dim: 5,
            target_required: true,
            paper_only: true,
        },
        TrainingTargetHead::ConfidenceCalibration => HeadShapeSpec {
            head,
            output_kind: HeadShapeOutputKind::Bucket,
            expected_dim: 6,
            target_required: true,
            paper_only: true,
        },
        TrainingTargetHead::Risk => HeadShapeSpec {
            head,
            output_kind: HeadShapeOutputKind::Class,
            expected_dim: 3,
            target_required: true,
            paper_only: true,
        },
        TrainingTargetHead::EvidenceNeed => HeadShapeSpec {
            head,
            output_kind: HeadShapeOutputKind::Class,
            expected_dim: 3,
            target_required: true,
            paper_only: true,
        },
        TrainingTargetHead::Uncertainty => HeadShapeSpec {
            head,
            output_kind: HeadShapeOutputKind::OptionalScalar,
            expected_dim: 1,
            target_required: false,
            paper_only: true,
        },
        TrainingTargetHead::ExpectedReturnHint => HeadShapeSpec {
            head,
            output_kind: HeadShapeOutputKind::OptionalScalar,
            expected_dim: 1,
            target_required: false,
            paper_only: true,
        },
    }
}

pub fn validate_smartcore_v2_head_shapes(
    batch_spec: &SmartCoreV2BatchSpec,
    target_schema: &TrainingTargetSchema,
    enabled_heads: &[TrainingTargetHead],
) -> HeadShapeValidationResult {
    let mut validated_heads = Vec::new();
    let mut missing_heads = Vec::new();
    let mut invalid_heads = Vec::new();
    let mut warnings = Vec::new();
    for head in enabled_heads {
        let spec = head_shape_spec(*head);
        let head_name = training_target_head_name(*head).to_string();
        let present_in_spec = batch_spec.target_heads.contains(head);
        let present_in_schema = target_schema.target_heads.contains(head);
        if present_in_spec && present_in_schema {
            validated_heads.push(head_name);
        } else if spec.target_required {
            invalid_heads.push(head_name.clone());
            warnings.push(format!(
                "{head_name} missing from batch spec or target schema"
            ));
        } else {
            missing_heads.push(head_name.clone());
            warnings.push(format!(
                "{head_name} remains deferred because target is optional"
            ));
        }
    }
    let shape_status = if !invalid_heads.is_empty() {
        HeadShapeStatus::Invalid
    } else if !warnings.is_empty() {
        HeadShapeStatus::ValidWithWarnings
    } else {
        HeadShapeStatus::Valid
    };
    HeadShapeValidationResult {
        validated_heads,
        missing_heads,
        invalid_heads,
        shape_status,
        warnings,
        paper_only: true,
    }
}

fn member_learning_label_bucket(label: MemberLearningLabel) -> f64 {
    match label {
        MemberLearningLabel::Reinforce => 1.0,
        MemberLearningLabel::Penalize => -1.0,
        MemberLearningLabel::CalibrateDown => -0.5,
        MemberLearningLabel::CalibrateUp => 0.5,
        MemberLearningLabel::NeedMoreEvidence => 0.25,
        MemberLearningLabel::Keep => 0.0,
    }
}

fn dummy_prediction_for_head(
    row: &TrainingTargetRow,
    head: TrainingTargetHead,
    policy: &DummyPredictionPolicy,
) -> DummyHeadPrediction {
    match head {
        TrainingTargetHead::Stance => DummyHeadPrediction {
            replay_id: row.replay_id.clone(),
            member_id: row.member_id.clone(),
            head,
            predicted_class: Some(match policy.stance_baseline {
                DummyStanceBaseline::AlwaysHold => "Hold".to_string(),
                DummyStanceBaseline::AlwaysNoTrade => "NoTrade".to_string(),
                DummyStanceBaseline::FixedUnknown => "Unknown".to_string(),
            }),
            predicted_value: None,
            target_class: Some(format!("{:?}", row.stance_target)),
            target_value: None,
            shape_valid: true,
            paper_only: true,
        },
        TrainingTargetHead::ConfidenceCalibration => DummyHeadPrediction {
            replay_id: row.replay_id.clone(),
            member_id: row.member_id.clone(),
            head,
            predicted_class: None,
            predicted_value: Some(policy.confidence_baseline_value),
            target_class: None,
            target_value: Some(member_learning_label_bucket(row.confidence_target)),
            shape_valid: true,
            paper_only: true,
        },
        TrainingTargetHead::Risk => DummyHeadPrediction {
            replay_id: row.replay_id.clone(),
            member_id: row.member_id.clone(),
            head,
            predicted_class: Some(match policy.risk_baseline {
                DummyRiskBaseline::Neutral => "Neutral".to_string(),
                DummyRiskBaseline::Unknown => "Unknown".to_string(),
            }),
            predicted_value: None,
            target_class: Some(row.risk_target.clone()),
            target_value: None,
            shape_valid: true,
            paper_only: true,
        },
        TrainingTargetHead::EvidenceNeed => DummyHeadPrediction {
            replay_id: row.replay_id.clone(),
            member_id: row.member_id.clone(),
            head,
            predicted_class: Some(match policy.evidence_baseline {
                DummyEvidenceBaseline::NeedMoreEvidence => "NeedMoreEvidence".to_string(),
                DummyEvidenceBaseline::Unknown => "Unknown".to_string(),
            }),
            predicted_value: None,
            target_class: Some(row.evidence_target.clone()),
            target_value: None,
            shape_valid: true,
            paper_only: true,
        },
        TrainingTargetHead::Uncertainty => DummyHeadPrediction {
            replay_id: row.replay_id.clone(),
            member_id: row.member_id.clone(),
            head,
            predicted_class: None,
            predicted_value: Some(0.5),
            target_class: None,
            target_value: row.uncertainty_target,
            shape_valid: true,
            paper_only: true,
        },
        TrainingTargetHead::ExpectedReturnHint => DummyHeadPrediction {
            replay_id: row.replay_id.clone(),
            member_id: row.member_id.clone(),
            head,
            predicted_class: None,
            predicted_value: Some(0.0),
            target_class: None,
            target_value: row.expected_return_target,
            shape_valid: true,
            paper_only: true,
        },
    }
}

fn dummy_head_loss_for_batch(
    batch: &SmartCoreV2TrainingBatch,
    head: TrainingTargetHead,
    policy: &DummyPredictionPolicy,
) -> DummyHeadLoss {
    let predictions: Vec<DummyHeadPrediction> = batch
        .target_rows
        .iter()
        .map(|row| dummy_prediction_for_head(row, head, policy))
        .collect();
    let mut valid_target_count = 0usize;
    let mut missing_target_count = 0usize;
    let mut accumulated_loss = 0.0;
    let loss_kind = match head {
        TrainingTargetHead::Stance
        | TrainingTargetHead::Risk
        | TrainingTargetHead::EvidenceNeed => DummyLossKind::ClassificationMismatchRate,
        TrainingTargetHead::ConfidenceCalibration => DummyLossKind::CalibrationBucketError,
        TrainingTargetHead::Uncertainty | TrainingTargetHead::ExpectedReturnHint => {
            DummyLossKind::MeanAbsoluteBucketError
        }
    };
    for prediction in &predictions {
        match head {
            TrainingTargetHead::Stance
            | TrainingTargetHead::Risk
            | TrainingTargetHead::EvidenceNeed => {
                if let (Some(predicted_class), Some(target_class)) = (
                    prediction.predicted_class.as_ref(),
                    prediction.target_class.as_ref(),
                ) {
                    valid_target_count += 1;
                    if predicted_class != target_class {
                        accumulated_loss += 1.0;
                    }
                } else {
                    missing_target_count += 1;
                }
            }
            TrainingTargetHead::ConfidenceCalibration
            | TrainingTargetHead::Uncertainty
            | TrainingTargetHead::ExpectedReturnHint => {
                if let (Some(predicted_value), Some(target_value)) =
                    (prediction.predicted_value, prediction.target_value)
                {
                    valid_target_count += 1;
                    accumulated_loss += (predicted_value - target_value).abs();
                } else {
                    missing_target_count += 1;
                }
            }
        }
    }
    let optional_head = matches!(
        head,
        TrainingTargetHead::Uncertainty | TrainingTargetHead::ExpectedReturnHint
    );
    if valid_target_count == 0 && optional_head {
        return DummyHeadLoss {
            head,
            loss_kind: DummyLossKind::DeferredHeadSkipped,
            example_count: predictions.len(),
            valid_target_count,
            missing_target_count,
            dummy_loss_value: 0.0,
            skipped: true,
            skip_reason: Some(format!(
                "{} target remains deferred/optional",
                training_target_head_name(head)
            )),
            paper_only: true,
        };
    }
    let dummy_loss_value = if valid_target_count == 0 {
        1.0
    } else {
        accumulated_loss / valid_target_count as f64
    };
    DummyHeadLoss {
        head,
        loss_kind: if valid_target_count == 0 {
            DummyLossKind::MissingTargetPenalty
        } else {
            loss_kind
        },
        example_count: predictions.len(),
        valid_target_count,
        missing_target_count,
        dummy_loss_value,
        skipped: false,
        skip_reason: None,
        paper_only: true,
    }
}

pub fn prove_no_weight_update_path(
    config: &TinyLossSimulationConfig,
    simulation_result: &TinyLossSimulationResult,
) -> NoWeightUpdateGuardProof {
    let optimizer_present = !config.no_optimizer;
    let gradient_computation_present = !config.no_backprop;
    let backprop_present = !config.no_backprop;
    let weight_mutation_present = !config.no_weight_update;
    let checkpoint_write_present = !config.no_checkpoint;
    let model_runtime_present = false;
    let live_inference_present = false;
    let broker_order_account_present = false;
    let mut violations = Vec::new();
    if optimizer_present {
        violations.push("optimizer path present".to_string());
    }
    if gradient_computation_present {
        violations.push("gradient computation path present".to_string());
    }
    if backprop_present {
        violations.push("backprop path present".to_string());
    }
    if weight_mutation_present {
        violations.push("weight mutation path present".to_string());
    }
    if checkpoint_write_present {
        violations.push("checkpoint write path present".to_string());
    }
    if model_runtime_present {
        violations.push("runtime model path present".to_string());
    }
    if live_inference_present {
        violations.push("live inference path present".to_string());
    }
    if broker_order_account_present {
        violations.push("broker/order/account path present".to_string());
    }
    let proof_status = if !violations.is_empty() {
        NoWeightUpdateGuardProofStatus::Violated
    } else if !simulation_result.warnings.is_empty() {
        NoWeightUpdateGuardProofStatus::PreservedWithWarnings
    } else {
        NoWeightUpdateGuardProofStatus::Preserved
    };
    NoWeightUpdateGuardProof {
        optimizer_present,
        gradient_computation_present,
        backprop_present,
        weight_mutation_present,
        checkpoint_write_present,
        model_runtime_present,
        live_inference_present,
        broker_order_account_present,
        proof_status,
        violations,
        paper_only: true,
    }
}

fn tiny_loss_split_enabled(split: TrainingBatchSplit, config: &TinyLossSimulationConfig) -> bool {
    match split {
        TrainingBatchSplit::Train => config.include_train_split,
        TrainingBatchSplit::Validation => config.include_validation_split,
        TrainingBatchSplit::Test => config.include_test_split,
        TrainingBatchSplit::All => {
            config.include_train_split
                || config.include_validation_split
                || config.include_test_split
        }
    }
}

pub fn simulate_tiny_label_losses(
    batches: &[SmartCoreV2TrainingBatch],
    config: &TinyLossSimulationConfig,
    prediction_policy: &DummyPredictionPolicy,
) -> TinyLossSimulationResult {
    let mut config_warnings = Vec::new();
    if let Err(error) = config.validate() {
        config_warnings.push(error);
    }
    if let Err(error) = prediction_policy.validate() {
        config_warnings.push(error);
    }
    let feature_schema = TrainingFeatureSchema::default();
    let target_schema = TrainingTargetSchema {
        target_heads: config.enabled_heads.clone(),
        ..TrainingTargetSchema::default()
    };
    let batch_spec =
        build_smartcore_v2_batch_spec(config.batch_size, &feature_schema, &target_schema);
    let shape_validation =
        validate_smartcore_v2_head_shapes(&batch_spec, &target_schema, &config.enabled_heads);
    let mut batch_results = Vec::new();
    let mut split_counts = std::collections::BTreeMap::new();
    let mut member_counts = std::collections::BTreeMap::new();
    let mut warnings = shape_validation.warnings.clone();
    warnings.extend(config_warnings.clone());
    for batch in batches
        .iter()
        .filter(|batch| tiny_loss_split_enabled(batch.split, config))
    {
        let canonical_member_id = display_name_for_member_id(&batch.member_id).to_string();
        *split_counts
            .entry(format!("{:?}", batch.split))
            .or_insert(0usize) += batch.example_ids.len();
        *member_counts
            .entry(canonical_member_id.clone())
            .or_insert(0usize) += batch.example_ids.len();
        let head_losses: Vec<DummyHeadLoss> = config
            .enabled_heads
            .iter()
            .copied()
            .map(|head| dummy_head_loss_for_batch(batch, head, prediction_policy))
            .collect();
        let batch_loss = head_losses
            .iter()
            .filter(|loss| !loss.skipped)
            .map(|loss| loss.dummy_loss_value)
            .sum::<f64>();
        let target_valid = head_losses.iter().all(|loss| {
            loss.valid_target_count > 0
                || loss.skipped
                || matches!(loss.loss_kind, DummyLossKind::DeferredHeadSkipped)
        });
        if !target_valid {
            warnings.push(format!("{} has missing mandatory targets", batch.batch_id));
        }
        batch_results.push(TinyLossSimulationBatchResult {
            batch_id: batch.batch_id.clone(),
            member_id: canonical_member_id,
            split: batch.split,
            example_ids: batch.example_ids.clone(),
            head_losses,
            batch_loss,
            shape_valid: !matches!(shape_validation.shape_status, HeadShapeStatus::Invalid),
            target_valid,
            no_weight_update: config.no_weight_update,
            no_optimizer: config.no_optimizer,
            no_backprop: config.no_backprop,
            no_checkpoint: config.no_checkpoint,
            paper_only: true,
        });
    }
    let aggregate_example_count = batch_results
        .iter()
        .map(|batch| batch.example_ids.len())
        .sum();
    let mut aggregate_by_head: std::collections::BTreeMap<TrainingTargetHead, DummyHeadLoss> =
        std::collections::BTreeMap::new();
    for batch in &batch_results {
        for loss in &batch.head_losses {
            aggregate_by_head
                .entry(loss.head)
                .and_modify(|aggregate| {
                    aggregate.example_count += loss.example_count;
                    aggregate.valid_target_count += loss.valid_target_count;
                    aggregate.missing_target_count += loss.missing_target_count;
                    aggregate.dummy_loss_value += loss.dummy_loss_value;
                    aggregate.skipped &= loss.skipped;
                })
                .or_insert_with(|| loss.clone());
        }
    }
    let mut aggregate_head_losses = aggregate_by_head.into_values().collect::<Vec<_>>();
    for loss in &mut aggregate_head_losses {
        let divisor = batch_results
            .iter()
            .filter(|batch| {
                batch
                    .head_losses
                    .iter()
                    .any(|head_loss| head_loss.head == loss.head)
            })
            .count()
            .max(1) as f64;
        loss.dummy_loss_value /= divisor;
    }
    aggregate_head_losses.sort_by_key(|loss| loss.head);
    let aggregate_loss = if batch_results.is_empty() {
        0.0
    } else {
        batch_results
            .iter()
            .map(|batch| batch.batch_loss)
            .sum::<f64>()
            / batch_results.len() as f64
    };
    let mut provisional = TinyLossSimulationResult {
        simulation_id: config.simulation_id.clone(),
        dataset_id: batches
            .first()
            .map(|batch| batch.spec_id.clone())
            .unwrap_or_else(|| "tiny-loss-simulation".to_string()),
        batch_count: batch_results.len(),
        example_count: aggregate_example_count,
        split_counts,
        member_counts,
        batch_results,
        aggregate_head_losses,
        aggregate_loss,
        shape_validation,
        guard_proof: NoWeightUpdateGuardProof {
            optimizer_present: false,
            gradient_computation_present: false,
            backprop_present: false,
            weight_mutation_present: false,
            checkpoint_write_present: false,
            model_runtime_present: false,
            live_inference_present: false,
            broker_order_account_present: false,
            proof_status: NoWeightUpdateGuardProofStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        simulation_status: OfflineTrainerDryRunStatus::Passed,
        warnings,
        paper_only: true,
    };
    let guard_proof = prove_no_weight_update_path(config, &provisional);
    provisional.simulation_status = if !config_warnings.is_empty()
        || !guard_proof.violations.is_empty()
        || matches!(
            provisional.shape_validation.shape_status,
            HeadShapeStatus::Invalid
        )
        || provisional
            .batch_results
            .iter()
            .any(|batch| !batch.target_valid)
    {
        OfflineTrainerDryRunStatus::Failed
    } else if provisional.warnings.is_empty() {
        OfflineTrainerDryRunStatus::Passed
    } else {
        OfflineTrainerDryRunStatus::PassedWithWarnings
    };
    provisional.guard_proof = guard_proof;
    provisional
}

pub fn summarize_tiny_loss_by_member(
    simulation_result: &TinyLossSimulationResult,
) -> Vec<MemberTinyLossSummary> {
    let mut member_ids = canonical_pilot_member_ids();
    let mut extra_members: std::collections::BTreeSet<String> = simulation_result
        .batch_results
        .iter()
        .map(|batch| display_name_for_member_id(&batch.member_id).to_string())
        .collect();
    for member_id in &member_ids {
        extra_members.remove(member_id);
    }
    member_ids.extend(extra_members);
    member_ids
        .into_iter()
        .map(|member_id| {
            let member_batches: Vec<&TinyLossSimulationBatchResult> = simulation_result
                .batch_results
                .iter()
                .filter(|batch| display_name_for_member_id(&batch.member_id) == member_id)
                .collect();
            let example_count = member_batches
                .iter()
                .map(|batch| batch.example_ids.len())
                .sum();
            let batch_count = member_batches.len();
            let aggregate_loss = if batch_count == 0 {
                0.0
            } else {
                member_batches
                    .iter()
                    .map(|batch| batch.batch_loss)
                    .sum::<f64>()
                    / batch_count as f64
            };
            let mut head_loss_summary = std::collections::BTreeMap::new();
            for batch in &member_batches {
                for loss in &batch.head_losses {
                    *head_loss_summary
                        .entry(training_target_head_name(loss.head).to_string())
                        .or_insert(0.0) += loss.dummy_loss_value;
                }
            }
            for value in head_loss_summary.values_mut() {
                *value /= batch_count.max(1) as f64;
            }
            let best_head = head_loss_summary
                .iter()
                .min_by(|left, right| left.1.total_cmp(right.1))
                .map(|(head, _)| head.clone());
            let worst_head = head_loss_summary
                .iter()
                .max_by(|left, right| left.1.total_cmp(right.1))
                .map(|(head, _)| head.clone());
            let mut warnings = Vec::new();
            let summary_status = if member_batches.is_empty() {
                warnings.push("no tiny loss simulation batches for member".to_string());
                MemberTinyLossSummaryStatus::InsufficientData
            } else if member_batches
                .iter()
                .any(|batch| !batch.shape_valid || !batch.target_valid)
            {
                warnings.push("shape or target validation failed for member".to_string());
                MemberTinyLossSummaryStatus::Failed
            } else if member_batches.len() == 1 {
                warnings.push("member has only one tiny loss batch".to_string());
                MemberTinyLossSummaryStatus::ReadyWithWarnings
            } else {
                MemberTinyLossSummaryStatus::Ready
            };
            MemberTinyLossSummary {
                member_id,
                example_count,
                batch_count,
                aggregate_loss,
                head_loss_summary,
                worst_head,
                best_head,
                summary_status,
                warnings,
                paper_only: true,
            }
        })
        .collect()
}

pub fn run_tiny_no_weight_training_dry_run(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    config: &TinyNoWeightTrainingDryRunConfig,
) -> TinyNoWeightTrainingDryRunResult {
    let mut validation_errors = Vec::new();
    if let Err(error) = config.validate() {
        validation_errors.push(error);
    }
    let tiny_loss_config = TinyLossSimulationConfig {
        simulation_id: config.run_id.clone(),
        batch_size: config.batch_size,
        enabled_heads: config.enabled_heads.clone(),
        ..TinyLossSimulationConfig::default()
    };
    if let Err(error) = tiny_loss_config.validate() {
        validation_errors.push(error);
    }
    let feature_schema = TrainingFeatureSchema::default();
    let target_schema = TrainingTargetSchema {
        target_heads: config.enabled_heads.clone(),
        ..TrainingTargetSchema::default()
    };
    let build_batches_for_split = |split_kind| {
        build_training_batches(
            dataset,
            split,
            &feature_schema,
            &target_schema,
            &TrainingBatchIteratorConfig {
                batch_size: config.batch_size,
                shuffle: false,
                split: split_kind,
                member_id: None,
                drop_last: false,
                paper_only: true,
            },
        )
        .unwrap_or(TrainingBatchIteratorResult {
            batches: Vec::new(),
            batch_count: 0,
            example_count: 0,
            skipped_count: 0,
            skipped_reasons: Vec::new(),
            paper_only: true,
        })
    };
    let mut batches = Vec::new();
    if tiny_loss_config.include_train_split {
        batches.extend(build_batches_for_split(TrainingBatchSplit::Train).batches);
    }
    if tiny_loss_config.include_validation_split {
        batches.extend(build_batches_for_split(TrainingBatchSplit::Validation).batches);
    }
    if tiny_loss_config.include_test_split {
        batches.extend(build_batches_for_split(TrainingBatchSplit::Test).batches);
    }
    let mut simulation_result =
        simulate_tiny_label_losses(&batches, &tiny_loss_config, &config.prediction_policy);
    if !validation_errors.is_empty() {
        simulation_result.warnings.extend(validation_errors);
        simulation_result.simulation_status = OfflineTrainerDryRunStatus::Failed;
    }
    let member_loss_summaries = summarize_tiny_loss_by_member(&simulation_result);
    let guard_proof = prove_no_weight_update_path(&tiny_loss_config, &simulation_result);
    let next_allowed_step = if simulation_result.example_count == 0 {
        TinyNoWeightTrainingNextStep::KeepCollectingData
    } else if matches!(
        simulation_result.simulation_status,
        OfflineTrainerDryRunStatus::Failed
    ) {
        TinyNoWeightTrainingNextStep::FixBlockingIssues
    } else if !guard_proof.violations.is_empty()
        || matches!(
            simulation_result.shape_validation.shape_status,
            HeadShapeStatus::Invalid
        )
        || simulation_result
            .aggregate_head_losses
            .iter()
            .any(|loss| loss.missing_target_count > 0 && !loss.skipped)
    {
        TinyNoWeightTrainingNextStep::FixBlockingIssues
    } else {
        TinyNoWeightTrainingNextStep::KeepNoWeightSimulationOnly
    };
    TinyNoWeightTrainingDryRunResult {
        run_id: config.run_id.clone(),
        trainer_readiness_brief: None,
        eligibility_gate: None,
        loss_simulation_result: simulation_result.clone(),
        member_loss_summaries,
        no_weight_update_guard_proof: guard_proof,
        next_allowed_step,
        dry_run_status: simulation_result.simulation_status,
        paper_only: true,
    }
}

fn combined_member_loss_summary_status(
    member_summaries: &[MemberTinyLossSummary],
) -> MemberTinyLossSummaryStatus {
    if member_summaries
        .iter()
        .any(|summary| matches!(summary.summary_status, MemberTinyLossSummaryStatus::Failed))
    {
        MemberTinyLossSummaryStatus::Failed
    } else if member_summaries.iter().any(|summary| {
        matches!(
            summary.summary_status,
            MemberTinyLossSummaryStatus::InsufficientData
        )
    }) {
        MemberTinyLossSummaryStatus::InsufficientData
    } else if member_summaries.iter().any(|summary| {
        matches!(
            summary.summary_status,
            MemberTinyLossSummaryStatus::ReadyWithWarnings
        )
    }) {
        MemberTinyLossSummaryStatus::ReadyWithWarnings
    } else {
        MemberTinyLossSummaryStatus::Ready
    }
}

pub fn evaluate_no_persistence_training_simulation_gate(
    tiny_dry_run_result: &TinyNoWeightTrainingDryRunResult,
) -> NoPersistenceTrainingSimulationGate {
    let min_examples_required = tiny_dry_run_result
        .eligibility_gate
        .as_ref()
        .map(|gate| gate.min_training_examples_required)
        .unwrap_or_else(default_min_tiny_training_examples_required);
    let actual_examples = tiny_dry_run_result.loss_simulation_result.example_count;
    let member_loss_summary_status =
        combined_member_loss_summary_status(&tiny_dry_run_result.member_loss_summaries);
    let mut blockers = Vec::new();
    let mut warnings = tiny_dry_run_result.loss_simulation_result.warnings.clone();
    let gate_status = if matches!(
        tiny_dry_run_result
            .no_weight_update_guard_proof
            .proof_status,
        NoWeightUpdateGuardProofStatus::Violated
    ) {
        blockers.extend(
            tiny_dry_run_result
                .no_weight_update_guard_proof
                .violations
                .clone(),
        );
        NoPersistenceTrainingSimulationGateStatus::BlockedBySafety
    } else if matches!(
        tiny_dry_run_result.dry_run_status,
        OfflineTrainerDryRunStatus::Failed
    ) {
        blockers.push("tiny no-weight dry-run failed".to_string());
        NoPersistenceTrainingSimulationGateStatus::BlockedBySafety
    } else if matches!(
        tiny_dry_run_result
            .loss_simulation_result
            .shape_validation
            .shape_status,
        HeadShapeStatus::Invalid
    ) {
        blockers.extend(
            tiny_dry_run_result
                .loss_simulation_result
                .shape_validation
                .invalid_heads
                .clone(),
        );
        NoPersistenceTrainingSimulationGateStatus::BlockedByShape
    } else if tiny_dry_run_result
        .loss_simulation_result
        .aggregate_head_losses
        .iter()
        .any(|loss| loss.missing_target_count > 0 && !loss.skipped)
    {
        blockers.push("mandatory targets remain missing".to_string());
        NoPersistenceTrainingSimulationGateStatus::BlockedByMissingTargets
    } else if matches!(
        member_loss_summary_status,
        MemberTinyLossSummaryStatus::Failed
    ) {
        blockers.push("member tiny loss summary failed".to_string());
        NoPersistenceTrainingSimulationGateStatus::BlockedByMissingTargets
    } else if actual_examples < min_examples_required
        || matches!(
            tiny_dry_run_result
                .eligibility_gate
                .as_ref()
                .map(|gate| gate.eligibility_status),
            Some(TinyTrainingEligibilityStatus::NeedsMoreData)
        )
        || matches!(
            member_loss_summary_status,
            MemberTinyLossSummaryStatus::InsufficientData
        )
    {
        warnings.push("additional examples are still required before next simulation".to_string());
        NoPersistenceTrainingSimulationGateStatus::NeedsMoreData
    } else if matches!(
        tiny_dry_run_result.dry_run_status,
        OfflineTrainerDryRunStatus::PassedWithWarnings
    ) || matches!(
        tiny_dry_run_result
            .eligibility_gate
            .as_ref()
            .map(|gate| gate.eligibility_status),
        Some(TinyTrainingEligibilityStatus::EligibleWithWarnings)
    ) || matches!(
        member_loss_summary_status,
        MemberTinyLossSummaryStatus::ReadyWithWarnings
    ) {
        NoPersistenceTrainingSimulationGateStatus::AllowedWithWarnings
    } else {
        NoPersistenceTrainingSimulationGateStatus::Allowed
    };
    let allow_next_no_persistence_simulation = matches!(
        gate_status,
        NoPersistenceTrainingSimulationGateStatus::Allowed
            | NoPersistenceTrainingSimulationGateStatus::AllowedWithWarnings
    );
    NoPersistenceTrainingSimulationGate {
        tiny_loss_simulation_status: tiny_dry_run_result.loss_simulation_result.simulation_status,
        no_weight_guard_status: tiny_dry_run_result
            .no_weight_update_guard_proof
            .proof_status,
        head_shape_status: tiny_dry_run_result
            .loss_simulation_result
            .shape_validation
            .shape_status,
        member_loss_summary_status,
        min_examples_required,
        actual_examples,
        allow_next_no_persistence_simulation,
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn is_validated_training_candidate_label(example: &TrainingCandidateExample) -> bool {
    matches!(
        example.label_source,
        ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
    ) && matches!(
        example.label_confidence,
        ReplayLabelConfidence::High | ReplayLabelConfidence::Medium
    )
}

fn is_weak_training_candidate_label(example: &TrainingCandidateExample) -> bool {
    !matches!(
        example.label_source,
        ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
    ) || matches!(
        example.label_confidence,
        ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired
    )
}

fn is_review_required_training_candidate_label(example: &TrainingCandidateExample) -> bool {
    matches!(
        example.label_source,
        ReplayLabelSource::ReviewRequired | ReplayLabelSource::AmbiguousLabel
    ) || matches!(
        example.label_confidence,
        ReplayLabelConfidence::ReviewRequired
    )
}

fn shadow_training_operations() -> Vec<ShadowTrainingOperation> {
    vec![
        ShadowTrainingOperation::LoadBatch,
        ShadowTrainingOperation::ValidateFeatureShape,
        ShadowTrainingOperation::ValidateTargetShape,
        ShadowTrainingOperation::ComputeDummyHeadLoss,
        ShadowTrainingOperation::AggregateDummyLoss,
        ShadowTrainingOperation::RecordStepMetrics,
        ShadowTrainingOperation::SkipOptimizerStep,
        ShadowTrainingOperation::SkipBackprop,
        ShadowTrainingOperation::SkipCheckpoint,
        ShadowTrainingOperation::SkipWeightMutation,
    ]
}

fn shadow_training_forbidden_operations() -> Vec<ShadowTrainingForbiddenOperation> {
    vec![
        ShadowTrainingForbiddenOperation::OptimizerStep,
        ShadowTrainingForbiddenOperation::Backpropagation,
        ShadowTrainingForbiddenOperation::GradientComputation,
        ShadowTrainingForbiddenOperation::WeightMutation,
        ShadowTrainingForbiddenOperation::CheckpointWrite,
        ShadowTrainingForbiddenOperation::RuntimeInference,
    ]
}

pub fn build_shadow_training_step_plan(
    config: &NoPersistenceTrainingSimulationConfig,
    batch_spec: &SmartCoreV2BatchSpec,
) -> ShadowTrainingStepPlan {
    let operations = shadow_training_operations();
    let forbidden_operations = shadow_training_forbidden_operations();
    let mut warnings = Vec::new();
    if let Err(error) = config.validate() {
        warnings.push(error);
    }
    if !batch_spec.paper_only {
        warnings.push("shadow training batch spec must remain paper-only".to_string());
    }
    if batch_spec.batch_size != config.batch_size {
        warnings.push("shadow training batch spec batch_size does not match config".to_string());
    }
    let required_skips = [
        ShadowTrainingOperation::SkipOptimizerStep,
        ShadowTrainingOperation::SkipBackprop,
        ShadowTrainingOperation::SkipCheckpoint,
        ShadowTrainingOperation::SkipWeightMutation,
    ];
    if required_skips
        .iter()
        .any(|required| !operations.contains(required))
    {
        warnings.push("shadow training plan is missing required skip operations".to_string());
    }
    let plan_valid = warnings.is_empty();
    ShadowTrainingStepPlan {
        plan_id: format!("{}-shadow-plan", config.simulation_id),
        operations,
        forbidden_operations,
        plan_valid,
        warnings,
        paper_only: true,
    }
}

fn build_no_persistence_step_record(
    epoch_index: usize,
    step_index: usize,
    batch_result: &TinyLossSimulationBatchResult,
    enabled_heads: &[TrainingTargetHead],
) -> NoPersistenceTrainingStepRecord {
    NoPersistenceTrainingStepRecord {
        step_id: format!(
            "{}-epoch-{epoch_index}-step-{step_index}",
            batch_result.batch_id
        ),
        epoch_index,
        step_index,
        batch_id: batch_result.batch_id.clone(),
        member_id: display_name_for_member_id(&batch_result.member_id).to_string(),
        split: batch_result.split,
        example_ids: batch_result.example_ids.clone(),
        example_count: batch_result.example_ids.len(),
        enabled_heads: enabled_heads.to_vec(),
        dummy_head_losses: batch_result.head_losses.clone(),
        aggregate_dummy_loss: batch_result.batch_loss,
        operations_executed: vec![
            ShadowTrainingOperation::LoadBatch,
            ShadowTrainingOperation::ValidateFeatureShape,
            ShadowTrainingOperation::ValidateTargetShape,
            ShadowTrainingOperation::ComputeDummyHeadLoss,
            ShadowTrainingOperation::AggregateDummyLoss,
            ShadowTrainingOperation::RecordStepMetrics,
        ],
        operations_skipped: vec![
            ShadowTrainingOperation::SkipOptimizerStep,
            ShadowTrainingOperation::SkipBackprop,
            ShadowTrainingOperation::SkipCheckpoint,
            ShadowTrainingOperation::SkipWeightMutation,
        ],
        optimizer_step_executed: false,
        backprop_executed: false,
        gradient_computed: false,
        weight_mutation_executed: false,
        checkpoint_written: false,
        model_runtime_used: false,
        live_inference_used: false,
        paper_only: true,
    }
}

pub fn aggregate_no_persistence_epoch_result(
    step_records: &[NoPersistenceTrainingStepRecord],
) -> NoPersistenceTrainingEpochResult {
    let epoch_index = step_records
        .first()
        .map(|step| step.epoch_index)
        .unwrap_or(0);
    let mut per_member_dummy_loss = std::collections::BTreeMap::new();
    let mut per_member_counts = std::collections::BTreeMap::new();
    let mut per_head_dummy_loss = std::collections::BTreeMap::new();
    let mut per_head_counts = std::collections::BTreeMap::new();
    for step in step_records {
        *per_member_dummy_loss
            .entry(step.member_id.clone())
            .or_insert(0.0) += step.aggregate_dummy_loss;
        *per_member_counts
            .entry(step.member_id.clone())
            .or_insert(0usize) += 1;
        for loss in &step.dummy_head_losses {
            let head_name = training_target_head_name(loss.head).to_string();
            *per_head_dummy_loss.entry(head_name.clone()).or_insert(0.0) += loss.dummy_loss_value;
            *per_head_counts.entry(head_name).or_insert(0usize) += 1;
        }
    }
    for (member_id, total_loss) in &mut per_member_dummy_loss {
        *total_loss /= per_member_counts
            .get(member_id)
            .copied()
            .unwrap_or(1)
            .max(1) as f64;
    }
    for (head_name, total_loss) in &mut per_head_dummy_loss {
        *total_loss /= per_head_counts.get(head_name).copied().unwrap_or(1).max(1) as f64;
    }
    let mut warnings = Vec::new();
    if step_records.is_empty() {
        warnings.push("no no-persistence training step records were produced".to_string());
    }
    NoPersistenceTrainingEpochResult {
        epoch_index,
        step_count: step_records.len(),
        train_step_count: step_records
            .iter()
            .filter(|step| matches!(step.split, TrainingBatchSplit::Train))
            .count(),
        validation_step_count: step_records
            .iter()
            .filter(|step| matches!(step.split, TrainingBatchSplit::Validation))
            .count(),
        test_step_count: step_records
            .iter()
            .filter(|step| matches!(step.split, TrainingBatchSplit::Test))
            .count(),
        aggregate_dummy_loss: if step_records.is_empty() {
            0.0
        } else {
            step_records
                .iter()
                .map(|step| step.aggregate_dummy_loss)
                .sum::<f64>()
                / step_records.len() as f64
        },
        per_member_dummy_loss,
        per_head_dummy_loss,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_training_simulation_safety(
    step_records: &[NoPersistenceTrainingStepRecord],
    dataset: &TrainingCandidateDataset,
    config: &NoPersistenceTrainingSimulationConfig,
) -> TrainingSimulationSafetyGuard {
    let optimizer_step_detected =
        config.allow_optimizer || step_records.iter().any(|step| step.optimizer_step_executed);
    let backprop_detected =
        config.allow_backprop || step_records.iter().any(|step| step.backprop_executed);
    let gradient_detected =
        config.allow_gradient || step_records.iter().any(|step| step.gradient_computed);
    let weight_mutation_detected = config.allow_weight_mutation
        || step_records
            .iter()
            .any(|step| step.weight_mutation_executed);
    let checkpoint_write_detected =
        config.allow_checkpoint_write || step_records.iter().any(|step| step.checkpoint_written);
    let model_runtime_detected =
        config.allow_model_runtime || step_records.iter().any(|step| step.model_runtime_used);
    let live_inference_detected =
        config.allow_live_inference || step_records.iter().any(|step| step.live_inference_used);
    let broker_order_account_detected = false;
    let training_candidate_ids: std::collections::BTreeSet<&str> = dataset
        .examples
        .iter()
        .map(|example| example.training_example_id.as_str())
        .collect();
    let non_training_candidate_example_detected = step_records.iter().any(|step| {
        step.example_ids
            .iter()
            .any(|example_id| !training_candidate_ids.contains(example_id.as_str()))
    });
    let weak_label_included_detected = dataset
        .examples
        .iter()
        .any(is_weak_training_candidate_label);
    let review_required_label_included_detected = dataset
        .examples
        .iter()
        .any(is_review_required_training_candidate_label);
    let mut violations = Vec::new();
    if optimizer_step_detected {
        violations.push("optimizer step detected in no-persistence simulation".to_string());
    }
    if backprop_detected {
        violations.push("backprop detected in no-persistence simulation".to_string());
    }
    if gradient_detected {
        violations.push("gradient computation detected in no-persistence simulation".to_string());
    }
    if weight_mutation_detected {
        violations.push("weight mutation detected in no-persistence simulation".to_string());
    }
    if checkpoint_write_detected {
        violations.push("checkpoint write detected in no-persistence simulation".to_string());
    }
    if model_runtime_detected {
        violations.push("model runtime detected in no-persistence simulation".to_string());
    }
    if live_inference_detected {
        violations.push("live inference detected in no-persistence simulation".to_string());
    }
    if broker_order_account_detected {
        violations
            .push("broker/order/account path detected in no-persistence simulation".to_string());
    }
    if non_training_candidate_example_detected {
        violations.push(
            "non-training-candidate example consumed in no-persistence simulation".to_string(),
        );
    }
    if weak_label_included_detected {
        violations.push("weak label included in no-persistence simulation dataset".to_string());
    }
    if review_required_label_included_detected {
        violations.push(
            "review-required label included in no-persistence simulation dataset".to_string(),
        );
    }
    let safety_status = if !violations.is_empty() {
        TrainingSimulationSafetyStatus::Violated
    } else if step_records.is_empty() {
        TrainingSimulationSafetyStatus::PreservedWithWarnings
    } else {
        TrainingSimulationSafetyStatus::Preserved
    };
    TrainingSimulationSafetyGuard {
        guard_id: format!("{}-safety-guard", config.simulation_id),
        optimizer_step_detected,
        backprop_detected,
        gradient_detected,
        weight_mutation_detected,
        checkpoint_write_detected,
        model_runtime_detected,
        live_inference_detected,
        broker_order_account_detected,
        non_training_candidate_example_detected,
        weak_label_included_detected,
        review_required_label_included_detected,
        safety_status,
        violations,
        paper_only: true,
    }
}

pub fn run_no_persistence_training_simulation(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    batches: &[SmartCoreV2TrainingBatch],
    config: &NoPersistenceTrainingSimulationConfig,
) -> NoPersistenceTrainingSimulationResult {
    let mut warnings = Vec::new();
    if let Err(error) = config.validate() {
        warnings.push(error);
    }
    if !dataset.paper_only || !split.paper_only || batches.iter().any(|batch| !batch.paper_only) {
        warnings
            .push("no-persistence training simulation inputs must remain paper-only".to_string());
    }
    if dataset
        .examples
        .iter()
        .any(|example| !is_validated_training_candidate_label(example))
    {
        warnings.push("training candidate dataset contains non-validated labels".to_string());
    }
    let feature_schema = TrainingFeatureSchema::default();
    let target_schema = TrainingTargetSchema {
        target_heads: config.enabled_heads.clone(),
        ..TrainingTargetSchema::default()
    };
    let batch_spec =
        build_smartcore_v2_batch_spec(config.batch_size, &feature_schema, &target_schema);
    let step_plan = build_shadow_training_step_plan(config, &batch_spec);
    warnings.extend(step_plan.warnings.clone());
    let selected_batches: Vec<SmartCoreV2TrainingBatch> =
        batches.iter().take(config.max_steps).cloned().collect();
    if batches.len() > selected_batches.len() {
        warnings.push(format!(
            "no-persistence training simulation capped steps to {}",
            config.max_steps
        ));
    }
    let tiny_loss_config = TinyLossSimulationConfig {
        simulation_id: config.simulation_id.clone(),
        batch_size: config.batch_size,
        enabled_heads: config.enabled_heads.clone(),
        ..TinyLossSimulationConfig::default()
    };
    let tiny_loss_simulation_result = simulate_tiny_label_losses(
        &selected_batches,
        &tiny_loss_config,
        &DummyPredictionPolicy::default(),
    );
    warnings.extend(tiny_loss_simulation_result.warnings.clone());
    let batch_results_by_id: std::collections::BTreeMap<_, _> = tiny_loss_simulation_result
        .batch_results
        .iter()
        .map(|batch_result| (batch_result.batch_id.clone(), batch_result))
        .collect();
    let mut step_records = Vec::new();
    for epoch_index in 0..config.max_epochs {
        for (step_index, batch) in selected_batches.iter().enumerate() {
            if let Some(batch_result) = batch_results_by_id.get(&batch.batch_id) {
                step_records.push(build_no_persistence_step_record(
                    epoch_index,
                    step_index,
                    batch_result,
                    &config.enabled_heads,
                ));
            }
        }
    }
    if step_records.is_empty() {
        warnings.push("no-persistence training simulation produced no step records".to_string());
    }
    let epoch_results: Vec<NoPersistenceTrainingEpochResult> = (0..config.max_epochs)
        .map(|epoch_index| {
            let epoch_steps: Vec<NoPersistenceTrainingStepRecord> = step_records
                .iter()
                .filter(|step| step.epoch_index == epoch_index)
                .cloned()
                .collect();
            aggregate_no_persistence_epoch_result(&epoch_steps)
        })
        .collect();
    let safety_guard = evaluate_training_simulation_safety(&step_records, dataset, config);
    let simulation_status = if !step_plan.plan_valid
        || matches!(
            tiny_loss_simulation_result.simulation_status,
            OfflineTrainerDryRunStatus::Failed
        )
        || matches!(
            safety_guard.safety_status,
            TrainingSimulationSafetyStatus::Violated
        ) {
        NoPersistenceTrainingSimulationStatus::Failed
    } else if !warnings.is_empty()
        || matches!(
            tiny_loss_simulation_result.simulation_status,
            OfflineTrainerDryRunStatus::PassedWithWarnings
        )
        || matches!(
            safety_guard.safety_status,
            TrainingSimulationSafetyStatus::PreservedWithWarnings
        )
    {
        NoPersistenceTrainingSimulationStatus::PassedWithWarnings
    } else {
        NoPersistenceTrainingSimulationStatus::Passed
    };
    warnings.sort();
    warnings.dedup();
    NoPersistenceTrainingSimulationResult {
        simulation_id: config.simulation_id.clone(),
        dataset_id: config
            .dataset_id
            .clone()
            .unwrap_or_else(|| dataset.dataset_id.clone()),
        config: config.clone(),
        step_plan,
        step_records,
        epoch_results,
        tiny_loss_simulation_result,
        safety_guard,
        no_training_executed: true,
        no_optimizer: !config.allow_optimizer,
        no_backprop: !config.allow_backprop,
        no_gradient: !config.allow_gradient,
        no_weight_mutation: !config.allow_weight_mutation,
        no_checkpoint: !config.allow_checkpoint_write,
        no_model_runtime: !config.allow_model_runtime,
        no_live_inference: !config.allow_live_inference,
        no_broker_order_account: true,
        simulation_status,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_smartcore_adapter_skeleton_readiness(
    simulation_result: &NoPersistenceTrainingSimulationResult,
    trainer_design_status: Option<&OfflineTrainerDesignStatus>,
) -> SmartCoreAdapterSkeletonReadinessGate {
    let mut blockers = simulation_result.safety_guard.violations.clone();
    let mut warnings = simulation_result.warnings.clone();
    let trainer_ready = trainer_design_status
        .map(|status| {
            matches!(
                status.design_status,
                OfflineTrainerDesignStatusLevel::ReadyForTinyTrainingDryRun
                    | OfflineTrainerDesignStatusLevel::ReadyWithWarnings
            )
        })
        .unwrap_or(true);
    if !trainer_ready {
        warnings.push("offline trainer design is not ready for adapter skeleton yet".to_string());
    }
    let dataset_status = if simulation_result.safety_guard.weak_label_included_detected
        || simulation_result
            .safety_guard
            .review_required_label_included_detected
    {
        TrainingSimulationDatasetStatus::BlockedByWeakLabels
    } else if matches!(
        simulation_result.safety_guard.safety_status,
        TrainingSimulationSafetyStatus::Violated
    ) {
        TrainingSimulationDatasetStatus::BlockedBySafety
    } else if simulation_result.step_records.is_empty() {
        TrainingSimulationDatasetStatus::NeedsMoreData
    } else {
        TrainingSimulationDatasetStatus::Ready
    };
    let batch_shape_status = simulation_result
        .tiny_loss_simulation_result
        .shape_validation
        .shape_status;
    let head_shape_status = simulation_result
        .tiny_loss_simulation_result
        .shape_validation
        .shape_status;
    let allow_adapter_skeleton_next = trainer_ready
        && !matches!(
            simulation_result.simulation_status,
            NoPersistenceTrainingSimulationStatus::Failed
        )
        && !matches!(
            simulation_result.safety_guard.safety_status,
            TrainingSimulationSafetyStatus::Violated
        )
        && !matches!(head_shape_status, HeadShapeStatus::Invalid)
        && matches!(dataset_status, TrainingSimulationDatasetStatus::Ready);
    let next_allowed_step = if allow_adapter_skeleton_next {
        AdapterSkeletonNextAllowedStep::BuildMamba3GatedDeltaNetAdapterSkeleton
    } else if matches!(
        dataset_status,
        TrainingSimulationDatasetStatus::NeedsMoreData
    ) {
        warnings.push("more no-persistence simulation coverage is still required".to_string());
        AdapterSkeletonNextAllowedStep::NeedsMoreData
    } else if matches!(
        dataset_status,
        TrainingSimulationDatasetStatus::BlockedByWeakLabels
            | TrainingSimulationDatasetStatus::BlockedBySafety
    ) || matches!(head_shape_status, HeadShapeStatus::Invalid)
    {
        if matches!(head_shape_status, HeadShapeStatus::Invalid) {
            blockers.push("head shape validation failed".to_string());
        }
        AdapterSkeletonNextAllowedStep::BlockedBySafety
    } else {
        AdapterSkeletonNextAllowedStep::KeepSimulationOnly
    };
    SmartCoreAdapterSkeletonReadinessGate {
        no_persistence_simulation_status: simulation_result.simulation_status,
        safety_guard_status: simulation_result.safety_guard.safety_status,
        batch_shape_status,
        head_shape_status,
        dataset_status,
        allow_adapter_skeleton_next,
        next_allowed_step,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_no_persistence_training_simulation_brief(
    simulation_result: &NoPersistenceTrainingSimulationResult,
    adapter_gate: &SmartCoreAdapterSkeletonReadinessGate,
) -> NoPersistenceTrainingSimulationBrief {
    let mut per_member_summary = std::collections::BTreeMap::new();
    let mut per_member_counts = std::collections::BTreeMap::new();
    let mut per_head_summary = std::collections::BTreeMap::new();
    let mut per_head_counts = std::collections::BTreeMap::new();
    for step in &simulation_result.step_records {
        *per_member_summary
            .entry(step.member_id.clone())
            .or_insert(0.0) += step.aggregate_dummy_loss;
        *per_member_counts
            .entry(step.member_id.clone())
            .or_insert(0usize) += 1;
        for loss in &step.dummy_head_losses {
            let head_name = training_target_head_name(loss.head).to_string();
            *per_head_summary.entry(head_name.clone()).or_insert(0.0) += loss.dummy_loss_value;
            *per_head_counts.entry(head_name).or_insert(0usize) += 1;
        }
    }
    for (member_id, total_loss) in &mut per_member_summary {
        *total_loss /= per_member_counts
            .get(member_id)
            .copied()
            .unwrap_or(1)
            .max(1) as f64;
    }
    for (head_name, total_loss) in &mut per_head_summary {
        *total_loss /= per_head_counts.get(head_name).copied().unwrap_or(1).max(1) as f64;
    }
    let step_count = simulation_result.step_records.len();
    let epoch_count = simulation_result.epoch_results.len();
    let aggregate_dummy_loss = if step_count == 0 {
        0.0
    } else {
        simulation_result
            .step_records
            .iter()
            .map(|step| step.aggregate_dummy_loss)
            .sum::<f64>()
            / step_count as f64
    };
    let safety_summary = if simulation_result.safety_guard.violations.is_empty() {
        format!("{:?}", simulation_result.safety_guard.safety_status)
    } else {
        format!(
            "{:?}: {}",
            simulation_result.safety_guard.safety_status,
            simulation_result.safety_guard.violations.join(", ")
        )
    };
    let human_readable_summary = format!(
        "dummy loss simulation only; no weights updated; no optimizer/backprop/checkpoint; Mamba3/Gated runtime still deferred; next step: {:?}",
        adapter_gate.next_allowed_step
    );
    NoPersistenceTrainingSimulationBrief {
        brief_id: format!("{}-brief", simulation_result.simulation_id),
        simulation_status: simulation_result.simulation_status,
        dataset_id: simulation_result.dataset_id.clone(),
        step_count,
        epoch_count,
        aggregate_dummy_loss,
        per_member_summary,
        per_head_summary,
        safety_summary,
        next_allowed_step: adapter_gate.next_allowed_step,
        human_readable_summary,
        paper_only: true,
    }
}

impl SmartCoreAdapterRegistry {
    pub fn get_profile(&self, member_id: &str) -> Option<&MemberSmartCoreAdapterProfile> {
        let requested_display_name = display_name_for_member_id(member_id);
        let requested_role = role_for_member_id(member_id);
        self.profiles.iter().find(|profile| {
            profile.member_id == member_id
                || display_name_for_member_id(&profile.member_id) == requested_display_name
                || requested_role
                    .map(|role| profile.role == role)
                    .unwrap_or(false)
        })
    }

    pub fn validate_registry(&self) -> bool {
        self.profile_count == self.profiles.len()
            && self.runtime_ready_count == 0
            && self.training_ready_count == 0
            && self.shape_only_count
                == self
                    .profiles
                    .iter()
                    .filter(|profile| {
                        matches!(profile.adapter_status, SmartCoreV2AdapterStatus::ShapeOnly)
                    })
                    .count()
            && self.profiles.iter().all(|profile| profile.paper_only)
    }

    pub fn adapter_profiles_for_active_members(
        &self,
        active_member_ids: &[String],
    ) -> Vec<MemberSmartCoreAdapterProfile> {
        active_member_ids
            .iter()
            .filter_map(|member_id| self.get_profile(member_id).cloned())
            .collect()
    }
}

impl SmartCoreV2AdapterTrait for ShapeOnlySmartCoreV2Adapter {
    fn adapter_id(&self) -> &str {
        &self.adapter_id
    }

    fn member_id(&self) -> &str {
        &self.member_id
    }

    fn adapter_kind(&self) -> SmartCoreV2AdapterKind {
        self.adapter_kind
    }

    fn status(&self) -> SmartCoreV2AdapterStatus {
        self.status
    }

    fn validate_input_shape(
        &self,
        input: &SmartCoreV2AdapterInputShape,
    ) -> AdapterShapeValidationResult {
        let mut warnings = Vec::new();
        let mut invalid = false;
        if input.member_id != self.member_id {
            warnings.push("input shape member id does not match adapter member id".to_string());
            invalid = true;
        }
        if input.example_count == 0 {
            warnings.push("adapter input shape has zero examples".to_string());
            invalid = true;
        }
        if input.sequence_len == 0 {
            warnings.push("adapter input shape has zero sequence length".to_string());
            invalid = true;
        }
        if input.feature_dim == 0 {
            warnings.push("adapter input shape has zero feature dimension".to_string());
            invalid = true;
        }
        if !input.has_news_features {
            warnings.push("adapter input shape has no news features".to_string());
        }
        if !input.has_owner_context {
            warnings.push("adapter input shape has no owner context features".to_string());
        }
        if !input.has_prior_memory {
            warnings.push("adapter input shape has no prior memory features".to_string());
        }
        AdapterShapeValidationResult {
            shape_id: input.shape_id.clone(),
            validation_status: if invalid {
                AdapterShapeValidationStatus::Invalid
            } else if warnings.is_empty() {
                AdapterShapeValidationStatus::Valid
            } else {
                AdapterShapeValidationStatus::ValidWithWarnings
            },
            warnings,
            paper_only: true,
        }
    }

    fn validate_output_shape(
        &self,
        output: &SmartCoreV2AdapterOutputShape,
    ) -> AdapterShapeValidationResult {
        let mut warnings = Vec::new();
        let mut invalid = false;
        if output.member_id != self.member_id {
            warnings.push("output shape member id does not match adapter member id".to_string());
            invalid = true;
        }
        if output.example_count == 0 {
            warnings.push("adapter output shape has zero examples".to_string());
            invalid = true;
        }
        if output.stance_output_dim == 0
            || output.confidence_output_dim == 0
            || output.risk_output_dim == 0
            || output.evidence_output_dim == 0
        {
            warnings.push("required adapter head output dimension is zero".to_string());
            invalid = true;
        }
        if output.enabled_heads.is_empty() {
            warnings.push("adapter output shape exposes no heads".to_string());
            invalid = true;
        }
        AdapterShapeValidationResult {
            shape_id: output.shape_id.clone(),
            validation_status: if invalid {
                AdapterShapeValidationStatus::Invalid
            } else if warnings.is_empty() {
                AdapterShapeValidationStatus::Valid
            } else {
                AdapterShapeValidationStatus::ValidWithWarnings
            },
            warnings,
            paper_only: true,
        }
    }

    fn runtime_ready(&self) -> bool {
        false
    }

    fn training_ready(&self) -> bool {
        false
    }
}

fn adapter_kind_for_profile(
    core_v2_spec: &SmartMemberCoreV2Spec,
    include_sparse_event_attention: bool,
) -> SmartCoreV2AdapterKind {
    match (
        core_v2_spec.temporal_core,
        core_v2_spec.memory_core,
        core_v2_spec.event_attention_core,
        include_sparse_event_attention,
    ) {
        (
            SmartCoreV2ComponentStatus::Mamba3Deferred | SmartCoreV2ComponentStatus::Deferred,
            SmartCoreV2ComponentStatus::GatedDeltaNetDeferred
            | SmartCoreV2ComponentStatus::Deferred,
            SmartCoreV2ComponentStatus::SparseEventAttentionDeferred
            | SmartCoreV2ComponentStatus::Deferred,
            true,
        ) => SmartCoreV2AdapterKind::Mamba3GatedDeltaNetSparseEvent,
        (
            SmartCoreV2ComponentStatus::Mamba3Deferred | SmartCoreV2ComponentStatus::Deferred,
            SmartCoreV2ComponentStatus::GatedDeltaNetDeferred
            | SmartCoreV2ComponentStatus::Deferred,
            _,
            _,
        ) => SmartCoreV2AdapterKind::Mamba3GatedDeltaNet,
        (
            SmartCoreV2ComponentStatus::Mamba3Deferred | SmartCoreV2ComponentStatus::Deferred,
            SmartCoreV2ComponentStatus::None,
            _,
            _,
        ) => SmartCoreV2AdapterKind::Mamba3OnlyDeferred,
        (
            SmartCoreV2ComponentStatus::None,
            SmartCoreV2ComponentStatus::GatedDeltaNetDeferred
            | SmartCoreV2ComponentStatus::Deferred,
            _,
            _,
        ) => SmartCoreV2AdapterKind::GatedDeltaNetOnlyDeferred,
        _ => SmartCoreV2AdapterKind::Mamba3GatedDeltaNet,
    }
}

fn adapter_head_kind(head: TrainingTargetHead) -> SmartCoreV2HeadKind {
    match head {
        TrainingTargetHead::Stance => SmartCoreV2HeadKind::Stance,
        TrainingTargetHead::ConfidenceCalibration => SmartCoreV2HeadKind::ConfidenceCalibration,
        TrainingTargetHead::Risk => SmartCoreV2HeadKind::Risk,
        TrainingTargetHead::EvidenceNeed => SmartCoreV2HeadKind::EvidenceNeed,
        TrainingTargetHead::Uncertainty => SmartCoreV2HeadKind::Uncertainty,
        TrainingTargetHead::ExpectedReturnHint => SmartCoreV2HeadKind::ExpectedReturnHint,
    }
}

fn role_head_order(role: IndependentMemberRole) -> Vec<TrainingTargetHead> {
    match role {
        IndependentMemberRole::TrendEntry => vec![
            TrainingTargetHead::Stance,
            TrainingTargetHead::ConfidenceCalibration,
            TrainingTargetHead::ExpectedReturnHint,
            TrainingTargetHead::EvidenceNeed,
            TrainingTargetHead::Risk,
            TrainingTargetHead::Uncertainty,
        ],
        IndependentMemberRole::RiskGuard => vec![
            TrainingTargetHead::Risk,
            TrainingTargetHead::Uncertainty,
            TrainingTargetHead::EvidenceNeed,
            TrainingTargetHead::ConfidenceCalibration,
            TrainingTargetHead::Stance,
            TrainingTargetHead::ExpectedReturnHint,
        ],
        IndependentMemberRole::EvidenceRegime => vec![
            TrainingTargetHead::EvidenceNeed,
            TrainingTargetHead::ConfidenceCalibration,
            TrainingTargetHead::Risk,
            TrainingTargetHead::Stance,
            TrainingTargetHead::Uncertainty,
            TrainingTargetHead::ExpectedReturnHint,
        ],
    }
}

fn default_sparse_event_attention_types() -> Vec<SparseEventAttentionType> {
    vec![
        SparseEventAttentionType::RiskVeto,
        SparseEventAttentionType::EarningsShock,
        SparseEventAttentionType::MacroEvent,
        SparseEventAttentionType::VolatilitySpike,
        SparseEventAttentionType::OwnerConcern,
        SparseEventAttentionType::ContradictoryEvidence,
        SparseEventAttentionType::EvidenceGap,
    ]
}

fn build_head_adapter_spec(
    member_id: &str,
    head: TrainingTargetHead,
) -> SmartCoreV2HeadAdapterSpec {
    let shape = head_shape_spec(head);
    SmartCoreV2HeadAdapterSpec {
        spec_id: format!("{}-{}-head", member_id, training_target_head_name(head)),
        member_id: member_id.to_string(),
        head_kind: adapter_head_kind(head),
        output_kind: shape.output_kind,
        output_dim: shape.expected_dim,
        target_required: shape.target_required,
        runtime_status: SmartCoreV2AdapterStatus::RuntimeDeferred,
        training_status: SmartCoreV2AdapterStatus::TrainingDeferred,
        paper_only: true,
    }
}

fn build_mamba3_temporal_adapter_spec(
    core_v2_spec: &SmartMemberCoreV2Spec,
) -> Mamba3TemporalAdapterSpec {
    let default_feature_schema = TrainingFeatureSchema::default();
    Mamba3TemporalAdapterSpec {
        spec_id: format!("{}-mamba3-skeleton", core_v2_spec.member_id),
        member_id: core_v2_spec.member_id.clone(),
        state_size_hint: core_v2_spec.base_core_spec.memory_budget_mb_hint.max(1) as usize,
        sequence_len_hint: default_feature_schema.sequence_len_hint.max(1),
        feature_dim_hint: default_feature_schema.feature_groups.len().max(1),
        selective_scan_status: AdapterDeferredStatus::Deferred,
        causal_ordering_required: true,
        runtime_status: SmartCoreV2AdapterStatus::RuntimeDeferred,
        training_status: SmartCoreV2AdapterStatus::TrainingDeferred,
        paper_only: true,
    }
}

fn build_gated_deltanet_memory_adapter_spec(
    core_v2_spec: &SmartMemberCoreV2Spec,
) -> GatedDeltaNetMemoryAdapterSpec {
    let default_feature_schema = TrainingFeatureSchema::default();
    GatedDeltaNetMemoryAdapterSpec {
        spec_id: format!("{}-gated-deltanet-skeleton", core_v2_spec.member_id),
        member_id: core_v2_spec.member_id.clone(),
        memory_dim_hint: default_feature_schema.feature_groups.len().max(1),
        update_rule_status: AdapterDeferredStatus::Deferred,
        erase_gate_status: AdapterDeferredStatus::Deferred,
        write_gate_status: AdapterDeferredStatus::Deferred,
        memory_persistence: GatedDeltaNetMemoryPersistence::None,
        runtime_status: SmartCoreV2AdapterStatus::RuntimeDeferred,
        training_status: SmartCoreV2AdapterStatus::TrainingDeferred,
        paper_only: true,
    }
}

fn build_sparse_event_attention_adapter_spec(
    member_id: &str,
    enabled: bool,
) -> Option<SparseEventAttentionAdapterSpec> {
    enabled.then(|| SparseEventAttentionAdapterSpec {
        spec_id: format!("{}-sparse-event-skeleton", member_id),
        member_id: member_id.to_string(),
        enabled: true,
        event_types: default_sparse_event_attention_types(),
        max_events_per_sequence: 16,
        attention_runtime_status: AdapterDeferredStatus::Deferred,
        paper_only: true,
    })
}

pub fn validate_mamba3_temporal_adapter_spec(
    spec: &Mamba3TemporalAdapterSpec,
) -> AdapterShapeValidationResult {
    let mut warnings = Vec::new();
    if spec.sequence_len_hint == 0 {
        warnings.push("Mamba3 adapter sequence_len_hint must be positive".to_string());
    }
    if spec.feature_dim_hint == 0 {
        warnings.push("Mamba3 adapter feature_dim_hint must be positive".to_string());
    }
    if !matches!(
        spec.runtime_status,
        SmartCoreV2AdapterStatus::RuntimeDeferred
    ) {
        warnings.push("Mamba3 adapter runtime must remain deferred".to_string());
    }
    if !matches!(
        spec.training_status,
        SmartCoreV2AdapterStatus::TrainingDeferred
    ) {
        warnings.push("Mamba3 adapter training must remain deferred".to_string());
    }
    if !spec.paper_only {
        warnings.push("Mamba3 adapter spec must remain paper-only".to_string());
    }
    AdapterShapeValidationResult {
        shape_id: spec.spec_id.clone(),
        validation_status: if warnings.is_empty() {
            AdapterShapeValidationStatus::Valid
        } else {
            AdapterShapeValidationStatus::Invalid
        },
        warnings,
        paper_only: true,
    }
}

