fn load_paper_label_validation_policy_from_local_file(
    path: &Path,
) -> Result<PaperLabelValidationPolicy, String> {
    validate_local_json_path(path, "paper label validation policy path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_offline_batch_text(&text)?;
    if path.extension().and_then(|ext| ext.to_str()) == Some("toml") {
        toml::from_str(&text).map_err(|err| err.to_string())
    } else {
        serde_json::from_str(&text).map_err(|err| err.to_string())
    }
}

fn load_backtest_label_contract_from_local_file(
    path: &Path,
) -> Result<BacktestLabelContract, String> {
    validate_local_json_path(path, "backtest label contract path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_offline_batch_text(&text)?;
    if path.extension().and_then(|ext| ext.to_str()) == Some("toml") {
        toml::from_str(&text).map_err(|err| err.to_string())
    } else {
        serde_json::from_str(&text).map_err(|err| err.to_string())
    }
}

fn load_paper_outcome_fixtures_from_local_json(
    path: &Path,
) -> Result<Vec<PaperOutcomeFixture>, String> {
    validate_local_json_path(path, "paper outcome fixture path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_offline_batch_text(&text)?;
    let fixtures = if let Ok(fixtures) = serde_json::from_str::<Vec<PaperOutcomeFixture>>(&text) {
        fixtures
    } else {
        #[derive(Deserialize)]
        struct FixtureFile {
            fixtures: Vec<PaperOutcomeFixture>,
        }
        serde_json::from_str::<FixtureFile>(&text)
            .map_err(|err| err.to_string())?
            .fixtures
    };
    if fixtures.iter().any(|fixture| !fixture.paper_only) {
        return Err("paper outcome fixtures must be paper-only".to_string());
    }
    Ok(fixtures)
}

fn synthetic_market_data_for_scenario(item: &PaperScenarioCollectionItem) -> MarketDataSnapshot {
    let symbol = item
        .symbol
        .clone()
        .unwrap_or_else(|| "PAPER-SCENARIO".to_string());
    let market_scope = item.market_scope.unwrap_or(MarketScope::KoreaShortTerm);
    let risk_case = item
        .event_type
        .as_deref()
        .map(|event_type| event_type == "RiskWarning")
        .unwrap_or(false);
    MarketDataSnapshot {
        symbol,
        market_scope,
        timestamp: "paper-scenario-collection".to_string(),
        price: 100.0,
        change_pct: if risk_case { -0.035 } else { 0.018 },
        volume: 1_000_000.0,
        volatility_hint: if risk_case { 0.18 } else { 0.04 },
        source_label: "synthetic-paper-scenario-fixture".to_string(),
    }
}

fn synthetic_news_for_scenario(item: &PaperScenarioCollectionItem) -> Vec<NewsSnapshot> {
    let market = synthetic_market_data_for_scenario(item);
    vec![NewsSnapshot {
        symbol: market.symbol,
        headline: format!("Paper scenario coverage item {}", item.item_id),
        summary: item.suggested_fixture_hint.clone(),
        sentiment_hint: if item.event_type.as_deref() == Some("RiskWarning") {
            "negative".to_string()
        } else {
            "neutral".to_string()
        },
        source_label: "synthetic-paper-scenario-fixture".to_string(),
        timestamp: "paper-scenario-collection".to_string(),
    }]
}

fn fixture_for_scenario_item<'a>(
    item: &PaperScenarioCollectionItem,
    fixtures: &'a [PaperOutcomeFixture],
) -> Option<&'a PaperOutcomeFixture> {
    fixtures.iter().find(|fixture| {
        item.symbol
            .as_ref()
            .map(|symbol| symbol == &fixture.symbol)
            .unwrap_or(true)
            && item
                .market_scope
                .map(|scope| scope == fixture.market_scope)
                .unwrap_or(true)
    })
}

fn fixture_label_confidence(fixture: &PaperOutcomeFixture) -> ReplayLabelConfidence {
    if fixture.label_confidence == ReplayLabelConfidence::ReviewRequired {
        fixture.confidence
    } else {
        fixture.label_confidence
    }
}

pub fn run_paper_scenario_collection(
    config: PaperScenarioRunConfig,
) -> Result<PaperScenarioRunResult, String> {
    if !config.paper_only || !config.collection_queue.paper_only {
        return Err("paper scenario collection must be paper-only".to_string());
    }
    for path in [
        config.market_data_path.as_ref(),
        config.news_path.as_ref(),
        config.news_cache_path.as_ref(),
        config.offline_member_output_batch_path.as_ref(),
        config.member_state_input_path.as_ref(),
        config.paper_outcome_fixture_path.as_ref(),
    ]
    .into_iter()
    .flatten()
    {
        if !local_only(path) {
            return Err("paper scenario collection paths must be local".to_string());
        }
    }

    let local_market_data = if let Some(path) = &config.market_data_path {
        load_market_data_from_local_json(Path::new(path))?
    } else {
        Vec::new()
    };
    let local_news = if let Some(path) = &config.news_path {
        load_news_from_local_json(Path::new(path))?
    } else {
        Vec::new()
    };
    let mut outcome_fixtures = config.outcome_fixtures.clone();
    if let Some(path) = &config.paper_outcome_fixture_path {
        outcome_fixtures.extend(load_paper_outcome_fixtures_from_local_json(Path::new(
            path,
        ))?);
    }

    let mut all_records = Vec::new();
    let mut used_fixture_count = 0;
    let source_items = if config.collection_items.is_empty() {
        config.collection_queue.items.clone()
    } else {
        config.collection_items.clone()
    };
    let max_items = config.max_items.unwrap_or(source_items.len());
    let selected_items: Vec<PaperScenarioCollectionItem> =
        source_items.iter().take(max_items).cloned().collect();
    let remaining_items: Vec<PaperScenarioCollectionItem> =
        source_items.iter().skip(max_items).cloned().collect();
    for item in &selected_items {
        let market_data = local_market_data
            .iter()
            .find(|snapshot| {
                item.symbol
                    .as_ref()
                    .map(|symbol| symbol == &snapshot.symbol)
                    .unwrap_or(true)
                    && item
                        .market_scope
                        .map(|scope| scope == snapshot.market_scope)
                        .unwrap_or(true)
            })
            .cloned()
            .unwrap_or_else(|| synthetic_market_data_for_scenario(item));
        let news: Vec<NewsSnapshot> = local_news
            .iter()
            .filter(|snapshot| snapshot.symbol == market_data.symbol)
            .cloned()
            .collect();
        let news = if news.is_empty() {
            synthetic_news_for_scenario(item)
        } else {
            news
        };
        let fixture = fixture_for_scenario_item(item, &outcome_fixtures);
        if fixture.is_some() {
            used_fixture_count += 1;
        }
        let batch_result =
            run_batch_committee_cycle_with_state(BatchCommitteeCycleWithStateInput {
                batch_input: BatchCommitteeCycleInput {
                    market_data: vec![market_data.clone()],
                    news,
                    members: create_three_member_pilot_roster(market_data.market_scope),
                    offline_output_batch: None,
                    owner_context: Some(format!("paper scenario collection: {}", item.reason)),
                    paper_outcome: fixture.map(|fixture| fixture.outcome),
                },
                member_state_store: None,
                member_state_output_path: None,
                emit_owner_summary: true,
                emit_owner_console_view: false,
                owner_feedback: Vec::new(),
                emit_reconsideration_view: false,
            })?
            .batch_result;
        all_records.extend(batch_result.member_experience_records);
    }

    let generated_experience_records = all_records.clone();
    let experience_store = MemberExperienceStore::new(
        format!("{}-experience-store", config.scenario_run_id),
        all_records,
    );
    let mut sanitized_replay_build = build_sanitized_replay_dataset_from_experience_store(
        &experience_store,
        SanitizedReplayDatasetBuildConfig {
            source_experience_store_id: experience_store.store_id.clone(),
            strict_temporal_boundary: true,
            include_post_decision_context_for_audit: true,
            include_prior_memory_buckets: true,
            reject_on_blocking_leakage: true,
            paper_only: true,
        },
    );
    for example in &mut sanitized_replay_build.dataset.examples {
        if let Some(labels) = example.target_labels.as_mut() {
            if let Some(fixture) = outcome_fixtures.iter().find(|fixture| {
                fixture.symbol == example.symbol && fixture.market_scope == example.market_scope
            }) {
                labels.label_source = fixture.label_source;
                labels.label_confidence = fixture_label_confidence(fixture);
            } else {
                labels.label_source = ReplayLabelSource::SimulatedFixture;
                labels.label_confidence = ReplayLabelConfidence::Medium;
            }
        }
    }
    let replay_quality_eval = run_replay_quality_evaluation_with_thresholds(
        &experience_store,
        &sanitized_replay_build.dataset,
        1,
        1,
    );

    let generated_batch_count = selected_items.len();
    let collection_queue_remaining = PaperScenarioCollectionQueue {
        queue_id: format!("{}-remaining", config.collection_queue.queue_id),
        high_priority_count: remaining_items
            .iter()
            .filter(|item| item.priority == ReplayCoverageGapPriority::High)
            .count(),
        item_count: remaining_items.len(),
        items: remaining_items,
        paper_only: true,
    };
    Ok(PaperScenarioRunResult {
        scenario_run_id: config.scenario_run_id,
        generated_batch_count,
        generated_experience_record_count: experience_store.record_count,
        generated_experience_records,
        generated_replay_examples: sanitized_replay_build.dataset.examples.clone(),
        used_fixture_count,
        collection_queue_remaining,
        collection_queue: config.collection_queue,
        replay_dataset: sanitized_replay_build.dataset.clone(),
        sanitized_replay_build_result: sanitized_replay_build.clone(),
        sanitized_replay_build,
        quality_eval_result: replay_quality_eval.clone(),
        replay_quality_eval,
        safety_summary: safety_summary(),
        paper_only: true,
    })
}

fn leakage_issue_type_for_term(term: &str) -> ReplayLeakageIssueType {
    let lower = term.to_ascii_lowercase();
    if lower.contains("chairman") || lower == "final_action" {
        ReplayLeakageIssueType::ChairmanDecisionInInput
    } else if lower.contains("risk") || lower.contains("veto") {
        ReplayLeakageIssueType::RiskVetoInInput
    } else if lower.contains("broker")
        || lower.contains("order")
        || lower.contains("account")
        || lower.contains("position")
        || lower.contains("holdings")
        || lower.contains("buying_power")
    {
        ReplayLeakageIssueType::BrokerAccountFieldDetected
    } else if lower.contains("pnl") {
        ReplayLeakageIssueType::RealTradeFieldDetected
    } else if lower.contains("label") || lower.contains("attribution") {
        ReplayLeakageIssueType::LabelCopiedIntoFeatures
    } else {
        ReplayLeakageIssueType::FutureOutcomeInInput
    }
}

fn memory_count_bucket(count: u32) -> MemoryCountBucket {
    match count {
        0 => MemoryCountBucket::None,
        1..=2 => MemoryCountBucket::Low,
        3..=5 => MemoryCountBucket::Medium,
        _ => MemoryCountBucket::High,
    }
}

fn evidence_need_tendency_from_notes(notes: &[String]) -> EvidenceNeedTendency {
    let evidence_notes = notes
        .iter()
        .filter(|note| note.to_ascii_lowercase().contains("evidence"))
        .count();
    match evidence_notes {
        0 => EvidenceNeedTendency::Unknown,
        1 => EvidenceNeedTendency::Low,
        2..=3 => EvidenceNeedTendency::Medium,
        _ => EvidenceNeedTendency::High,
    }
}

