pub fn evaluate_replay_dataset_quality(dataset: &ReplayDataset) -> ReplayDatasetQualitySummary {
    let mut member_ids_covered: Vec<String> = dataset
        .examples
        .iter()
        .map(|example| example.member_id.clone())
        .collect();
    member_ids_covered.sort();
    member_ids_covered.dedup();
    let mut symbols_covered: Vec<String> = dataset
        .examples
        .iter()
        .map(|example| example.symbol.clone())
        .collect();
    symbols_covered.sort();
    symbols_covered.dedup();

    let mut market_scopes_covered: Vec<MarketScope> = dataset
        .examples
        .iter()
        .map(|example| example.market_scope)
        .collect();
    market_scopes_covered.sort();
    market_scopes_covered.dedup();

    let mut stance_distribution = std::collections::BTreeMap::new();
    let mut outcome_label_distribution = std::collections::BTreeMap::new();
    let mut risk_label_distribution = std::collections::BTreeMap::new();
    let mut evidence_label_distribution = std::collections::BTreeMap::new();
    let mut confidence_distribution = std::collections::BTreeMap::new();
    let mut high_confidence_count = 0;
    let mut low_confidence_count = 0;
    let mut missing_outcome_count = 0;
    let mut review_required_count = 0;

    for example in &dataset.examples {
        increment_count(
            &mut stance_distribution,
            format!("{:?}", example.target.stance),
        );
        increment_count(
            &mut outcome_label_distribution,
            format!("{:?}", example.target.outcome_label),
        );
        increment_count(
            &mut risk_label_distribution,
            example.target.risk_label.clone(),
        );
        increment_count(
            &mut evidence_label_distribution,
            example.target.evidence_label.clone(),
        );
        let confidence_bucket = confidence_bucket_for_label(example.target.confidence_calibration);
        increment_count(&mut confidence_distribution, confidence_bucket.to_string());
        if confidence_bucket == "high" {
            high_confidence_count += 1;
        }
        if confidence_bucket == "low" {
            low_confidence_count += 1;
        }
        if matches!(
            example.target.outcome_label,
            MemberExperienceOutcome::Unknown
        ) {
            missing_outcome_count += 1;
        }
        if example.target.evidence_label == "insufficient_evidence"
            || matches!(
                example.target.confidence_calibration,
                MemberLearningLabel::NeedMoreEvidence
            )
        {
            review_required_count += 1;
        }
    }

    let quality_status = if !dataset.paper_only
        || dataset.examples.iter().any(|example| !example.paper_only)
        || dataset.example_count != dataset.examples.len()
    {
        ReplayQualityStatus::UnsafeForTraining
    } else if dataset.member_count != member_ids_covered.len() {
        ReplayQualityStatus::UnsafeForTraining
    } else if dataset.example_count < 10 || dataset.member_count == 0 {
        ReplayQualityStatus::NeedsMoreData
    } else if missing_outcome_count > 0 || review_required_count > 0 || low_confidence_count > 0 {
        ReplayQualityStatus::ReadyWithWarnings
    } else {
        ReplayQualityStatus::Ready
    };

    ReplayDatasetQualitySummary {
        dataset_id: dataset.dataset_id.clone(),
        example_count: dataset.example_count,
        member_count: member_ids_covered.len(),
        symbols_covered,
        market_scopes_covered,
        stance_distribution,
        outcome_label_distribution,
        risk_label_distribution,
        evidence_label_distribution,
        confidence_distribution,
        high_confidence_count,
        low_confidence_count,
        missing_outcome_count,
        review_required_count,
        quality_status,
        paper_only: true,
    }
}

pub fn check_replay_data_leakage(dataset: &ReplayDataset) -> ReplayDataLeakageCheck {
    let mut leakage_findings = Vec::new();
    for example in &dataset.examples {
        inspect_replay_feature_for_leakage(
            example,
            ReplaySection::InputFeatures,
            "market_data_summary",
            &example.input_features.market_data_summary,
            &mut leakage_findings,
        );
        inspect_replay_feature_for_leakage(
            example,
            ReplaySection::InputFeatures,
            "news_summary",
            &example.input_features.news_summary,
            &mut leakage_findings,
        );
        if let Some(value) = &example.input_features.owner_context_summary {
            inspect_replay_feature_for_leakage(
                example,
                ReplaySection::InputFeatures,
                "owner_context_summary",
                value,
                &mut leakage_findings,
            );
        }
        if let Some(value) = &example.input_features.memory_state_summary {
            inspect_replay_feature_for_leakage(
                example,
                ReplaySection::InputFeatures,
                "memory_state_summary",
                value,
                &mut leakage_findings,
            );
        }
        if let Some(context) = &example.post_decision_context {
            inspect_replay_feature_for_leakage(
                example,
                ReplaySection::PostDecisionContext,
                "other_member_stances",
                &context.other_member_stances.join(" "),
                &mut leakage_findings,
            );
            inspect_replay_feature_for_leakage(
                example,
                ReplaySection::PostDecisionContext,
                "risk_flags",
                &context.risk_flags.join(" "),
                &mut leakage_findings,
            );
        }
    }
    leakage_findings.sort_by(|left, right| {
        left.replay_id
            .cmp(&right.replay_id)
            .then(left.field_name.cmp(&right.field_name))
            .then(format!("{:?}", left.issue_type).cmp(&format!("{:?}", right.issue_type)))
    });

    let has_blocking = leakage_findings
        .iter()
        .any(|finding| finding.severity == ReplayLeakageSeverity::Blocking);
    let has_safety_blocker = leakage_findings.iter().any(|finding| {
        matches!(
            finding.issue_type,
            ReplayLeakageIssueType::BrokerAccountFieldDetected
                | ReplayLeakageIssueType::RealTradeFieldDetected
        )
    });
    let leakage_status = if has_safety_blocker || !dataset.paper_only {
        ReplayLeakageStatus::UnsafeForTraining
    } else if has_blocking {
        ReplayLeakageStatus::LeakageDetected
    } else if leakage_findings.is_empty() {
        ReplayLeakageStatus::NoLeakageDetected
    } else {
        ReplayLeakageStatus::LeakageWarnings
    };

    ReplayDataLeakageCheck {
        dataset_id: dataset.dataset_id.clone(),
        checked_example_count: dataset.examples.len(),
        leakage_findings,
        leakage_status,
        paper_only: true,
    }
}

pub fn evaluate_member_calibration(
    records: &[MemberExperienceRecord],
    member_id: &str,
) -> MemberCalibrationEval {
    let member_records: Vec<&MemberExperienceRecord> = records
        .iter()
        .filter(|record| record.member_id == member_id)
        .collect();
    let total_examples = member_records.len();
    let high_confidence_examples = member_records
        .iter()
        .filter(|record| record.member_opinion.confidence >= 0.75)
        .count();
    let high_confidence_bad_outcomes = member_records
        .iter()
        .filter(|record| {
            record.member_opinion.confidence >= 0.75 && is_bad_member_outcome(record.outcome)
        })
        .count();
    let low_confidence_good_outcomes = member_records
        .iter()
        .filter(|record| {
            record.member_opinion.confidence <= 0.45 && is_good_member_outcome(record.outcome)
        })
        .count();
    let risk_veto_cases = member_records
        .iter()
        .filter(|record| {
            record.committee_context.risk_governor_status == Some(RiskGovernorStatus::Vetoed)
        })
        .count();
    let risk_veto_aligned = member_records
        .iter()
        .filter(|record| {
            record.committee_context.risk_governor_status == Some(RiskGovernorStatus::Vetoed)
                && matches!(
                    record.outcome,
                    MemberExperienceOutcome::RiskVetoSavedLoss
                        | MemberExperienceOutcome::BadRiskCall
                        | MemberExperienceOutcome::PaperNegative
                )
        })
        .count();
    let evidence_requests = member_records
        .iter()
        .filter(|record| {
            matches!(
                record.member_opinion.stance,
                MemberStance::NeedMoreEvidence | MemberStance::Hold
            ) || matches!(record.learning_label, MemberLearningLabel::NeedMoreEvidence)
        })
        .count();
    let evidence_aligned = member_records
        .iter()
        .filter(|record| {
            (matches!(
                record.member_opinion.stance,
                MemberStance::NeedMoreEvidence | MemberStance::Hold
            ) || matches!(record.learning_label, MemberLearningLabel::NeedMoreEvidence))
                && matches!(
                    record.outcome,
                    MemberExperienceOutcome::Unknown
                        | MemberExperienceOutcome::MissedOpportunity
                        | MemberExperienceOutcome::PaperNeutral
                )
        })
        .count();

    let overconfidence_rate = ratio(high_confidence_bad_outcomes, high_confidence_examples);
    let underconfidence_rate = ratio(low_confidence_good_outcomes, total_examples);
    let risk_veto_alignment_rate = ratio(risk_veto_aligned, risk_veto_cases);
    let evidence_request_alignment_rate = ratio(evidence_aligned, evidence_requests);

    let (calibration_status, suggested_adjustment) = if total_examples < 3 {
        (
            MemberCalibrationEvalStatus::InsufficientData,
            MemberCalibrationEvalSuggestedAdjustment::CollectMoreData,
        )
    } else if overconfidence_rate >= 0.25 {
        (
            MemberCalibrationEvalStatus::Overconfident,
            MemberCalibrationEvalSuggestedAdjustment::LowerConfidence,
        )
    } else if underconfidence_rate >= 0.25 {
        (
            MemberCalibrationEvalStatus::Underconfident,
            MemberCalibrationEvalSuggestedAdjustment::RaiseConfidence,
        )
    } else if evidence_requests > 0 && evidence_request_alignment_rate < 0.5 {
        (
            MemberCalibrationEvalStatus::NeedsMoreEvidence,
            MemberCalibrationEvalSuggestedAdjustment::RaiseEvidenceThreshold,
        )
    } else {
        (
            MemberCalibrationEvalStatus::WellCalibrated,
            MemberCalibrationEvalSuggestedAdjustment::Keep,
        )
    };

    MemberCalibrationEval {
        member_id: member_id.to_string(),
        total_examples,
        high_confidence_examples,
        high_confidence_bad_outcomes,
        low_confidence_good_outcomes,
        overconfidence_rate,
        underconfidence_rate,
        risk_veto_alignment_rate,
        evidence_request_alignment_rate,
        calibration_status,
        suggested_adjustment,
        paper_only: true,
    }
}

pub fn evaluate_risk_governor_alignment(
    experience_store: &MemberExperienceStore,
) -> RiskGovernorAlignmentEval {
    let veto_records: Vec<&MemberExperienceRecord> = experience_store
        .records
        .iter()
        .filter(|record| {
            record.committee_context.risk_governor_status == Some(RiskGovernorStatus::Vetoed)
        })
        .collect();
    let bad_risk_call_without_veto_count = experience_store
        .records
        .iter()
        .filter(|record| {
            record.committee_context.risk_governor_status != Some(RiskGovernorStatus::Vetoed)
                && matches!(record.outcome, MemberExperienceOutcome::BadRiskCall)
        })
        .count();
    let total_vetoes = veto_records.len();
    let veto_followed_by_negative_outcome_count = veto_records
        .iter()
        .filter(|record| {
            matches!(
                record.outcome,
                MemberExperienceOutcome::RiskVetoSavedLoss
                    | MemberExperienceOutcome::BadRiskCall
                    | MemberExperienceOutcome::PaperNegative
            )
        })
        .count();
    let veto_followed_by_positive_outcome_count = veto_records
        .iter()
        .filter(|record| matches!(record.outcome, MemberExperienceOutcome::PaperPositive))
        .count();
    let helpful_veto_rate = ratio(veto_followed_by_negative_outcome_count, total_vetoes);
    let possible_overblocking_rate = ratio(veto_followed_by_positive_outcome_count, total_vetoes);
    let risk_alignment_status = if total_vetoes == 0 && bad_risk_call_without_veto_count == 0 {
        RiskAlignmentStatus::InsufficientData
    } else if possible_overblocking_rate >= 0.5 {
        RiskAlignmentStatus::PossiblyTooStrict
    } else if bad_risk_call_without_veto_count > 0 {
        RiskAlignmentStatus::PossiblyTooLoose
    } else if helpful_veto_rate < 0.25 {
        RiskAlignmentStatus::PossiblyTooLoose
    } else {
        RiskAlignmentStatus::Aligned
    };
    let notes = match risk_alignment_status {
        RiskAlignmentStatus::Aligned => {
            vec!["paper veto outcomes support current Risk Governor behavior".to_string()]
        }
        RiskAlignmentStatus::PossiblyTooStrict => {
            vec!["collect more vetoed positive paper outcomes before relaxing policy".to_string()]
        }
        RiskAlignmentStatus::PossiblyTooLoose => {
            let mut notes = vec![
                "collect more bad-risk and high-volatility cases before changing policy"
                    .to_string(),
            ];
            if bad_risk_call_without_veto_count > 0 {
                notes.push(format!(
                    "{bad_risk_call_without_veto_count} bad risk call(s) were not Risk Governor vetoes"
                ));
            }
            notes
        }
        RiskAlignmentStatus::InsufficientData => {
            vec!["not enough paper risk veto cases for alignment evaluation".to_string()]
        }
    };

    RiskGovernorAlignmentEval {
        total_vetoes,
        veto_followed_by_negative_outcome_count,
        veto_followed_by_positive_outcome_count,
        helpful_veto_rate,
        possible_overblocking_rate,
        risk_alignment_status,
        notes,
        paper_only: true,
    }
}

pub fn evaluate_offline_training_readiness(
    dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
) -> OfflineTrainingReadinessGate {
    evaluate_offline_training_readiness_with_thresholds(dataset, experience_store, 10, 2)
}

pub fn evaluate_offline_training_readiness_with_thresholds(
    dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    min_examples_required: usize,
    per_member_min_examples_required: usize,
) -> OfflineTrainingReadinessGate {
    evaluate_offline_training_readiness_with_label_ratio_threshold(
        dataset,
        experience_store,
        min_examples_required,
        per_member_min_examples_required,
        default_min_validated_label_ratio_required(),
    )
}

pub fn evaluate_offline_training_readiness_with_label_ratio_threshold(
    dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    min_examples_required: usize,
    per_member_min_examples_required: usize,
    min_validated_label_ratio_required: f64,
) -> OfflineTrainingReadinessGate {
    let min_validated_label_ratio_required = min_validated_label_ratio_required.clamp(0.0, 1.0);
    let quality_summary = evaluate_replay_dataset_quality(dataset);
    let leakage_check = check_replay_data_leakage(dataset);
    let risk_eval = evaluate_risk_governor_alignment(experience_store);
    let coverage_eval = evaluate_replay_coverage_targets(
        dataset,
        ReplayCoverageTargetConfig {
            min_examples_total: min_examples_required,
            min_total_examples: min_examples_required,
            min_examples_per_member: per_member_min_examples_required,
            min_examples_per_market_scope: 1,
            min_examples_per_event_type: 1,
            require_non_weak_label_source: true,
            allowed_weak_label_ratio: 0.25,
            paper_only: true,
            ..ReplayCoverageTargetConfig::default()
        },
    );
    let label_source_status = if coverage_eval.weak_label_count > 0
        && coverage_eval.weak_label_ratio > coverage_eval.target_config.allowed_weak_label_ratio
    {
        ReplayCoverageTargetStatus::BlockedByWeakLabels
    } else {
        ReplayCoverageTargetStatus::Met
    };
    let validated_label_count = dataset
        .examples
        .iter()
        .filter(|example| is_validated_replay_label(example))
        .count();
    let weak_label_count = dataset
        .examples
        .iter()
        .filter(|example| is_weak_replay_label(example))
        .count();
    let rejected_label_count = dataset
        .examples
        .iter()
        .filter(|example| is_rejected_replay_label(example))
        .count();
    let validated_label_ratio = ratio(validated_label_count, dataset.examples.len());
    let label_promotion_status = if rejected_label_count > 0 {
        LabelQualityStatus::Blocked
    } else if validated_label_ratio >= 0.8 {
        LabelQualityStatus::Strong
    } else if validated_label_ratio >= min_validated_label_ratio_required {
        LabelQualityStatus::Acceptable
    } else {
        LabelQualityStatus::Weak
    };
    let mut member_ids: Vec<String> = experience_store
        .records
        .iter()
        .map(|record| record.member_id.clone())
        .collect();
    member_ids.sort();
    member_ids.dedup();

    let mut member_calibration_statuses = std::collections::BTreeMap::new();
    let mut per_member_counts = std::collections::BTreeMap::new();
    for member_id in &member_ids {
        let calibration = evaluate_member_calibration(&experience_store.records, member_id);
        per_member_counts.insert(member_id.clone(), calibration.total_examples);
        member_calibration_statuses.insert(member_id.clone(), calibration.calibration_status);
    }

    let mut blockers = Vec::new();
    if !dataset.paper_only || !experience_store.paper_only {
        blockers.push("dataset and experience store must be paper-only".to_string());
    }
    if matches!(
        leakage_check.leakage_status,
        ReplayLeakageStatus::LeakageDetected | ReplayLeakageStatus::UnsafeForTraining
    ) {
        blockers.push("blocking replay data leakage detected".to_string());
    }
    if dataset.example_count < min_examples_required {
        blockers.push(format!(
            "needs at least {min_examples_required} replay examples"
        ));
    }
    if matches!(
        coverage_eval.target_status,
        ReplayCoverageTargetStatus::BlockedByWeakLabels
    ) {
        blockers.push("weak replay labels require manual paper outcome review".to_string());
    }
    if validated_label_count == 0 {
        blockers.push("needs at least one validated paper/backtest label".to_string());
    }
    if validated_label_ratio < min_validated_label_ratio_required {
        blockers.push(format!(
            "validated label ratio below {:.2}",
            min_validated_label_ratio_required
        ));
    }
    if rejected_label_count > 0 {
        blockers.push("rejected replay labels remain in dataset".to_string());
    }
    for (member_id, count) in &per_member_counts {
        if *count < per_member_min_examples_required {
            blockers.push(format!(
                "{member_id} needs at least {per_member_min_examples_required} examples"
            ));
        }
    }

    let mut recommended_next_data = recommended_next_data_for(dataset, experience_store);
    if dataset.example_count < min_examples_required {
        recommended_next_data.push(RecommendedNextData::MoreSymbols);
    }
    if risk_eval.total_vetoes < per_member_min_examples_required {
        recommended_next_data.push(RecommendedNextData::MoreRiskVetoCases);
    }
    recommended_next_data.sort();
    recommended_next_data.dedup();

    let readiness_status = if !dataset.paper_only || !experience_store.paper_only {
        OfflineTrainingReadinessStatus::BlockedBySafety
    } else if matches!(
        leakage_check.leakage_status,
        ReplayLeakageStatus::LeakageDetected | ReplayLeakageStatus::UnsafeForTraining
    ) {
        OfflineTrainingReadinessStatus::BlockedByLeakage
    } else if dataset.example_count < min_examples_required
        || per_member_counts
            .values()
            .any(|count| *count < per_member_min_examples_required)
        || matches!(
            coverage_eval.target_status,
            ReplayCoverageTargetStatus::BlockedByWeakLabels
        )
        || validated_label_count == 0
        || validated_label_ratio < min_validated_label_ratio_required
        || rejected_label_count > 0
    {
        OfflineTrainingReadinessStatus::NeedsMoreData
    } else if matches!(
        quality_summary.quality_status,
        ReplayQualityStatus::ReadyWithWarnings | ReplayQualityStatus::NeedsMoreData
    ) || member_calibration_statuses.values().any(|status| {
        !matches!(
            status,
            MemberCalibrationEvalStatus::WellCalibrated
                | MemberCalibrationEvalStatus::InsufficientData
        )
    }) || !matches!(
        risk_eval.risk_alignment_status,
        RiskAlignmentStatus::Aligned
    ) {
        OfflineTrainingReadinessStatus::ReadyWithWarnings
    } else {
        OfflineTrainingReadinessStatus::ReadyForOfflineTraining
    };

    let coverage_target_status = coverage_eval.target_status;
    let coverage_matrix = coverage_eval.coverage_matrix.clone();
    let remaining_coverage_gaps = coverage_eval.gaps.clone();
    let collection_queue_size = coverage_eval.coverage_gap_count;
    let replay_coverage_matrix_summary = ReplayCoverageMatrixSummary {
        dataset_id: coverage_matrix.dataset_id.clone(),
        total_examples: coverage_matrix.total_examples,
        sparse_gap_count: remaining_coverage_gaps.len(),
        coverage_status: coverage_matrix.coverage_status,
        weak_label_count: coverage_matrix.weak_label_count,
        paper_only: true,
    };

    OfflineTrainingReadinessGate {
        dataset_id: dataset.dataset_id.clone(),
        dataset_quality_status: quality_summary.quality_status,
        leakage_status: leakage_check.leakage_status,
        member_calibration_statuses,
        risk_alignment_status: risk_eval.risk_alignment_status,
        min_examples_required,
        actual_example_count: dataset.example_count,
        per_member_min_examples_required,
        per_member_counts,
        ready_for_offline_training: matches!(
            readiness_status,
            OfflineTrainingReadinessStatus::ReadyForOfflineTraining
                | OfflineTrainingReadinessStatus::ReadyWithWarnings
                | OfflineTrainingReadinessStatus::ReadyForOfflineTrainingDesign
                | OfflineTrainingReadinessStatus::ReadyWithWarningsForOfflineTrainingDesign
        ) && validated_label_ratio
            >= min_validated_label_ratio_required
            && rejected_label_count == 0,
        readiness_status,
        blockers,
        recommended_next_data,
        coverage_target_status,
        label_source_status,
        replay_coverage_matrix_summary,
        coverage_matrix,
        remaining_coverage_gaps,
        collection_queue_size,
        validated_label_ratio_after_evidence: validated_label_ratio,
        promoted_by_paper_evidence_count: 0,
        unmatched_evidence_count: 0,
        ambiguous_evidence_count: 0,
        rejected_evidence_count: 0,
        validated_label_count,
        weak_label_count,
        rejected_label_count,
        label_promotion_status,
        backtest_contract_status: None,
        validated_label_ratio,
        min_validated_label_ratio_required,
        training_included_example_count: 0,
        excluded_weak_label_count: 0,
        weak_labels_remaining: weak_label_count,
        weak_labels_required_for_coverage: matches!(
            coverage_target_status,
            ReplayCoverageTargetStatus::BlockedByWeakLabels
        ),
        offline_training_design_status: offline_training_design_status_for_readiness(
            readiness_status,
        ),
        paper_only: true,
    }
}

pub fn build_member_improvement_plan(
    member_calibration_eval: &MemberCalibrationEval,
    readiness_gate: &OfflineTrainingReadinessGate,
) -> MemberImprovementPlan {
    let mut suggested_behavior_adjustments = Vec::new();
    let mut data_collection_needs = Vec::new();
    let replay_sampling_priority = match member_calibration_eval.calibration_status {
        MemberCalibrationEvalStatus::Overconfident => {
            suggested_behavior_adjustments
                .push("lower confidence on high-volatility or weak-evidence setups".to_string());
            data_collection_needs.push(RecommendedNextData::MoreNegativeOutcomes);
            data_collection_needs.push(RecommendedNextData::MoreRiskVetoCases);
            "high".to_string()
        }
        MemberCalibrationEvalStatus::Underconfident => {
            suggested_behavior_adjustments
                .push("raise confidence only after repeated paper-positive evidence".to_string());
            data_collection_needs.push(RecommendedNextData::MorePositiveOutcomes);
            "medium".to_string()
        }
        MemberCalibrationEvalStatus::NeedsMoreEvidence => {
            suggested_behavior_adjustments
                .push("raise evidence threshold before proposing paper actions".to_string());
            data_collection_needs.push(RecommendedNextData::MoreNeedMoreEvidenceCases);
            "medium".to_string()
        }
        MemberCalibrationEvalStatus::InsufficientData => {
            suggested_behavior_adjustments
                .push("collect more member-specific paper replay examples".to_string());
            data_collection_needs.push(RecommendedNextData::MoreSymbols);
            "medium".to_string()
        }
        MemberCalibrationEvalStatus::WellCalibrated => {
            suggested_behavior_adjustments.push("keep current paper-only behavior".to_string());
            "normal".to_string()
        }
    };
    data_collection_needs.extend(readiness_gate.recommended_next_data.iter().copied());
    data_collection_needs.sort();
    data_collection_needs.dedup();

    MemberImprovementPlan {
        member_id: member_calibration_eval.member_id.clone(),
        current_calibration_status: member_calibration_eval.calibration_status,
        suggested_behavior_adjustments,
        data_collection_needs,
        replay_sampling_priority,
        core_v2_notes: MemberImprovementCoreV2Notes {
            temporal_core_notes: vec![
                "Mamba3 temporal core remains deferred until replay data passes readiness gate"
                    .to_string(),
            ],
            memory_core_notes: vec![
                "Gated DeltaNet memory updates remain offline replay targets only".to_string(),
            ],
            event_attention_notes: vec![
                "Sparse Event Attention should focus on veto, volatility, and evidence-gap cases"
                    .to_string(),
            ],
            calibration_head_notes: vec![
                "calibration head needs validated confidence/outcome labels before training"
                    .to_string(),
            ],
            risk_head_notes: vec![
                "risk head should learn only from paper Risk Governor alignment data".to_string(),
            ],
            uncertainty_head_notes: vec![
                "uncertainty head remains deferred until missing-data coverage improves"
                    .to_string(),
            ],
        },
        paper_only: true,
    }
}

pub fn run_replay_quality_evaluation(
    experience_store: &MemberExperienceStore,
    replay_dataset: &ReplayDataset,
) -> ReplayQualityEvalResult {
    run_replay_quality_evaluation_with_thresholds(experience_store, replay_dataset, 10, 2)
}

pub fn run_replay_quality_evaluation_with_thresholds(
    experience_store: &MemberExperienceStore,
    replay_dataset: &ReplayDataset,
    min_examples_required: usize,
    per_member_min_examples_required: usize,
) -> ReplayQualityEvalResult {
    run_replay_quality_evaluation_with_label_ratio_threshold(
        experience_store,
        replay_dataset,
        min_examples_required,
        per_member_min_examples_required,
        default_min_validated_label_ratio_required(),
    )
}

pub fn run_replay_quality_evaluation_with_label_ratio_threshold(
    experience_store: &MemberExperienceStore,
    replay_dataset: &ReplayDataset,
    min_examples_required: usize,
    per_member_min_examples_required: usize,
    min_validated_label_ratio_required: f64,
) -> ReplayQualityEvalResult {
    let quality_summary = evaluate_replay_dataset_quality(replay_dataset);
    let leakage_check = check_replay_data_leakage(replay_dataset);
    let risk_governor_alignment_eval = evaluate_risk_governor_alignment(experience_store);
    let mut member_ids: Vec<String> = experience_store
        .records
        .iter()
        .map(|record| record.member_id.clone())
        .collect();
    member_ids.sort();
    member_ids.dedup();
    let member_calibration_evals: Vec<MemberCalibrationEval> = member_ids
        .iter()
        .map(|member_id| evaluate_member_calibration(&experience_store.records, member_id))
        .collect();
    let offline_training_readiness_gate =
        evaluate_offline_training_readiness_with_label_ratio_threshold(
            replay_dataset,
            experience_store,
            min_examples_required,
            per_member_min_examples_required,
            min_validated_label_ratio_required,
        );
    let member_improvement_plans = member_calibration_evals
        .iter()
        .map(|eval| build_member_improvement_plan(eval, &offline_training_readiness_gate))
        .collect();

    ReplayQualityEvalResult {
        quality_summary,
        leakage_check,
        member_calibration_evals,
        risk_governor_alignment_eval,
        offline_training_readiness_gate,
        member_improvement_plans,
        safety_summary: safety_summary(),
        paper_only: true,
    }
}

fn increment_count(map: &mut std::collections::BTreeMap<String, usize>, key: String) {
    *map.entry(key).or_insert(0) += 1;
}

fn confidence_bucket_for_label(label: MemberLearningLabel) -> &'static str {
    match label {
        MemberLearningLabel::Reinforce | MemberLearningLabel::CalibrateUp => "high",
        MemberLearningLabel::Penalize
        | MemberLearningLabel::CalibrateDown
        | MemberLearningLabel::NeedMoreEvidence => "low",
        MemberLearningLabel::Keep => "medium",
    }
}

fn inspect_replay_feature_for_leakage(
    example: &ReplayExample,
    section: ReplaySection,
    field_name: &str,
    value: &str,
    findings: &mut Vec<ReplayLeakageFinding>,
) {
    let lower = value.to_ascii_lowercase();
    for (needle, issue_type, severity, note) in [
        (
            "future outcome",
            ReplayLeakageIssueType::FutureOutcomeInInput,
            ReplayLeakageSeverity::Blocking,
            "future outcome text must not be an input feature",
        ),
        (
            "paperpositive",
            ReplayLeakageIssueType::FutureOutcomeInInput,
            ReplayLeakageSeverity::Blocking,
            "outcome label appears copied into input features",
        ),
        (
            "papernegative",
            ReplayLeakageIssueType::FutureOutcomeInInput,
            ReplayLeakageSeverity::Blocking,
            "outcome label appears copied into input features",
        ),
        (
            "chairman",
            ReplayLeakageIssueType::ChairmanDecisionInInput,
            ReplayLeakageSeverity::Blocking,
            "chairman decision context belongs outside replay input features",
        ),
        (
            "riskveto",
            ReplayLeakageIssueType::RiskVetoInInput,
            ReplayLeakageSeverity::Blocking,
            "risk veto result belongs in target/context, not input features",
        ),
        (
            "risk veto",
            ReplayLeakageIssueType::RiskVetoInInput,
            ReplayLeakageSeverity::Blocking,
            "risk veto result belongs in target/context, not input features",
        ),
        (
            "risk_veto",
            ReplayLeakageIssueType::RiskVetoInInput,
            ReplayLeakageSeverity::Blocking,
            "risk veto result belongs in target/context, not input features",
        ),
        (
            "target label",
            ReplayLeakageIssueType::LabelCopiedIntoFeatures,
            ReplayLeakageSeverity::Blocking,
            "target labels must not be copied into input features",
        ),
        (
            "broker",
            ReplayLeakageIssueType::BrokerAccountFieldDetected,
            ReplayLeakageSeverity::Blocking,
            "broker/account/order fields are forbidden",
        ),
        (
            "account",
            ReplayLeakageIssueType::BrokerAccountFieldDetected,
            ReplayLeakageSeverity::Blocking,
            "broker/account/order fields are forbidden",
        ),
        (
            "order",
            ReplayLeakageIssueType::BrokerAccountFieldDetected,
            ReplayLeakageSeverity::Blocking,
            "broker/account/order fields are forbidden",
        ),
        (
            "real pnl",
            ReplayLeakageIssueType::RealTradeFieldDetected,
            ReplayLeakageSeverity::Blocking,
            "real PnL fields are forbidden in paper replay input",
        ),
    ] {
        let allowed_post_decision_signal = section == ReplaySection::PostDecisionContext
            && matches!(
                issue_type,
                ReplayLeakageIssueType::ChairmanDecisionInInput
                    | ReplayLeakageIssueType::RiskVetoInInput
                    | ReplayLeakageIssueType::FutureOutcomeInInput
                    | ReplayLeakageIssueType::LabelCopiedIntoFeatures
            );
        if lower.contains(needle) && !allowed_post_decision_signal {
            findings.push(ReplayLeakageFinding {
                replay_id: example.replay_id.clone(),
                member_id: example.member_id.clone(),
                section,
                issue_type,
                field_name: field_name.to_string(),
                severity,
                note: note.to_string(),
            });
        }
    }
}

fn is_bad_member_outcome(outcome: MemberExperienceOutcome) -> bool {
    matches!(
        outcome,
        MemberExperienceOutcome::PaperNegative
            | MemberExperienceOutcome::BadRiskCall
            | MemberExperienceOutcome::MissedOpportunity
    )
}

fn is_good_member_outcome(outcome: MemberExperienceOutcome) -> bool {
    matches!(
        outcome,
        MemberExperienceOutcome::PaperPositive
            | MemberExperienceOutcome::RiskVetoSavedLoss
            | MemberExperienceOutcome::HelpfulDissent
    )
}

fn ratio(numerator: usize, denominator: usize) -> f64 {
    if denominator == 0 {
        0.0
    } else {
        numerator as f64 / denominator as f64
    }
}

fn recommended_next_data_for(
    dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
) -> Vec<RecommendedNextData> {
    let mut recommendations = Vec::new();
    let positive = dataset
        .examples
        .iter()
        .filter(|example| {
            matches!(
                example.target.outcome_label,
                MemberExperienceOutcome::PaperPositive
            )
        })
        .count();
    let negative = dataset
        .examples
        .iter()
        .filter(|example| {
            matches!(
                example.target.outcome_label,
                MemberExperienceOutcome::PaperNegative | MemberExperienceOutcome::BadRiskCall
            )
        })
        .count();
    let need_more_evidence = dataset
        .examples
        .iter()
        .filter(|example| {
            matches!(
                example.target.confidence_calibration,
                MemberLearningLabel::NeedMoreEvidence
            )
        })
        .count();
    if positive == 0 {
        recommendations.push(RecommendedNextData::MorePositiveOutcomes);
    }
    if negative == 0 {
        recommendations.push(RecommendedNextData::MoreNegativeOutcomes);
    }
    if need_more_evidence == 0 {
        recommendations.push(RecommendedNextData::MoreNeedMoreEvidenceCases);
    }
    if dataset.market_scope_count() < 3 {
        recommendations.push(RecommendedNextData::MoreMarketScopes);
    }
    if dataset.symbol_count() < 5 {
        recommendations.push(RecommendedNextData::MoreSymbols);
    }
    if !experience_store.records.iter().any(|record| {
        matches!(
            record.market_scope,
            MarketScope::KoreaLongTerm | MarketScope::UsLongTerm | MarketScope::CryptoLongTerm
        )
    }) {
        recommendations.push(RecommendedNextData::MoreLongHorizonCases);
    }
    if !experience_store.records.iter().any(|record| {
        matches!(
            record.market_scope,
            MarketScope::CryptoShortTerm | MarketScope::CryptoLongTerm
        ) && record.member_opinion.risk_hint >= 0.7
    }) {
        recommendations.push(RecommendedNextData::MoreCryptoVolatilityCases);
    }
    recommendations
}

impl ReplayDataset {
    fn market_scope_count(&self) -> usize {
        let mut scopes: Vec<MarketScope> = self
            .examples
            .iter()
            .map(|example| example.market_scope)
            .collect();
        scopes.sort();
        scopes.dedup();
        scopes.len()
    }

    fn symbol_count(&self) -> usize {
        let mut symbols: Vec<String> = self
            .examples
            .iter()
            .map(|example| example.symbol.clone())
            .collect();
        symbols.sort();
        symbols.dedup();
        symbols.len()
    }
}

pub fn build_smart_core_v2_specs_for_members(
    members: &[AICommitteeMember],
) -> Vec<SmartMemberCoreV2Spec> {
    members
        .iter()
        .filter(|member| !matches!(member.status, AICommitteeMemberStatus::Disabled))
        .map(|member| SmartMemberCoreV2Spec {
            member_id: member.member_id.clone(),
            base_core_spec: Mamba3GatedDeltaNetCoreSpec::runtime_deferred_for(&member.member_id),
            core_family: SmartCoreV2Family::Mamba3GatedDeltaNetSparseEvent,
            temporal_core: SmartCoreV2ComponentStatus::Mamba3Deferred,
            memory_core: SmartCoreV2ComponentStatus::GatedDeltaNetDeferred,
            event_attention_core: SmartCoreV2ComponentStatus::SparseEventAttentionDeferred,
            heads: SmartCoreV2Heads {
                stance_head: SmartCoreV2ComponentStatus::Deferred,
                expected_return_head: SmartCoreV2ComponentStatus::Deferred,
                risk_head: SmartCoreV2ComponentStatus::Deferred,
                uncertainty_head: SmartCoreV2ComponentStatus::Deferred,
                calibration_head: SmartCoreV2ComponentStatus::Deferred,
            },
            replay_dataset_ready: false,
            runtime_status: CoreRuntimeStatus::RuntimeDeferred,
            learning_status: SmartCoreV2LearningStatus::ExperienceCollectionOnly,
            notes: vec![
                "Smart Core v2 contract only; no training or live inference".to_string(),
                "member independence preserved by per-member replay records".to_string(),
            ],
        })
        .collect()
}

fn empty_replay_dataset(store_id: &str) -> ReplayDataset {
    ReplayDataset {
        dataset_id: format!("replay-dataset-{store_id}"),
        examples: Vec::new(),
        member_count: 0,
        example_count: 0,
        generated_from_store_id: store_id.to_string(),
        paper_only: true,
    }
}

fn validate_member_experience_path(path: &Path, label: &str) -> Result<(), String> {
    if !local_only(&path.to_string_lossy()) {
        return Err(format!("{label} must be local"));
    }
    if path_has_parent_component(path) {
        return Err(format!(
            "{label} must not contain parent-directory traversal"
        ));
    }
    Ok(())
}

fn memory_state_summary(memory: &MemberMemoryState) -> String {
    format!(
        "opinions={} events={} good={} bad={} risk_veto={}",
        memory.recent_opinion_count,
        memory.recent_event_count,
        memory.recent_good_call_count,
        memory.recent_bad_call_count,
        memory.recent_risk_veto_count
    )
}

fn member_experience_outcome(
    update_reason: MemberScoreUpdateReason,
    decision: Option<&ChairmanDecision>,
    paper_outcome_feedback: Option<&PaperOutcomeFeedback>,
) -> MemberExperienceOutcome {
    match update_reason {
        MemberScoreUpdateReason::GoodCall => MemberExperienceOutcome::PaperPositive,
        MemberScoreUpdateReason::BadCall => MemberExperienceOutcome::PaperNegative,
        MemberScoreUpdateReason::RiskyCall => MemberExperienceOutcome::BadRiskCall,
        MemberScoreUpdateReason::HelpfulDissent => {
            if decision
                .is_some_and(|decision| decision.risk_governor_status == RiskGovernorStatus::Vetoed)
            {
                MemberExperienceOutcome::RiskVetoSavedLoss
            } else {
                MemberExperienceOutcome::HelpfulDissent
            }
        }
        MemberScoreUpdateReason::LowEvidence => MemberExperienceOutcome::MissedOpportunity,
        MemberScoreUpdateReason::Neutral => paper_outcome_feedback
            .map(|feedback| match feedback.simulated_result {
                SimulatedPaperOutcome::Positive => MemberExperienceOutcome::PaperPositive,
                SimulatedPaperOutcome::Negative => MemberExperienceOutcome::PaperNegative,
                SimulatedPaperOutcome::Neutral => MemberExperienceOutcome::PaperNeutral,
                SimulatedPaperOutcome::Unknown => MemberExperienceOutcome::Unknown,
            })
            .unwrap_or(MemberExperienceOutcome::Unknown),
    }
}

fn member_learning_label_for(
    update_reason: MemberScoreUpdateReason,
    outcome: MemberExperienceOutcome,
) -> MemberLearningLabel {
    match update_reason {
        MemberScoreUpdateReason::GoodCall | MemberScoreUpdateReason::HelpfulDissent => {
            MemberLearningLabel::Reinforce
        }
        MemberScoreUpdateReason::BadCall | MemberScoreUpdateReason::RiskyCall => {
            MemberLearningLabel::CalibrateDown
        }
        MemberScoreUpdateReason::LowEvidence => MemberLearningLabel::NeedMoreEvidence,
        MemberScoreUpdateReason::Neutral => match outcome {
            MemberExperienceOutcome::PaperPositive => MemberLearningLabel::CalibrateUp,
            MemberExperienceOutcome::PaperNegative | MemberExperienceOutcome::BadRiskCall => {
                MemberLearningLabel::Penalize
            }
            _ => MemberLearningLabel::Keep,
        },
    }
}

fn replay_filter_matches(record: &MemberExperienceRecord, filter: &ReplayDatasetFilter) -> bool {
    if let Some(member_id) = &filter.member_id {
        if &record.member_id != member_id {
            return false;
        }
    }
    if let Some(market_scope) = filter.market_scope {
        if record.market_scope != market_scope {
            return false;
        }
    }
    if let Some(symbol) = &filter.symbol {
        if &record.symbol != symbol {
            return false;
        }
    }
    if let Some(min_confidence) = filter.min_confidence {
        if record.member_opinion.confidence < min_confidence {
            return false;
        }
    }
    if !filter.include_outcomes.is_empty() && !filter.include_outcomes.contains(&record.outcome) {
        return false;
    }
    if filter.exclude_low_confidence_review_required
        && matches!(record.learning_label, MemberLearningLabel::NeedMoreEvidence)
        && record.member_opinion.confidence < 0.5
    {
        return false;
    }
    true
}

fn evidence_label_for(record: &MemberExperienceRecord) -> String {
    if matches!(record.learning_label, MemberLearningLabel::NeedMoreEvidence) {
        "insufficient_evidence".to_string()
    } else if record.member_opinion.evidence_notes.is_empty() {
        "no_notes".to_string()
    } else {
        "has_member_notes".to_string()
    }
}

fn replay_sample_weight(record: &MemberExperienceRecord) -> f64 {
    match record.learning_label {
        MemberLearningLabel::Reinforce => 1.2,
        MemberLearningLabel::Penalize | MemberLearningLabel::CalibrateDown => 1.5,
        MemberLearningLabel::NeedMoreEvidence => 1.1,
        MemberLearningLabel::CalibrateUp | MemberLearningLabel::Keep => 1.0,
    }
}

fn produce_mock_opinion(member: &AICommitteeMember, packet: &MemberInputPacket) -> MemberOpinion {
    let market = &packet.market_data;
    let sentiment = combined_sentiment(&packet.news);
    let style = member.style_profile.to_ascii_lowercase();
    let mut stance = MemberStance::Hold;
    let mut confidence: f64 = 0.52;
    let mut expected_return_hint = market.change_pct / 100.0;
    let mut risk_hint = clamp_unit(market.volatility_hint);
    let mut notes = vec![
        format!("style={}", member.style_profile),
        "deterministic mock opinion; not model inference".to_string(),
    ];
    let mut event_triggered = false;
    let mut event_reason = None;

    if style.contains("risk") && market.volatility_hint >= 0.08 {
        stance = MemberStance::NoTrade;
        confidence = 0.82;
        expected_return_hint = 0.0;
        risk_hint = clamp_unit(market.volatility_hint + 0.2);
        event_triggered = true;
        event_reason = Some("high volatility risk warning".to_string());
        notes.push("risk-style member raised volatility warning".to_string());
    } else if style.contains("evidence") && sentiment == "unknown" {
        stance = MemberStance::NeedMoreEvidence;
        confidence = 0.7;
        expected_return_hint = 0.0;
        risk_hint = clamp_unit(market.volatility_hint + 0.1);
        event_triggered = true;
        event_reason = Some("news sentiment unknown".to_string());
        notes.push("evidence-style member requested more evidence".to_string());
    } else if style.contains("trend") && market.change_pct > 3.0 && sentiment == "positive" {
        stance = MemberStance::BuyProposal;
        confidence = 0.78;
        expected_return_hint = 0.035;
        risk_hint = clamp_unit(market.volatility_hint);
        event_triggered = true;
        event_reason = Some("positive momentum and news".to_string());
        notes.push("trend-style member proposed paper entry".to_string());
    } else if style.contains("value")
        && matches!(
            market.market_scope,
            MarketScope::KoreaLongTerm | MarketScope::UsLongTerm
        )
        && market.volatility_hint <= 0.04
        && sentiment != "negative"
    {
        stance = MemberStance::BuyProposal;
        confidence = 0.66;
        expected_return_hint = 0.02;
        risk_hint = clamp_unit(market.volatility_hint);
        event_triggered = true;
        event_reason = Some("long-term low-volatility setup".to_string());
        notes.push("value-style member proposed paper entry".to_string());
    } else if style.contains("liquidity")
        && matches!(
            market.market_scope,
            MarketScope::CryptoShortTerm | MarketScope::CryptoLongTerm
        )
        && market.volatility_hint >= 0.07
    {
        stance = MemberStance::NoTrade;
        confidence = 0.74;
        expected_return_hint = 0.0;
        risk_hint = clamp_unit(market.volatility_hint + 0.15);
        event_triggered = true;
        event_reason = Some("crypto liquidity volatility warning".to_string());
        notes.push("liquidity-style member warned against crypto risk".to_string());
    }

    MemberOpinion {
        member_id: member.member_id.clone(),
        symbol: market.symbol.clone(),
        market_scope: market.market_scope,
        stance,
        confidence: clamp_unit(confidence),
        expected_return_hint,
        risk_hint,
        evidence_notes: notes,
        event_triggered,
        event_reason,
    }
}

fn combined_sentiment(news: &[NewsSnapshot]) -> &'static str {
    if news
        .iter()
        .any(|item| item.sentiment_hint.eq_ignore_ascii_case("positive"))
    {
        "positive"
    } else if news
        .iter()
        .any(|item| item.sentiment_hint.eq_ignore_ascii_case("negative"))
    {
        "negative"
    } else {
        "unknown"
    }
}

fn select_event(
    market: &MarketDataSnapshot,
    opinions: &[MemberOpinion],
) -> Option<InvestmentEvent> {
    let triggering_opinion = opinions
        .iter()
        .filter(|opinion| {
            opinion.event_triggered && matches!(opinion.stance, MemberStance::BuyProposal)
        })
        .max_by(|left, right| {
            left.confidence
                .partial_cmp(&right.confidence)
                .unwrap_or(std::cmp::Ordering::Equal)
        })
        .or_else(|| {
            opinions
                .iter()
                .filter(|opinion| opinion.event_triggered)
                .max_by(|left, right| {
                    left.confidence
                        .partial_cmp(&right.confidence)
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
        })?
        .clone();
    let event_type = match triggering_opinion.stance {
        MemberStance::BuyProposal => InvestmentEventType::EntryProposal,
        MemberStance::SellProposal => InvestmentEventType::ExitProposal,
        MemberStance::NoTrade => InvestmentEventType::RiskWarning,
        MemberStance::NeedMoreEvidence => InvestmentEventType::NeedMoreEvidence,
        MemberStance::Hold => InvestmentEventType::NeedMoreEvidence,
    };
    Some(InvestmentEvent {
        event_id: format!(
            "event-{}-{}-{}",
            market.symbol, market.timestamp, triggering_opinion.member_id
        ),
        proposed_by_member_id: triggering_opinion.member_id.clone(),
        symbol: market.symbol.clone(),
        market_scope: market.market_scope,
        event_type,
        triggering_opinion,
        created_at: market.timestamp.clone(),
    })
}

fn build_committee_session(
    market: &MarketDataSnapshot,
    event: InvestmentEvent,
    members: &[AICommitteeMember],
    opinions: &[MemberOpinion],
) -> CommitteeSession {
    let buy_count = opinions
        .iter()
        .filter(|opinion| matches!(opinion.stance, MemberStance::BuyProposal))
        .count();
    let defensive_count = opinions
        .iter()
        .filter(|opinion| {
            matches!(
                opinion.stance,
                MemberStance::NoTrade | MemberStance::NeedMoreEvidence
            )
        })
        .count();
    let total = opinions.len().max(1) as f64;
    let mut risk_flags = Vec::new();
    if market.volatility_hint >= 0.08 {
        risk_flags.push("high_volatility".to_string());
    }
    if opinions
        .iter()
        .any(|opinion| matches!(opinion.stance, MemberStance::NoTrade))
    {
        risk_flags.push("member_no_trade_warning".to_string());
    }
    CommitteeSession {
        session_id: format!("session-{}", event.event_id),
        event,
        invited_members: members
            .iter()
            .map(|member| member.member_id.clone())
            .collect(),
        member_opinions: opinions.to_vec(),
        disagreement_level: ((buy_count as f64 - defensive_count as f64).abs() / total)
            .mul_add(-1.0, 1.0)
            .clamp(0.0, 1.0),
        risk_flags,
    }
}

fn synthesize_chairman_decision(
    session: &CommitteeSession,
    risk_veto_volatility_threshold: f64,
) -> ChairmanDecision {
    let weighted_buy: f64 = session
        .member_opinions
        .iter()
        .filter(|opinion| matches!(opinion.stance, MemberStance::BuyProposal))
        .map(|opinion| opinion.confidence)
        .sum();
    let weighted_defensive: f64 = session
        .member_opinions
        .iter()
        .filter(|opinion| {
            matches!(
                opinion.stance,
                MemberStance::NoTrade | MemberStance::NeedMoreEvidence
            )
        })
        .map(|opinion| opinion.confidence)
        .sum();
    let vetoed = session
        .risk_flags
        .iter()
        .any(|flag| flag == "high_volatility")
        && session
            .member_opinions
            .iter()
            .any(|opinion| opinion.risk_hint >= risk_veto_volatility_threshold);

    let (final_action, risk_governor_status, rationale) = if vetoed {
        (
            ChairmanFinalAction::RiskVetoed,
            RiskGovernorStatus::Vetoed,
            "Risk Governor vetoed high-volatility paper proposal".to_string(),
        )
    } else if weighted_buy > weighted_defensive && weighted_buy >= 0.65 {
        (
            ChairmanFinalAction::PaperBuy,
            RiskGovernorStatus::Passed,
            "Chairman synthesized weighted member opinions into paper buy only".to_string(),
        )
    } else if weighted_defensive > weighted_buy {
        (
            ChairmanFinalAction::PaperNoTrade,
            RiskGovernorStatus::NeedsReview,
            "Defensive or low-evidence opinions outweighed entry proposal".to_string(),
        )
    } else {
        (
            ChairmanFinalAction::NeedMoreEvidence,
            RiskGovernorStatus::NeedsReview,
            "Committee needs more evidence before a paper-only decision".to_string(),
        )
    };

    ChairmanDecision {
        decision_id: format!("decision-{}", session.session_id),
        session_id: session.session_id.clone(),
        final_action,
        rationale,
        winning_arguments: session
            .member_opinions
            .iter()
            .filter(|opinion| match final_action {
                ChairmanFinalAction::RiskVetoed => {
                    matches!(opinion.stance, MemberStance::NoTrade)
                }
                ChairmanFinalAction::PaperBuy => {
                    matches!(opinion.stance, MemberStance::BuyProposal)
                }
                _ => matches!(
                    opinion.stance,
                    MemberStance::NoTrade | MemberStance::NeedMoreEvidence
                ),
            })
            .map(|opinion| format!("{}:{:?}", opinion.member_id, opinion.stance))
            .collect(),
        dissenting_arguments: session
            .member_opinions
            .iter()
            .filter(|opinion| match final_action {
                ChairmanFinalAction::RiskVetoed => {
                    matches!(opinion.stance, MemberStance::BuyProposal)
                }
                ChairmanFinalAction::PaperBuy => {
                    !matches!(opinion.stance, MemberStance::BuyProposal)
                }
                _ => matches!(opinion.stance, MemberStance::BuyProposal),
            })
            .map(|opinion| format!("{}:{:?}", opinion.member_id, opinion.stance))
            .collect(),
        risk_governor_status,
    }
}

fn score_update_for(
    member: &AICommitteeMember,
    opinion: &MemberOpinion,
    decision: Option<&ChairmanDecision>,
    simulated_outcome_return: Option<f64>,
) -> MemberScoreUpdate {
    let update_reason = match decision.map(|decision| decision.final_action) {
        Some(ChairmanFinalAction::RiskVetoed)
            if matches!(opinion.stance, MemberStance::NoTrade) =>
        {
            MemberScoreUpdateReason::HelpfulDissent
        }
        Some(ChairmanFinalAction::RiskVetoed)
            if matches!(opinion.stance, MemberStance::BuyProposal) =>
        {
            MemberScoreUpdateReason::RiskyCall
        }
        Some(ChairmanFinalAction::PaperBuy)
            if matches!(opinion.stance, MemberStance::BuyProposal)
                && simulated_outcome_return.unwrap_or(0.0) > 0.0 =>
        {
            MemberScoreUpdateReason::GoodCall
        }
        Some(ChairmanFinalAction::PaperBuy)
            if matches!(opinion.stance, MemberStance::BuyProposal) =>
        {
            MemberScoreUpdateReason::BadCall
        }
        Some(ChairmanFinalAction::NeedMoreEvidence)
            if matches!(opinion.stance, MemberStance::NeedMoreEvidence) =>
        {
            MemberScoreUpdateReason::LowEvidence
        }
        _ => MemberScoreUpdateReason::Neutral,
    };
    let delta = match update_reason {
        MemberScoreUpdateReason::GoodCall | MemberScoreUpdateReason::HelpfulDissent => 0.04,
        MemberScoreUpdateReason::BadCall | MemberScoreUpdateReason::RiskyCall => -0.05,
        MemberScoreUpdateReason::LowEvidence => -0.01,
        MemberScoreUpdateReason::Neutral => 0.0,
    };
    let new_score = clamp_unit(member.score + delta);
    let new_voice_weight = clamp_unit(member.voice_weight + delta / 2.0);
    MemberScoreUpdate {
        member_id: member.member_id.clone(),
        previous_score: member.score,
        new_score,
        previous_voice_weight: member.voice_weight,
        new_voice_weight,
        update_reason,
        promoted: member.score < 0.8 && new_score >= 0.8,
        demoted: member.score >= 0.3 && new_score < 0.3,
    }
}

fn safety_summary() -> MinimalCommitteeSafetySummary {
    MinimalCommitteeSafetySummary {
        paper_only: true,
        no_real_order_path: true,
        no_broker_order_account: true,
        no_model_training: true,
        no_weight_update: true,
        no_checkpoint: true,
        no_live_inference: true,
        runtime_mode: "LocalMockOrOfflineFixtureOnly".to_string(),
        notes: vec![
            "program orchestrates; AI members analyze through local mock or offline fixture logic"
                .to_string(),
            "no live trading, broker, order, account, training, weight update, checkpoint, or live inference path".to_string(),
        ],
    }
}
